insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('toscana','IT','Toscana','Toscana','Renacimiento, colinas y termas libres','{"mar":0,"montana":1,"ciudad":3,"campo":3,"fiesta":1,"calma":2,"cultura":3,"gastronomia":3,"naturaleza":2,"playa":0,"aventura":1,"postal":3}'::jsonb,'alto','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11],"evitar":[8],"nota":"Primavera y otoño sin calor ni colas; agosto es muy caluroso y cierran muchos locales. En invierno las termas libres son buena idea."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Sin coche funcionan Florencia, Pisa, Siena, Lucca y San Gimignano (tren y bus). Para Val d''Orcia, Chianti y las termas libres compensa alquilar un día entre 4 o más. Los centros tienen ZTL: aparcad fuera.","aeropuerto_recogida":"PSA","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Florencia.FLR.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Florencia.FLR.HERTZ.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Florencia.FLR.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Florencia.FLR.AVIS.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Florencia.FLR.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Florencia.FLR.EUROPCAR.cla.ksp"},{"nombre":"Enterprise","enlace":"https://www.momondo.es/alquiler-de-coches/Enterprise-Florencia.FLR.ENTERPRISE.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Enterprise-Florencia.FLR.ENTERPRISE.cla.ksp"},{"nombre":"Goldcar (Pisa)","enlace":"https://www.discovercars.com/es/partners/goldcar-1630","fuente":"https://www.discovercars.com/es/partners/goldcar-1630"}]}'::jsonb,'{"aeropuertos":[{"iata":"PSA","nombre":"Pisa – Galileo Galilei","ciudad":"Pisa","a_la_base":"Tren o bus corto a Pisa centro; a Florencia, con tren regional desde Pisa Centrale."},{"iata":"FLR","nombre":"Florencia – Peretola","ciudad":"Florencia","a_la_base":"Hay conexión con el centro de Florencia; comprobad el medio en la web del aeropuerto."}],"desde_espana":"Ryanair opera Pisa desde varias ciudades españolas; Florencia tiene menos vuelos directos. Comprobad siempre fechas y frecuencias al buscar.","rutas_directas":[{"origen":"Valencia","origen_iata":"VLC","destino_iata":"PSA","aerolinea":"Ryanair","nota":"comprobad si opera en vuestras fechas","fuente":"https://www.ryanair.com/gb/en/flights/flights-from-pisa-to-valencia-vlc"},{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"PSA","aerolinea":"Ryanair","nota":"comprobad si opera en vuestras fechas","fuente":"https://www.opodo.es/vuelos/aerolinea/FR/ryanair/PSA/pisa/BCN/barcelona/"},{"origen":"Madrid","origen_iata":"MAD","destino_iata":"PSA","aerolinea":"Ryanair","nota":"comprobad si opera en vuestras fechas","fuente":"https://www.edreams.net/es/aerolinea/FR/ryanair/MAD/madrid/PSA/pisa/"}],"desde_italia":"Florencia está en la línea de alta velocidad entre Milán, Bolonia y Roma; desde ahí, trenes regionales a Pisa, Lucca y Siena, y FlixBus entre ciudades.","novedades":[{"nota":"El billete combinado tren+avión de iryo y ITA Airways también cubre Florencia, comprado a la vez en ita-airways.com o iryo.eu.","fuente":"https://www.elperiodic.com/viajar-entre-comunitat-valenciana-italia-nunca-facil-funciona-billete-tren-avion_1002354"}]}'::jsonb,'{"resumen":"Sin coche, tren regional entre Florencia, Pisa, Lucca y Siena (esta última mejor en bus). Con coche, Val d''Orcia y Chianti, pero cuidado con las ZTL.","tren":{"nota":"Trenitalia cubre Florencia–Pisa–Lucca; a Siena es más cómodo el bus.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Conecta ciudades de Toscana y de Italia; solo dentro de Italia.","enlace":"https://www.flixbus.it/autobus/firenze","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia; enlace a la página general del país.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Entrada oficial de la Torre de Pisa y ticket de Duomo no verificados: enlazo mapa o reserva genérica.","Fechas de 2027 de los eventos no publicadas en fuente oficial verificada.","Cinque Terre queda fuera: está en Liguria.","Sin precios exactos por política del contrato."]'::jsonb,'{"zona":"toscana","base":"florencia","ciudad_referencia":"Florencia","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":14,"max":20,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/florence/","calidad":"orientativo"},"doble_noche":{"min":50,"max":135,"fuente":"https://www.booking.com/city/it/florence.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/florence","calidad":"orientativo"},"comida_barata":{"valor":24,"fuente":"https://www.numbeo.com/cost-of-living/in/Florence","calidad":"orientativo"},"transporte_billete":{"valor":2,"fuente":"https://www.at-bus.it/en/ticket","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 15 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=6.21, maximo=100.0); son precios ''desde'' sin fechas concretas. doble_noche: min=50 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=135 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Florencia (rango Numbeo 19-30). transporte_billete: Autolinee Toscane, billete urbano ordinario (Urbano capoluogo) 2.00 EUR; a bordo 3.00; por SMS 2.40 (90 min en Florencia). La pagina no nombra Florencia explicitamente pero cubre las capitales de provincia."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('toscana','florencia','Florencia','Estación central con trenes a Pisa, Siena, Lucca y Bolonia, vida nocturna y la mayor oferta de hostels.','fiesta',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('toscana','siena','Siena','Casco medieval compacto y estudiantil, con buses a San Gimignano y Chianti; la mejor puerta a las termas y la Val d''Orcia.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('toscana','pisa','Pisa','Aeropuerto a pocos minutos y tren corto a Lucca y Florencia; ciudad universitaria más barata que Florencia.','mixto',true);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','uffizi','florencia','Galería Uffizi','Florencia','cultura',array['postal']::text[],'medio_dia','manana','medio',false,true,'bajo','mixto',null,'Botticelli, Leonardo y Caravaggio en el museo más famoso de Florencia; entrad con hora para no comer cola.','Reservad con antelación en la web oficial; evitad las webs de reventa.','https://uffizi.it/en/tickets','oficial','https://www.google.com/maps/search/?api=1&query=Galleria+degli+Uffizi%2C+Florencia%2C+Italia','https://uffizi.it/en/tickets',43.768,11.255);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','piazzale-michelangelo-san-miniato','florencia','Piazzale Michelangelo y San Miniato al Monte','Florencia','postal',array['naturaleza']::text[],'2h','noche','gratis',false,false,'medio','social',null,'Subid a pie al mirador más famoso de la ciudad para ver el atardecer sobre el Arno y seguid hasta la iglesia de San Miniato, con vistas igual de buenas y menos gente.','Llevad bebida y algo de picar de abajo, arriba todo es más caro.','https://www.visititaly.eu/places-and-tours/top-best-views-of-florence','oficial','https://www.google.com/maps/search/?api=1&query=Piazzale+Michelangelo%2C+Florencia%2C+Italia','https://www.visititaly.eu/places-and-tours/top-best-views-of-florence',43.763,11.265);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','mercato-centrale','florencia','Mercato Centrale','Florencia','gastronomia',array['compras']::text[],'2h','cualquiera','bajo',false,false,'bajo','social',null,'Mercado cubierto en San Lorenzo: abajo puestos tradicionales y arriba un food court donde cada uno pide lo que quiere sin discutir sitio.',null,'https://italia.it/en/tuscany/florence/mercato-centrale-florence','oficial','https://www.google.com/maps/search/?api=1&query=Mercato+Centrale%2C+Florencia%2C+Italia','https://italia.it/en/tuscany/florence/mercato-centrale-florence',43.777,11.253);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','sant-ambrogio','florencia','Mercado de Sant''Ambrogio','Florencia','gastronomia',array['compras']::text[],'2h','manana','bajo',false,false,'bajo','mixto',null,'Mercado de barrio donde comen los florentinos: fruta, queso y puestos de comida casera, mucho menos turístico que San Lorenzo.','Mejor por la mañana; por la tarde el mercado ya está recogido.','https://feelflorence.it/en/node/12043','oficial','https://www.google.com/maps/search/?api=1&query=Mercato+di+Sant%27Ambrogio%2C+Florencia%2C+Italia','https://feelflorence.it/en/node/12043',43.771,11.268);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','oltrarno-atardecer','florencia','Ponte Vecchio y Oltrarno al atardecer','Florencia','cultura',array['postal','fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',null,'Cruzad el Ponte Vecchio, perdeos por las calles de artesanos del Oltrarno y acabad con un aperitivo en la plaza de Santo Spirito.',null,'https://www.florencetourism.org/free-things-to-do-in-florence/','oficial','https://www.google.com/maps/search/?api=1&query=Santo+Spirito%2C+Florencia%2C+Italia','https://www.florencetourism.org/free-things-to-do-in-florence/',43.768,11.253);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','cafe-historico-florencia','florencia','Merienda en un café histórico','Florencia','gastronomia',array['cultura']::text[],'2h','tarde','medio',false,false,'bajo','tranquilo',null,'Tomad un café y un dulce en Caffè Gilli, en Piazza della Repubblica, abierto desde 1733 con decoración modernista; en barra sale más barato que sentados.',null,'https://www.visittuscany.com/it/idee/viaggio-nel-tempo-4-caffe-storici-in-toscana/','oficial','https://www.google.com/maps/search/?api=1&query=Caff%C3%A8+Gilli%2C+Piazza+della+Repubblica%2C+Florencia%2C+Italia','https://www.visittuscany.com/it/idee/viaggio-nel-tempo-4-caffe-storici-in-toscana/',43.771,11.255);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','siena-campo','siena','Piazza del Campo y Torre del Mangia','Siena','cultura',array['postal']::text[],'medio_dia','cualquiera','bajo',false,false,'medio','social',null,'Sentaos en la plaza en forma de concha, donde se corre el Palio, y subid a la Torre del Mangia o a la catedral para ver los tejados rojos.','La subida a la torre tiene aforo limitado; id pronto o mirad entrada en la web de la ciudad.','https://www.visittuscany.com/en/attractions/piazza-del-campo-siena/','oficial','https://www.google.com/maps/search/?api=1&query=Piazza+del+Campo%2C+Siena%2C+Italia','https://www.visittuscany.com/en/attractions/piazza-del-campo-siena/',43.318,11.331);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','siena-contrade-noche','siena','Siena de noche: contrade y plazas','Siena','postal',array['fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',null,'Con el centro casi vacío de excursionistas, paseo por callejones de las contrade (cada una con su fuente y su bandera) y cena o copa en el ambiente universitario.',null,'https://www.visittuscany.com/en/destinations/siena/','oficial','https://www.google.com/maps/search/?api=1&query=Contrada+della+Selva%2C+Siena%2C+Italia','https://www.visittuscany.com/en/destinations/siena/',43.318,11.331);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','san-gimignano','siena','San Gimignano, el pueblo de las torres','San Gimignano','cultura',array['postal']::text[],'medio_dia','cualquiera','bajo',false,false,'medio','mixto',null,'Pueblo medieval amurallado con torres de piedra, que se hace bien en autobús desde Siena y se ve en media jornada.','Llegad temprano o al final de la tarde; entre las 11 y las 16 se llena de grupos.','https://www.visittuscany.com/en/ideas/san-gimignano-food-and-wine-itinerary','oficial','https://www.google.com/maps/search/?api=1&query=San+Gimignano%2C+Italia','https://www.visittuscany.com/en/ideas/san-gimignano-food-and-wine-itinerary',43.468,11.043);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','pisa-miracoli','pisa','Piazza dei Miracoli y Torre de Pisa','Pisa','cultura',array['postal']::text[],'medio_dia','cualquiera','medio',false,true,'bajo','social',null,'La torre inclinada, la catedral y el baptisterio en un césped enorme; la plaza se pisa gratis y se paga solo por entrar a los monumentos.','Subir a la torre exige entrada con hora; comprad solo en la web oficial de la Opera della Primaziale.','https://www.google.com/maps/search/?api=1&query=Piazza+dei+Miracoli%2C+Pisa%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Piazza+dei+Miracoli%2C+Pisa%2C+Italia','https://visititaly.eu/tickets/tower-of-pisa',43.723,10.397);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','pisa-lungarno-noche','pisa','Lungarno y plazas universitarias de Pisa','Pisa','fiesta',array['cultura']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Pisa es ciudad de estudiantes: aperitivo junto al río Arno y copas por Piazza delle Vettovaglie y alrededores de Piazza dei Cavalieri, sede de la Scuola Normale.',null,'https://www.google.com/maps/search/?api=1&query=Piazza+delle+Vettovaglie%2C+Pisa%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Piazza+delle+Vettovaglie%2C+Pisa%2C+Italia','https://www.visittuscany.com/it/idee/viaggio-nel-tempo-4-caffe-storici-in-toscana/',43.716,10.4);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','lucca-murallas-bici','pisa','Murallas de Lucca en bici','Lucca','naturaleza',array['cultura']::text[],'medio_dia','tarde','bajo',false,false,'bajo','social',null,'Alquilad bicis y dad la vuelta a las murallas renacentistas, un anillo arbolado y llano de unos 4 km por encima del casco antiguo, con paradas en los bastiones.','Lucca se llega en tren regional desde Pisa o Florencia; las bicis se alquilan junto a las puertas de la muralla.','https://www.turismo.lucca.it/en/information/how-to-get-around/','oficial','https://www.google.com/maps/search/?api=1&query=Mura+di+Lucca%2C+Italia','https://www.turismo.lucca.it/en/information/how-to-get-around/',43.843,10.502);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','saturnia','siena','Cascate del Mulino (Saturnia)','Saturnia','bienestar',array['agua','naturaleza']::text[],'medio_dia','cualquiera','gratis',true,false,'bajo','social',null,'Pozas termales de agua sulfurosa caliente y libres, entre cascadas de travertino, en plena Maremma.','Es acceso libre y sin servicios, y se llena en fin de semana. Id entre semana, llevad chanclas y toalla, no dejéis basura y respetad cualquier aviso local. Está lejos: unas 1,5 h en coche desde Siena.','https://www.visittuscany.com/en/attractions/cascate-del-mulino-hot-springs-in-saturnia/','oficial','https://www.google.com/maps/search/?api=1&query=Cascate+del+Mulino%2C+Saturnia%2C+Italia','https://www.visittuscany.com/en/attractions/cascate-del-mulino-hot-springs-in-saturnia/',42.649,11.511);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','bagni-san-filippo','siena','Fosso Bianco (Bagni San Filippo)','Bagni San Filippo','bienestar',array['agua','naturaleza']::text[],'medio_dia','cualquiera','gratis',true,false,'medio','mixto',null,'Camino corto por el bosque hasta un arroyo caliente con formaciones calcáreas blancas, la ballena blanca, y pozas libres.','Mejor en otoño e invierno, con el agua caliente y menos gente. Llevad calzado que se pueda mojar y toalla; el acceso es libre y no hay vestuarios.','https://www.bagnisanfilippoterme.it/fosso-bianco.html','oficial','https://www.google.com/maps/search/?api=1&query=Fosso+Bianco%2C+Bagni+San+Filippo%2C+Italia','https://www.bagnisanfilippoterme.it/fosso-bianco.html',42.915,11.7);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','val-orcia','siena','Val d''Orcia: Pienza, Montepulciano y Bagno Vignoni','Val d''Orcia','naturaleza',array['postal','gastronomia']::text[],'dia_completo','manana','bajo',true,false,'medio','mixto',null,'Colinas de cipreses, pueblos de piedra y pecorino; las vistas son lo mejor, y sin coche solo se llega a algún pueblo en bus regional.','Para 4 o más, el coche de alquiler compensa mucho en este día.','https://www.italia.it/en/tuscany/siena/things-to-do/bagno-vignoni-hot-springs','oficial','https://www.google.com/maps/search/?api=1&query=Val+d%27Orcia%2C+Toscana%2C+Italia','https://visittuscany.com/en/ideas/val-dorcia-hot-baths-and-more',43.077,11.679);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('toscana','chianti-vino','florencia','Ruta del vino en el Chianti','Chianti','gastronomia',array['naturaleza']::text[],'medio_dia','tarde','medio',true,true,'bajo','social',null,'Visita y cata en una bodega del Chianti Classico, con el viñedo de fondo; reservad, porque casi todas piden cita.','Que conduzca uno que no beba; hay catas con comida incluida.','https://www.antinori.it/','oficial','https://www.google.com/maps/search/?api=1&query=Chianti+Classico%2C+Toscana%2C+Italia','https://www.visittuscany.com/en/ideas/top-10-foods-you-must-eat-in-tuscany/',43.47,11.255);
