insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('roma','IT','Roma','Roma','Ruinas, aperitivo y atardeceres gratis','{"mar":0,"montana":0,"ciudad":3,"campo":0,"fiesta":2,"calma":0,"cultura":3,"gastronomia":3,"naturaleza":0,"playa":0,"aventura":0,"postal":3}'::jsonb,'medio','{"ideales":[4,5,6,9,10],"aceptables":[3,11],"evitar":[7,8],"nota":"En julio y agosto hace mucho calor y el centro se llena; abril-junio y septiembre-octubre son lo mejor."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Dentro de Roma el coche sobra: ZTL en el centro, aparcar es caro y el metro, tranvía y tren llegan a todo. Solo compensa para salir a pueblos sin tren.","aeropuerto_recogida":"FCO","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Roma.FCO.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Roma.FCO.HERTZ.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Roma.FCO.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Roma.FCO.AVIS.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Roma.FCO.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Roma.FCO.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"FCO","nombre":"Roma – Fiumicino Leonardo da Vinci","ciudad":"Roma","a_la_base":"Tren Leonardo Express a Roma Termini en unos 32 minutos (según Trenitalia)."},{"iata":"CIA","nombre":"Roma – Ciampino","ciudad":"Roma","a_la_base":"Bus o tren regional hasta Roma Termini; comprobad horarios antes de volar de noche."}],"desde_espana":"Roma es de las rutas más baratas desde España: Ryanair y Vueling vuelan desde Barcelona y Valencia, entre otras. Comparad FCO y CIA y sumad el traslado.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"FCO","aerolinea":"Vueling","nota":"según el buscador Omio; comprobad temporada","fuente":"https://www.omio.com.ar/vuelos/aeropuerto-de-barcelona-el-prat/aeropuerto-leonardo-da-vinci-fiumicino-de-roma-vlwvl"},{"origen":"Valencia","origen_iata":"VLC","destino_iata":"CIA","aerolinea":"Ryanair","nota":"según Opodo y Momondo; comprobad temporada","fuente":"https://www.opodo.es/vuelos/aerolinea/FR/ryanair/ROM/roma/VLC/valencia/"}],"desde_italia":"Roma Termini es el nudo ferroviario de Italia: alta velocidad con Trenitalia e Italo desde Bolonia, Milán o Florencia. Mirad también FlixBus si vais con tiempo.","novedades":[{"nota":"Billete combinado tren+avión de iryo e ITA Airways: tren hasta Madrid o Barcelona y vuelo ITA a Fiumicino, en una sola compra.","fuente":"https://www.elperiodic.com/viajar-entre-comunitat-valenciana-italia-nunca-facil-funciona-billete-tren-avion_1002354"}]}'::jsonb,'{"resumen":"Centro a pie, metro y tranvía para distancias largas, y tren regional para Ostia o Castelli Romani. Sin coche.","tren":{"nota":"Trenitalia para regionales (Ostia Antica, Frascati, Tivoli) y alta velocidad con Italo.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Solo trayectos dentro de Italia y Europa, no hace falta para moverse por Roma.","enlace":"https://www.flixbus.it/autobus/roma","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["No he verificado los precios ni los horarios de ningún sitio; mirad siempre la web oficial.","El primer domingo de cada mes hay entrada gratuita en museos y parques estatales (Domenica al Museo, https://siviaggia.it/notizie/domenica-al-museo-1-novembre/607806/), pero no he confirmado qué sitios romanos se incluyen ahora.","Rutas aéreas: solo dos con fuente de buscador, no de la aerolínea; faltan Madrid y otras ciudades.","Tivoli, Appia Antica y varios enlaces de actividad son solo mapa o búsqueda."]'::jsonb,'{"zona":"roma","base":"centro","ciudad_referencia":"Roma","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":25,"max":32,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/rome/","calidad":"orientativo"},"doble_noche":{"min":55,"max":177,"fuente":"https://www.booking.com/city/it/rome.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/rome","calidad":"orientativo"},"comida_barata":{"valor":16,"fuente":"https://www.numbeo.com/cost-of-living/in/Rome","calidad":"orientativo"},"transporte_billete":{"valor":1.5,"fuente":"https://www.atac.roma.it/biglietti-e-abbonamenti","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 28 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=8.28, maximo=40.5); son precios ''desde'' sin fechas concretas. doble_noche: min=55 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=177 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Roma (rango Numbeo 12-25). transporte_billete: ATAC BIT 100 minutos, corsa singola."}'::jsonb);
