insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('napoles','IT','Nápoles y su golfo','Nápoles','Pizza, ruinas y islas sin coche','{"mar":3,"montana":1,"ciudad":3,"campo":0,"fiesta":2,"calma":1,"cultura":3,"gastronomia":3,"naturaleza":2,"playa":2,"aventura":2,"postal":3}'::jsonb,'bajo','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8],"nota":"Playa e islas de mayo a septiembre; agosto es el más caro y concurrido. En invierno la ciudad y Pompeya siguen bien, pero hay menos barcos."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Conducir en Nápoles es caótico, hay ZTL y robos de coche; Pompeya, Herculano y los barcos se alcanzan en tren y ferry. Solo ayuda para recorrer la costa.","aeropuerto_recogida":"NAP","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Napoli.NAP.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Napoli.NAP.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.kayak.it/Europcar-Auto-a-noleggio-Napoli.NAP.AEUROPCAR.cla.ksp","fuente":"https://www.kayak.it/Europcar-Auto-a-noleggio-Napoli.NAP.AEUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.it/noleggio-auto/Avis-Napoli.NAP.AVIS.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Avis-Napoli.NAP.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"NAP","nombre":"Nápoles – Capodichino","ciudad":"Nápoles","a_la_base":"Autobús Alibus a la estación de Nápoles Centrale y al puerto (según Trenitalia)."}],"desde_espana":"Vuelan Ryanair y Vueling desde Barcelona, entre otros; mirad también el combinado tren+avión de iryo e ITA Airways. Las rutas cambian por temporada.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"NAP","aerolinea":"Ryanair","nota":"según Opodo; comprobad temporada","fuente":"https://www.opodo.es/vuelos/aerolinea/FR/ryanair/NAP/napoles/BCN/barcelona/"},{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"NAP","aerolinea":"Vueling","nota":"según Omio; comprobad temporada","fuente":"https://www.omio.com.ar/vuelos/barcelona/napoles"}],"desde_italia":"Desde Roma Termini hay tren de alta velocidad a Nápoles Centrale en algo más de una hora (Trenitalia o Italo); también hay FlixBus.","novedades":[{"nota":"El billete combinado tren+avión de iryo e ITA Airways también cubre Nápoles.","fuente":"https://www.elperiodic.com/viajar-entre-comunitat-valenciana-italia-nunca-facil-funciona-billete-tren-avion_1002354"}]}'::jsonb,'{"resumen":"Centro a pie y metro; Circumvesuviana a Pompeya y Herculano; ferris y aliscafos desde el puerto a las islas.","tren":{"nota":"Trenitalia e Italo hasta Nápoles Centrale; Circumvesuviana (EAV) para Herculano y Pompeya.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Solo trayectos dentro de Italia, no desde España.","enlace":"https://www.flixbus.it/autobus/napoli","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[{"operador":"Alilauro","ruta":"Nápoles (Beverello) – Ischia","nota":"Aliscafo; comprobad horarios por temporada.","enlace":"https://www.alilauro.it/it/tratte/napoli-beverello-ischia-ischia-napoli-beverello/","fuente":"https://www.alilauro.it/it/tratte/napoli-beverello-ischia-ischia-napoli-beverello/"},{"operador":"SNAV","ruta":"Nápoles – Procida, Ischia y Capri","nota":"Aliscafos a las tres islas; horarios en su web.","enlace":"https://www.snav.it/en/orari-e-tratte","fuente":"https://www.snav.it/en/orari-e-tratte"},{"operador":"Caremar","ruta":"Nápoles – Procida, Ischia y Capri","nota":"Ferris y aliscafos, normalmente más baratos que otros.","enlace":"https://shop.caremar.it/en/","fuente":"https://shop.caremar.it/en/"}],"camper":null}'::jsonb,'["No he verificado precios ni horarios; los barcos cambian por temporada, mirad cada web.","Vesubio: el acceso sin coche no lo he confirmado; mirad la web del parque.","Rutas aéreas: solo las de buscador, no de aerolínea; Medmar y Gescab no verificados.","Varios enlaces son mapa o búsqueda; sitios como MANN o Sansevero sin web oficial verificada.","Eventos: fuentes de prensa, no de la organización; sin fecha 2027 publicada."]'::jsonb,'{"zona":"napoles","base":"napoles","ciudad_referencia":"Nápoles","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":18,"max":23,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/naples/","calidad":"orientativo"},"doble_noche":{"min":47,"max":87,"fuente":"https://www.booking.com/city/it/naples.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/naples","calidad":"orientativo"},"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Naples","calidad":"orientativo"},"transporte_billete":{"valor":1.3,"fuente":"https://www.napolike.it/biglietti-abbonamenti-trasporti-napoli","calidad":"orientativo"}},"notas":"hostel_noche: rango P25-P75 de 17 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=14.0, maximo=47.12); son precios ''desde'' sin fechas concretas. doble_noche: min=47 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=87 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Napoles (rango Numbeo 10-20). transporte_billete: NO verificado en fuente oficial: anm.it bloquea la lectura (robots_disallowed). Dato de napolike.it (portal no oficial, actualizado jul-2026): corsa singola ANM 1.30 EUR en bus/tram/trolebus/funicular; metro lineas 1 y 6 = 1.50 EUR. Confirmar en anm.it."}'::jsonb);
