insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','spaccanapoli','napoles','Spaccanapoli y el centro histórico','Nápoles','cultura',array['postal']::text[],'medio_dia','manana','gratis',false,false,'bajo','social',null,'Calle recta que parte el centro antiguo: iglesias, talleres, graffitis y vida de barrio.',null,'https://www.google.com/maps/search/?api=1&query=Spaccanapoli%2C+Napoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spaccanapoli%2C+Napoli%2C+Italia','https://travel.thewom.it/italia/campania/napoli/spaccanapoli.html',40.85,14.256);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','napoli-sotterranea','napoles','Napoli Sotterranea','Nápoles','aventura',array['cultura']::text[],'2h','tarde','medio',false,true,'bajo','mixto',null,'Visita guiada por cisternas y túneles griegos y romanos bajo el centro.','Reservad en la web oficial.','https://www.napolisotterranea.org/en/?p=597','oficial','https://www.google.com/maps/search/?api=1&query=Napoli+Sotterranea%2C+Napoli%2C+Italia','https://www.napolisotterranea.org/en/?p=597',40.851,14.258);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','quartieri-spagnoli','napoles','Quartieri Spagnoli','Nápoles','cultura',array['postal']::text[],'2h','tarde','gratis',false,false,'bajo','social',null,'Calles estrechas con ropa tendida, murales y altares; lo más auténtico de la ciudad.','Id de día y en grupo, sin bolsos a la vista.','https://www.italia.it/es/campania/napoles/quartieri-spagnoli','oficial','https://www.google.com/maps/search/?api=1&query=Quartieri+Spagnoli%2C+Napoli%2C+Italia','https://www.italia.it/es/campania/napoles/quartieri-spagnoli',40.843,14.246);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','mann','napoles','Museo Arqueológico Nacional (MANN)','Nápoles','cultura',null,'medio_dia','manana','medio',false,false,'bajo','tranquilo',null,'Las piezas de Pompeya y Herculano, incluidos mosaicos y esculturas.','El primer domingo de mes la entrada suele ser gratis (Domenica al Museo); confirmadlo en la web del museo.','https://www.google.com/maps/search/?api=1&query=Museo+Archeologico+Nazionale+di+Napoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Museo+Archeologico+Nazionale+di+Napoli%2C+Italia','https://siviaggia.it/notizie/domenica-al-museo-1-novembre/607806/',40.853,14.25);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','sansevero','napoles','Cappella Sansevero y Cristo velado','Nápoles','cultura',array['postal']::text[],'2h','manana','medio',false,true,'bajo','tranquilo',null,'Capilla barroca con la escultura del Cristo velado, una de las más famosas de Italia.','Comprad la entrada con hora.','https://www.google.com/maps/search/?api=1&query=Cappella+Sansevero%2C+Napoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Cappella+Sansevero%2C+Napoli%2C+Italia','https://www.museionline.info/napoli-musei-e-monumenti/museo-cappella-sansevero',40.849,14.254);
