insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','movida-chiaia','napoles','Aperitivo en Piazza Bellini y Chiaia','Nápoles','fiesta',array['musica']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Plaza universitaria con bares y gente en la calle; y Chiaia, para ir arreglados.',null,'https://www.google.com/maps/search/?api=1&query=Piazza+Bellini%2C+Napoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Piazza+Bellini%2C+Napoli%2C+Italia','https://www.google.com/maps/search/?api=1&query=Piazza+Bellini%2C+Napoli%2C+Italia',40.847,14.25);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','pompeya','napoles','Pompeya','Pompeya','cultura',array['aventura']::text[],'dia_completo','manana','medio',false,true,'medio','mixto',null,'Ciudad romana entera sepultada por el Vesubio; se llega en Circumvesuviana.','Hay entradas nominativas y cupo diario: reservad en la web oficial.','https://pompeiisites.org/en/?p=5183','oficial','https://www.google.com/maps/search/?api=1&query=Parco+Archeologico+di+Pompei%2C+Italia','https://pompeiisites.org/en/?p=5183',40.751,14.489);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','herculano','napoles','Herculano','Ercolano','cultura',null,'medio_dia','manana','medio',false,false,'bajo','tranquilo',null,'Ciudad romana mejor conservada y más pequeña que Pompeya, a pocos minutos del tren.','Combinadla con el Vesubio el mismo día.','https://ercolano.cultura.gov.it/herculaneum/?lang=en','oficial','https://www.google.com/maps/search/?api=1&query=Parco+Archeologico+di+Ercolano%2C+Italia','https://ercolano.cultura.gov.it/herculaneum/?lang=en',40.806,14.348);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('napoles','vesubio','napoles','Vesubio: sendero al Gran Cono','Ercolano','aventura',array['naturaleza','postal']::text[],'medio_dia','manana','medio',false,true,'medio','mixto',null,'Subida a pie hasta el borde del cráter con vistas a todo el golfo.','El billete se vende solo online y el acceso puede cerrarse por tiempo; mirad la web del parque.','https://www.parconazionaledelvesuvio.it/','oficial','https://www.google.com/maps/search/?api=1&query=Vesuvio%2C+Gran+Cono%2C+Italia','https://www.parconazionaledelvesuvio.it/',40.821,14.426);
