insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('napoles','Belenes de San Gregorio Armeno','Nápoles','cada año, desde noviembre hasta Navidad',array[11,12]::int[],null,'https://www.voloscontato.it/sagre-ed-eventi/a-napoli-il-natale-comincia-il-1-novembre-torna-la-fiera-dei-presepi-di-san-gregorio-armeno.php','La calle de los belenes se llena de puestos y gente en Navidad.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('costa-amalfitana','IT','Costa Amalfitana','Amalfitana','Pueblos colgados sobre el mar','{"mar":3,"montana":2,"ciudad":1,"campo":1,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":3,"playa":2,"aventura":2,"postal":3}'::jsonb,'alto','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8,1,2],"nota":"Mayo-junio y septiembre dan buen mar sin las masas; agosto está lleno y caro, y en invierno cierran muchos locales y se reducen los barcos."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Sin coche se llega a casi todo: bus SITA, ferry Travelmar y Circumvesuviana hasta Sorrento. La carretera es estrecha, el aparcamiento es escaso y caro y hay tráfico en verano. Solo compensa para un grupo pequeño con conductor con experiencia.","aeropuerto_recogida":"NAP","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Napoli.NAP.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Napoli.NAP.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.kayak.it/Europcar-Auto-a-noleggio-Napoli.NAP.AEUROPCAR.cla.ksp","fuente":"https://www.kayak.it/Europcar-Auto-a-noleggio-Napoli.NAP.AEUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.it/noleggio-auto/Avis-Napoli.NAP.AVIS.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Avis-Napoli.NAP.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"NAP","nombre":"Nápoles – Capodichino","ciudad":"Nápoles","a_la_base":"Bus Alibus a la estación y puerto de Nápoles; de ahí Circumvesuviana a Sorrento o ferry/tren a Salerno. Calculad 2-3 h hasta Amalfi con bus o ferry."},{"iata":"QSR","nombre":"Salerno Costa d''Amalfi","ciudad":"Pontecagnano (Salerno)","a_la_base":"Bus Salerno Airlink (unos 40 min) a la estación de Salerno y de ahí ferry o SITA a Amalfi; pocos vuelos."}],"desde_espana":"Lo normal es volar a Nápoles (NAP) con low cost o con escala vía Roma/Milán. El aeropuerto de Salerno tiene Ryanair, Volotea y easyJet con pocas rutas (Roma, Milán, Turín...). Comprobad las rutas directas desde vuestro aeropuerto, no hay una verificada.","rutas_directas":[],"desde_italia":"Tren Trenitalia/Italo hasta Nápoles o Salerno, luego Circumvesuviana a Sorrento o ferry/bus a la costa. FlixBus tiene paradas en Nápoles.","novedades":[{"nota":"El billete combinado tren+avión de iryo y ITA Airways (2026) también cubre Nápoles: iryo hasta Madrid/Barcelona y vuelo ITA de conexión.","fuente":"https://www.elperiodic.com/viajar-entre-comunitat-valenciana-italia-nunca-facil-funciona-billete-tren-avion_1002354"}]}'::jsonb,'{"resumen":"Sin coche: ferry Travelmar entre Salerno, Amalfi y Positano, y bus SITA por la carretera costera; Circumvesuviana hasta Sorrento. Con coche, aparcar es el problema.","tren":{"nota":"Trenitalia/Italo hasta Nápoles o Salerno; Circumvesuviana (línea EAV) de Nápoles a Sorrento. La costa en sí no tiene tren.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"SITA Sud (costa) y FlixBus (larga distancia a Nápoles)","nota":"SITA une Salerno, Amalfi, Positano y Sorrento con tarifa Unico Costiera; algunos destinos exigen cambiar en Amalfi. FlixBus solo cubre llegadas dentro de Italia.","enlace":"https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/","fuente":"https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/"},"ferry":[{"operador":"Travelmar","ruta":"Salerno – Amalfi – Positano y pueblos intermedios (Maiori, Minori, Cetara)","nota":"Su web anuncia servicio todo el año; confirmad horarios y frecuencias fuera de verano.","enlace":"https://www.travelmar.it/","fuente":"https://www.travelmar.it/"}],"camper":null}'::jsonb,'["No hay ruta aérea directa desde España verificada a NAP ni a QSR; se deja vacío rutas_directas.","No verifiqué horarios ni tarifas de SITA, Travelmar ni Circumvesuviana; hay que consultar las webs el día del viaje.","No se verificó ningún ferry Sorrento–Positano/Amalfi ni Capri; sin enlace seguro, queda fuera.","Faltan webs oficiales de Positano, Praiano y Sorrento; se usan mapas y guías en esos casos.","Las fechas de eventos de 2027 no están publicadas en las fuentes consultadas: todo queda como recurrente.","Información de aeropuertos (Salerno) viene de una guía privada (positano.com), no de la web del aeropuerto."]'::jsonb,'{"zona":"costa-amalfitana","base":"amalfi","ciudad_referencia":"Amalfi","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":35,"max":35,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/amalfi/","calidad":"orientativo"},"doble_noche":{"min":88,"max":197,"fuente":"https://www.booking.com/city/it/amalfi.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/amalfi","calidad":"orientativo"},"comida_barata":{"valor":30,"fuente":"https://www.numbeo.com/cost-of-living/in/Amalfi?displayCurrency=EUR","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche: rango min-max de 1 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=35.0, maximo=35.0); son precios ''desde'' sin fechas concretas. Solo 1 hostel con precio de dorm; min=max. doble_noche: min=88 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=197 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Amalfi (dato POCO FIABLE: la propia Numbeo indica solo 2 entradas de 1 contribuidor en 12 meses (act. 15-ene-2026); Numbeo Salerno (ciudad vecina, https://www.numbeo.com/cost-of-living/in/Salerno) da 13.00 (rango 10-26.30)). transporte_billete null: Amalfi no tiene transporte urbano propio; los autobuses SITA/Unico Costiero son interurbanos por tramos (no se abrio una pagina oficial con tarifa)."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('costa-amalfitana','amalfi','Amalfi','Centro de la costa: ferries Travelmar, bus SITA a Positano, Ravello y Agerola (Sentiero degli Dei), pero alojamiento caro.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('costa-amalfitana','sorrento','Sorrento','Llegas en tren Circumvesuviana desde Nápoles, hay hostales baratos y ferry/bus a la costa; algo más alejado de Amalfi.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('costa-amalfitana','salerno','Salerno','La base más barata y con vida universitaria, con ferry a Amalfi y tren a Nápoles; lejos de Positano y del Sentiero.','fiesta',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('costa-amalfitana','praiano','Praiano','Pueblo tranquilo entre Positano y Amalfi, cerca de Marina di Praia y Furore, con parada de bus SITA.','calma',true);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','sentiero-degli-dei','amalfi','Sentiero degli Dei (Agerola – Nocelle – Positano)','Agerola / Nocelle / Positano','naturaleza',array['aventura','postal']::text[],'dia_completo','manana','gratis',false,false,'medio','mixto',null,'Ruta de unas 3-4 h colgada sobre el mar, de Bomerano (Agerola) a Nocelle y bajada por escaleras a Positano. Es la excursión estrella.','Sin coche: bus SITA hasta Bomerano y vuelta en bus o ferry desde Positano. Llevad agua y calzado con suela; la bajada final son cientos de escalones.','https://www.google.com/maps/search/?api=1&query=Sentiero+degli+Dei%2C+Agerola%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Sentiero+degli+Dei%2C+Agerola%2C+Italia','https://siviaggia.it/cammini/sentiero-degli-dei/538455/',40.626,14.54);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','duomo-amalfi','amalfi','Duomo de Amalfi y Chiostro del Paradiso','Amalfi','cultura',array['postal']::text[],'2h','manana','bajo',false,false,'bajo','mixto',null,'Catedral del siglo IX con escalinata, fachada de mosaicos y claustro árabe-normando con sarcófagos romanos.','Abre a diario a partir de las 9:00 (según italia.it); comprobad el horario de cierre antes de ir.','https://www.italia.it/it/campania/salerno/amalfi/duomo-di-sant-andrea','oficial','https://www.google.com/maps/search/?api=1&query=Duomo+di+Sant%27Andrea%2C+Amalfi%2C+Italia','https://www.italia.it/it/campania/salerno/amalfi/duomo-di-sant-andrea',40.634,14.603);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','fiordo-di-furore','praiano','Fiordo di Furore','Furore','playa',array['naturaleza','postal']::text[],'medio_dia','tarde','gratis',false,false,'medio','tranquilo',array[6,7,8,9]::int[],'Calita de piedras encajada bajo un puente, entre acantilados y las casas de un antiguo pueblo de pescadores. Agua muy limpia.','Se baja por escaleras desde el puente de la carretera (sin aparcamiento): id en bus SITA y bajad a pie. Solo coge sol en las horas centrales/tarde.','https://www.google.com/maps/search/?api=1&query=Fiordo+di+Furore%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Fiordo+di+Furore%2C+Italia','https://www.positano.com/it/e/le-spiagge-di-praiano',40.612,14.545);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','marina-di-praia','praiano','Marina di Praia','Praiano','playa',array['agua']::text[],'medio_dia','cualquiera','bajo',false,false,'bajo','social',array[6,7,8,9]::int[],'Playa de guijarros bajo una torre sarracena, con paseo por el acantilado y sitio para tomar algo; mucho más tranquila que Positano.','Recibe sol sobre todo a mediodía; para el atardecer subid a la zona de Praiano.','https://www.google.com/maps/search/?api=1&query=Marina+di+Praia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Marina+di+Praia%2C+Italia','https://www.positano.com/it/e/le-spiagge-di-praiano',40.614,14.531);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','positano-spiaggia-grande','praiano','Spiaggia Grande de Positano','Positano','playa',array['postal']::text[],'medio_dia','cualquiera','medio',false,false,'bajo','social',array[5,6,7,8,9,10]::int[],'La playa de la postal: guijarros oscuros bajo las casas de colores. Se entra gratis a zonas libres y se alquilan tumbonas en las de pago.','Si vais en grupo ajustado, llevad toalla y usad la zona libre; el coste se dispara con tumbonas y comida en primera línea.','https://www.google.com/maps/search/?api=1&query=Spiaggia+Grande%2C+Positano%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+Grande%2C+Positano%2C+Italia','https://www.positano.com/it/e/le-spiagge-di-praiano',40.628,14.485);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','ferry-amalfi-positano','amalfi','Barco entre pueblos con Travelmar','Amalfi / Positano / Salerno','agua',array['postal']::text[],'medio_dia','tarde','medio',false,false,'bajo','mixto',null,'Ver la costa desde el mar: ferry entre Salerno, Amalfi, Positano y otros pueblos con parada en cada embarcadero, sin pelearse con el tráfico.','La web de Travelmar dice servicio todo el año, pero fuera de verano hay menos frecuencias y la mar puede cancelar salidas: mirad el horario del día.','https://www.travelmar.it/','oficial','https://www.google.com/maps/search/?api=1&query=Travelmar+Amalfi%2C+Molo+Darsena%2C+Amalfi%2C+Italia','https://www.travelmar.it/',40.634,14.603);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','villa-rufolo','amalfi','Villa Rufolo y sus jardines','Ravello','cultura',array['postal','naturaleza']::text[],'2h','manana','bajo',false,false,'bajo','tranquilo',null,'Villa del siglo XIII con torre morisca, claustro y jardines en terrazas sobre el mar que inspiraron a Wagner para el jardín de Klingsor en Parsifal.','Según italia.it abre todos los días de 9:00 a 20:00. Se llega en bus SITA desde Amalfi.','https://www.italia.it/it/campania/salerno/ravello/giardini-di-villa-rufolo','oficial','https://www.google.com/maps/search/?api=1&query=Villa+Rufolo%2C+Ravello%2C+Italia','https://www.italia.it/it/campania/salerno/ravello/giardini-di-villa-rufolo',40.649,14.611);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','ravello-belvedere','amalfi','Terrazas y jardines panorámicos de Ravello','Ravello','postal',array['naturaleza']::text[],'2h','tarde','gratis',false,false,'bajo','tranquilo',null,'Paseo por el pueblo en lo alto, con plazas, miradores y villas-jardín sobre el mar; mucho más calmado que la costa.',null,'https://www.google.com/maps/search/?api=1&query=Ravello+centro%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Ravello+centro%2C+Italia','https://siviaggia.it/idee-di-viaggio/giardini-belvedere-ravello/517198/',40.649,14.612);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','ravello-festival','amalfi','Conciertos del Ravello Festival','Ravello','musica',array['cultura']::text[],'2h','noche','medio',false,true,'bajo','tranquilo',array[7,8,9]::int[],'En verano se monta un escenario sobre el mar en Villa Rufolo y Ravello se llena de música clásica y conciertos.','Programa y fechas cambian cada año; mirad la web del festival antes de reservar alojamiento.','https://villarufolo.com/the-festival-and-the-villa/?lang=en','oficial','https://www.google.com/maps/search/?api=1&query=Villa+Rufolo%2C+Ravello%2C+Italia','https://villarufolo.com/the-festival-and-the-villa/?lang=en',40.649,14.611);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','atrani','amalfi','Atrani al atardecer','Atrani','postal',array['cultura']::text[],'2h','noche','gratis',false,false,'bajo','tranquilo',null,'El pueblo más pequeño de Italia por habitantes, a 10 minutos andando de Amalfi: callejones, plaza sobre el mar y playa pequeña.','Se llega a pie desde Amalfi por un paseo corto o con bus SITA (Atrani figura en la línea Salerno–Amalfi).','https://www.google.com/maps/search/?api=1&query=Atrani%2C+Costiera+Amalfitana%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Atrani%2C+Costiera+Amalfitana%2C+Italia','https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/',40.634,14.61);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','bus-sita-panoramico','amalfi','Trayecto panorámico en bus SITA','Sorrento / Positano / Amalfi','postal',array['aventura']::text[],'medio_dia','manana','bajo',false,false,'bajo','social',null,'La carretera costera en bus es una atracción en sí misma: curvas sobre el mar, pueblos colgados y paradas para bajar a donde queráis.','Sentaos en el lado del mar según el sentido; en verano van llenos y las colas son largas. Tarifa Unico Costiera según la web de SITA.','https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/','oficial','https://www.google.com/maps/search/?api=1&query=SITA+Sud%2C+Amalfi%2C+Italia','https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/',40.626,14.376);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','barco-excursion','amalfi','Excursión en barco por la costa','Amalfi / Positano','agua',array['playa','postal']::text[],'medio_dia','manana','alto',false,true,'bajo','social',array[5,6,7,8,9]::int[],'Barco compartido para ver calas y cuevas inaccesibles por tierra y bañarse en mar abierto; se divide entre el grupo.','Comparad varias ofertas y mirad qué incluye (paradas para baño, duración) antes de pagar.','https://www.getyourguide.es/s/?q=barco+costa+amalfitana','reserva','https://www.google.com/maps/search/?api=1&query=Marina+Grande%2C+Amalfi%2C+Italia','https://www.sitabus.it/en/salerno-to-amalfi-coast-bus-timetable/',40.633,14.602);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','sorrento-vallone-mulini','sorrento','Centro de Sorrento y Vallone dei Mulini','Sorrento','cultura',array['postal']::text[],'2h','manana','gratis',false,false,'bajo','mixto',null,'Paseo por el casco antiguo, callejones y el Vallone dei Mulini, un barranco con un viejo molino entre vegetación a pocos pasos de la plaza principal.',null,'https://www.italia.it/en/campania/naples/sorrento','oficial','https://www.google.com/maps/search/?api=1&query=Vallone+dei+Mulini%2C+Sorrento%2C+Italia','https://travel.thewom.it/italia/campania/vallone-dei-mulini-a-sorrento.html',40.627,14.373);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','sorrento-limoncello','sorrento','Limones y limoncello de Sorrento','Sorrento','gastronomia',array['compras']::text[],'2h','tarde','bajo',false,false,'bajo','social',null,'Cata de limoncello y productos de limón en tiendas y pequeños productores; se aprende la diferencia entre el limón de Sorrento y el sfusato de Amalfi.','Pedid probar antes de comprar; el limoncello de supermercado sale más barato que el de souvenir.','https://www.getyourguide.es/s/?q=limoncello+Sorrento','reserva','https://www.google.com/maps/search/?api=1&query=limoncello+degustazione%2C+Sorrento%2C+Italia','https://gazzettadelgusto.it/cibo/sfusato-amalfitano-pregiato-frutto-della-divina-costiera/',40.626,14.376);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','sorrento-atardecer','sorrento','Atardecer en Marina Grande y miradores de Sorrento','Sorrento','postal',array['naturaleza']::text[],'2h','noche','gratis',false,false,'bajo','tranquilo',null,'Barrio de pescadores con barcas y restaurantes sencillos, y miradores sobre el golfo de Nápoles para ver caer el sol con el Vesubio al fondo.',null,'https://www.google.com/maps/search/?api=1&query=Marina+Grande%2C+Sorrento%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Marina+Grande%2C+Sorrento%2C+Italia','https://www.italia.it/en/campania/naples/sorrento',40.629,14.371);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','salerno-minerva','salerno','Giardino della Minerva','Salerno','naturaleza',array['cultura']::text[],'2h','manana','bajo',false,false,'bajo','tranquilo',null,'Huerto botánico medieval en terrazas en pleno casco antiguo, ligado a la Escuela Médica Salernitana.',null,'https://cultura.gov.it/luogo/orto-botanico-giardino-della-minerva','oficial','https://www.google.com/maps/search/?api=1&query=Giardino+della+Minerva%2C+Salerno%2C+Italia','https://cultura.gov.it/luogo/orto-botanico-giardino-della-minerva',40.68,14.76);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','salerno-luci','salerno','Luci d''Artista de Salerno','Salerno','postal',array['fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',array[12,1]::int[],'Instalaciones de luz de artistas contemporáneos por calles y parques de Salerno en Navidad, con mercadillos y mucha gente paseando.','Italia.it da el periodo aproximado (Navidad hasta finales de enero); las fechas exactas cambian cada año.','https://www.italia.it/it/campania/salerno/salerno-le-luci-d-artista','oficial','https://www.google.com/maps/search/?api=1&query=Luci+d%27Artista%2C+Salerno%2C+Italia','https://www.italia.it/it/campania/salerno/salerno-le-luci-d-artista',40.681,14.763);
