insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','vietri','salerno','Vietri sul Mare y su cerámica','Vietri sul Mare','compras',null,'2h','cualquiera','gratis',false,false,'bajo','tranquilo',null,'El primer pueblo de la costa viniendo de Salerno: fachadas, tiendas y hasta la cúpula de la iglesia cubiertas de cerámica pintada.','','https://www.google.com/maps/search/?api=1&query=Vietri%20sul%20Mare%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Vietri%20sul%20Mare%2C%20Italia','https://www.mochileandoporelmundo.com/guia-de-viaje-a-la-costa-amalfitana/',40.672,14.7275);
