insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('costa-amalfitana','capri-ferry','sorrento','Capri en ferry','Capri','postal',null,'dia_completo','manana','medio',false,false,'bajo','tranquilo',array[4,5,6,7,8,9,10]::int[],'Día entero en la isla: funicular a la Piazzetta, jardines de Augusto con los Faraglioni y, si queda tiempo, Anacapri.','Barcos desde Sorrento todo el año y desde Amalfi y Positano en temporada.','https://www.google.com/maps/search/?api=1&query=Marina%20Grande%2C%20Capri%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Marina%20Grande%2C%20Capri%2C%20Italia',null,40.5508,14.2433);
insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Limoncello','licor de limón de la costa, de limón sfusato (Amalfi) o ovale (Sorrento); se toma frío al final de la comida','bebida','bajo','tiendas de productores en Amalfi y Sorrento, y tras la comida en trattorias','https://www.google.com/maps/search/?api=1&query=limoncello+Amalfi%2C+Italia');
