insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Delizia al limone','bizcocho relleno de crema de limón y glaseado, el postre símbolo de la costa','dulce','bajo','pastelerías de Amalfi, Minori y Sorrento','https://www.google.com/maps/search/?api=1&query=pasticceria+delizia+al+limone+Amalfi%2C+Italia');
insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Colatura di alici di Cetara','salsa de anchoas fermentadas para condimentar espagueti; producto artesano de Cetara','trattoria','medio','espagueti con colatura en trattorias de Cetara y Amalfi','https://www.google.com/maps/search/?api=1&query=Cetara%2C+Costiera+Amalfitana%2C+Italia');
insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Mozzarella, provola y ricotta de Agerola y Tramonti','lácteos frescos de las montañas sobre la costa','mercado','bajo','queserías y latterías de Tramonti, Agerola y tiendas de Amalfi; sirven para bocadillos de picnic','https://www.google.com/maps/search/?api=1&query=caseificio+Agerola%2C+Italia');
insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Pasteles y galletas de Amalfi','biscotti amalfitani, zeppole de San José y pastelería con limón y cítricos','dulce','bajo','cafés históricos y pastelerías de la plaza del Duomo de Amalfi','https://www.google.com/maps/search/?api=1&query=pasticceria+Piazza+Duomo%2C+Amalfi%2C+Italia');
insert into public.lib_comida(destino_id,plato,que_es,estilo,coste,donde,maps) values ('costa-amalfitana','Pizza napolitana en Salerno','pizza de masa tierna con borde alto; en Salerno sale más barata que en Positano o Amalfi','trattoria','bajo','pizzerías del centro histórico y alrededores de la estación de Salerno','https://www.google.com/maps/search/?api=1&query=pizzeria+Salerno%2C+Italia');
insert into public.lib_noche(destino_id,base_id,zona,plan,descripcion,maps,lat,lon) values ('costa-amalfitana','salerno','Casco antiguo de Salerno (Via dei Mercanti y alrededores)','copas','La zona con más bares y ambiente universitario de toda la costa; abre también en invierno.','https://www.google.com/maps/search/?api=1&query=Via+dei+Mercanti%2C+Salerno%2C+Italia',40.68,14.76);
