insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('costa-amalfitana','Fiesta de Sant''Andrea (Corsa del Santo)','Amalfi','cada año, 26-27 de junio y 30 de noviembre',array[6,11]::int[],null,'https://www.travelamalficoast.it/en/saint-andrew-celebration-in-amalfi','Procesión, fuegos sobre el mar y carrera del busto del patrón escalinata abajo del Duomo.');
insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('costa-amalfitana','Fuegos de la Asunción en Positano y Maiori','Positano / Maiori','cada año, 15 de agosto (Maiori sobre las 23:00, Positano a medianoche)',array[8]::int[],null,'https://simplyamalficoast.it/?p=6616','Procesión de la Virgen y fuegos artificiales desde el mar; se ven también desde barcos.');
insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('costa-amalfitana','Ravello Festival','Ravello','cada año en verano, programa en la web oficial',array[7,8,9]::int[],null,'https://villarufolo.com/the-festival-and-the-villa/?lang=en','Conciertos de música clásica y otros géneros en un escenario sobre el mar en Villa Rufolo.');
insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('costa-amalfitana','Luci d''Artista','Salerno','cada año, de Navidad a finales de enero',array[12,1]::int[],null,'https://www.italia.it/it/campania/salerno/salerno-le-luci-d-artista','Luminarias de artistas contemporáneos por el centro de Salerno, con mercadillos navideños.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('veneto-venecia','IT','Venecia y Véneto','Venecia','Canales, cicchetti y Prosecco','{"mar":1,"montana":1,"ciudad":3,"campo":2,"fiesta":2,"calma":1,"cultura":3,"gastronomia":3,"naturaleza":1,"playa":1,"aventura":0,"postal":3}'::jsonb,'alto','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11,12],"evitar":[8],"nota":"Agosto es húmedo y bochornoso; en febrero (Carnaval) hay mucha gente y precios altos; en otoño-invierno puede haber acqua alta."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Dentro de Venecia no hay coches: se llega al aparcamiento de Piazzale Roma o a Tronchetto y se sigue a pie o en vaporetto. Padua, Verona y Vicenza se hacen en tren; el coche solo compensa para las colinas del Prosecco.","aeropuerto_recogida":"VCE","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Venecia.VCE.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Venecia.VCE.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Venezia.VCE.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Venezia.VCE.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Venecia.VCE.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Venecia.VCE.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"VCE","nombre":"Venecia – Marco Polo","ciudad":"Venecia","a_la_base":"Hay bus y barco desde el aeropuerto hasta Venecia (Piazzale Roma o paradas de Alilaguna); mirad las opciones y precios en la web del aeropuerto antes de volar."},{"iata":"TSF","nombre":"Treviso – Antonio Canova","ciudad":"Treviso","a_la_base":"Aeropuerto low cost a unos 30 km de Venecia; se conecta con Venecia y Mestre en bus o combinando bus y tren. Comprobad el bus en la web del aeropuerto."},{"iata":"VRN","nombre":"Verona – Valerio Catullo","ciudad":"Verona","a_la_base":"Útil si queréis empezar por Verona; desde ahí hay tren directo a Padua y Venecia."}],"desde_espana":"Ryanair vuela a Treviso (TSF) desde Barcelona y Madrid, y hay más rutas a Venecia (VCE) y Verona (VRN) según temporada. Comparad VCE y TSF: Treviso suele salir más barato, pero el transporte a Venecia cuesta algo más.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"TSF","aerolinea":"Ryanair","nota":"ruta publicada en la web de Ryanair; comprobad días y temporada al reservar","fuente":"https://www.ryanair.com/ie/en/flights/flights-from-barcelona-to-venice-treviso"},{"origen":"Madrid","origen_iata":"MAD","destino_iata":"TSF","aerolinea":"Ryanair","nota":"ruta publicada en la web de Ryanair; comprobad días y temporada al reservar","fuente":"https://www.ryanair.com/gb/en/flights/flights-from-madrid-to-venice-treviso"}],"desde_italia":"Hay trenes directos de Trenitalia e Italo a Venezia Santa Lucia desde Milán, Bolonia, Florencia y Roma. Si vais a dormir en Mestre, bajad en Venezia Mestre, que es la parada anterior.","novedades":[{"nota":"El billete combinado tren+avión de iryo e ITA Airways (2026) también cubre Venecia: iryo hasta Madrid/Barcelona y vuelo ITA Airways de conexión.","fuente":"https://www.elperiodic.com/viajar-entre-comunitat-valenciana-italia-nunca-facil-funciona-billete-tren-avion_1002354"},{"nota":"Venecia cobra una tasa de acceso a los visitantes de un día en fechas concretas: en la web oficial italia.it se indica 5 € por persona si se paga con antelación y 10 € si se paga tarde, en horario de 8:30 a 16:00. El calendario cambia cada año; consultad cda.ve.it y las exenciones antes de ir.","fuente":"https://italia.it/en/veneto/venice/things-to-do/information-contribution-access-venice"}]}'::jsonb,'{"resumen":"Venecia se recorre a pie y en vaporetto; para Padua, Verona y Vicenza el tren regional es lo más práctico y barato. El coche solo tiene sentido para las colinas del Prosecco.","tren":{"nota":"Trenes regionales y de alta velocidad entre Venecia, Padua, Verona y Vicenza; comprad en la web o app de Trenitalia e Italo.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Cubre rutas dentro de Italia (por ejemplo Venecia con Trieste o Milán); la web permite buscar la ruta exacta.","enlace":"https://www.flixbus.it/tratte-autobus","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[{"operador":"ACTV (vaporetto)","ruta":"Gran Canal (línea 1), Lido, Murano y Burano","nota":"Hay billetes sencillos y abonos de 1, 2, 3 y 7 días; para un grupo que va a moverse mucho compensa el abono.","enlace":"https://www.veneziaunica.it/it/acquista-i-biglietti/trasporto-pubblico-a-venezia/actv-biglietto-1-giorno-venezia-daily-pass","fuente":"https://www.veneziaunica.it/it/acquista-i-biglietti/trasporto-pubblico-a-venezia/actv-biglietto-1-giorno-venezia-daily-pass"}],"camper":null}'::jsonb,'["No hemos verificado las fechas de la tasa de acceso de 2027: la página oficial que pudimos abrir solo cubría 2025. Consultad cda.ve.it antes de ir, sobre todo en fines de semana y puentes.","Carnevale: enlace de fuente de la edición 2026; las fechas de 2027 no están verificadas.","Sin web oficial verificada para Murano/Burano, Rialto, Zattere o los bacari: los enlaces son mapas.","Las rutas de vuelo se basan en las páginas de ruta de Ryanair, sin horarios ni frecuencias verificados.","Los transportes desde los aeropuertos (VCE, TSF) se describen en general, sin tiempos ni precios verificados."]'::jsonb,'{"zona":"veneto-venecia","base":"venecia","ciudad_referencia":"Venecia","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":19,"max":39,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/venice/","calidad":"orientativo"},"doble_noche":{"min":65,"max":101,"fuente":"https://www.booking.com/city/it/venice.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/venice","calidad":"orientativo"},"comida_barata":{"valor":20,"fuente":"https://www.numbeo.com/cost-of-living/in/Venice","calidad":"orientativo"},"transporte_billete":{"valor":9.5,"fuente":"https://www.veneziaunica.it/it/acquista-i-biglietti/trasporto-pubblico-a-venezia","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 8 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=15.77, maximo=61.0); son precios ''desde'' sin fechas concretas. doble_noche: min=65 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=101 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Venecia (rango Numbeo 15-25). transporte_billete: ACTV Biglietto Ordinario 75 minutos: la pagina oficial indica \"da 9,50 EUR\" (vaporetto/bus en Venecia; es el precio turista, no el de residente). No es comparable con otras ciudades."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('veneto-venecia','venecia','Venecia (centro histórico)','Dormir en la ciudad permite ver San Marco de madrugada y salir de noche sin prisas, pero es lo más caro.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('veneto-venecia','mestre','Mestre','Tierra firme a pocos minutos en tren de Venecia, con alojamiento mucho más barato y buenas conexiones a Padua y Verona.','calma',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('veneto-venecia','padua','Padua','Ciudad universitaria con ambiente estudiantil, aperitivos baratos y tren frecuente a Venecia.','fiesta',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('veneto-venecia','verona','Verona','Centro compacto y bonito, con la Arena y mucha vida en las plazas; buena para un fin de semana aparte.','mixto',true);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('veneto-venecia','san-marco-ducal','venecia','Plaza San Marco y Palacio Ducal','Venecia','cultura',array['postal']::text[],'medio_dia','manana','medio',false,true,'medio','mixto',null,'Basílica, campanario y Palacio Ducal: lo imprescindible de Venecia, mejor a primera hora antes de los grupos.','Reservad entradas con antelación en temporada alta.','https://www.google.com/maps/search/?api=1&query=Palazzo+Ducale%2C+Venecia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Palazzo+Ducale%2C+Venecia%2C+Italia','https://www.google.com/maps/search/?api=1&query=Palazzo+Ducale%2C+Venecia%2C+Italia',45.434,12.34);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('veneto-venecia','gran-canal-vaporetto','venecia','Gran Canal en vaporetto (línea 1)','Venecia','postal',array['cultura']::text[],'2h','tarde','bajo',false,false,'bajo','social',null,'Recorrido lento por todo el Gran Canal con palacios a ambos lados, por el precio de un billete de transporte.','Subid al atardecer y buscad sitio de pie en la proa.','https://www.veneziaunica.it/it/acquista-i-biglietti/trasporto-pubblico-a-venezia/actv-biglietto-1-giorno-venezia-daily-pass','oficial','https://www.google.com/maps/search/?api=1&query=Ferrovia%2C+Venecia%2C+Italia','https://www.veneziaunica.it/it/acquista-i-biglietti/trasporto-pubblico-a-venezia/actv-biglietto-1-giorno-venezia-daily-pass',45.441,12.321);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('veneto-venecia','rialto-mercado','venecia','Puente y mercado de Rialto','Venecia','gastronomia',array['cultura']::text[],'2h','manana','gratis',false,false,'bajo','mixto',null,'Mercado de verdura y pescado junto al puente más famoso; ideal para ver Venecia cotidiana.','La pescadería suele cerrar domingos y lunes; comprobadlo antes de ir.','https://www.google.com/maps/search/?api=1&query=Mercato+di+Rialto%2C+Venecia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Mercato+di+Rialto%2C+Venecia%2C+Italia','https://www.google.com/maps/search/?api=1&query=Mercato+di+Rialto%2C+Venecia%2C+Italia',45.438,12.336);
