insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('sicilia','IT','Sicilia','Sicilia','Volcán, mercados y mar de postal','{"mar":3,"montana":2,"ciudad":3,"campo":1,"fiesta":2,"calma":1,"cultura":3,"gastronomia":3,"naturaleza":3,"playa":3,"aventura":2,"postal":3}'::jsonb,'bajo','{"ideales":[4,5,6,9,10],"aceptables":[3,11],"evitar":[7,8],"nota":"Mayo-junio y septiembre-octubre: mar bañable, menos gente y sin el calor de julio-agosto, que es muy fuerte en el interior y en la costa sur."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Palermo, Catania y Siracusa (Ortigia) se hacen sin coche y con ZTL en los centros. El coche compensa para Zingaro, Scala dei Turchi, Alcantara y la costa oeste; en ciudad es un lío de aparcamiento. Entre ciudades principales hay bus y tren.","aeropuerto_recogida":"CTA","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Catania.CTA.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Catania.CTA.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Catania.CTA.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Catania.CTA.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.it/noleggio-auto/Avis-Catania.CTA.AVIS.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Avis-Catania.CTA.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"CTA","nombre":"Catania – Fontanarossa","ciudad":"Catania","a_la_base":"Bus Alibus al centro de Catania (el aeropuerto está pegado a la ciudad); para Siracusa, bus o tren desde Catania."},{"iata":"PMO","nombre":"Palermo – Falcone Borsellino","ciudad":"Palermo","a_la_base":"Hay tren y bus al centro de Palermo; comprobad horarios en Trenitalia antes de volar."},{"iata":"TPS","nombre":"Trapani – Birgi","ciudad":"Trapani","a_la_base":"Útil para San Vito Lo Capo, Egadi y Zingaro: bus o coche hasta Trapani y luego a San Vito."},{"iata":"CIY","nombre":"Comiso","ciudad":"Comiso (Ragusa)","a_la_base":"Aeropuerto pequeño en el sureste; sin coche es incómodo, lo normal es bus o coche hasta Ragusa/Siracusa."}],"desde_espana":"Vueling vuela desde Barcelona a Palermo, Catania y Comiso (los de Comiso eran de verano). Ryanair tiene base en Catania, Palermo y Trapani y, según prensa del sector, añade en el invierno 2026-27 Valencia y Alicante a Catania. Mirad las fechas reales en el buscador.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"PMO","aerolinea":"Vueling","nota":"refuerzo en verano 2026; ruta ya existente","fuente":"https://forbes.es/turismo/430847/vueling-estrena-la-ruta-barcelona-comiso-italia-y-refuerza-la-conexion-con-sicilia/"},{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"CTA","aerolinea":"Vueling","nota":"refuerzo en verano 2026; ruta ya existente","fuente":"https://forbes.es/turismo/430847/vueling-estrena-la-ruta-barcelona-comiso-italia-y-refuerza-la-conexion-con-sicilia/"},{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"CIY","aerolinea":"Vueling","nota":"estacional: 13 junio-8 septiembre en 2026, dos vuelos semanales","fuente":"https://forbes.es/turismo/430847/vueling-estrena-la-ruta-barcelona-comiso-italia-y-refuerza-la-conexion-con-sicilia/"},{"origen":"Valencia","origen_iata":"VLC","destino_iata":"CTA","aerolinea":"Ryanair","nota":"nueva en el invierno 2026-27 según prensa del sector; confirmad en la web","fuente":"https://www.airtraveler.club/news/ryanair-adds-17-new-winter-routes-sicily-88-total/"},{"origen":"Alicante","origen_iata":"ALC","destino_iata":"CTA","aerolinea":"Ryanair","nota":"nueva en el invierno 2026-27 según prensa del sector; confirmad en la web","fuente":"https://www.airtraveler.club/news/ryanair-adds-17-new-winter-routes-sicily-88-total/"}],"desde_italia":"Desde Roma o Nápoles hay trenes y FlixBus que cruzan el estrecho de Mesina hasta Palermo, Catania o Siracusa; son muchas horas, así que para un fin de semana largo mejor volar (Ryanair y otras salen de Bolonia, Milán y Roma).","novedades":[{"nota":"Ryanair programa 88 rutas en Sicilia en invierno 2026-27, 17 nuevas, con aviones basados en Catania, Palermo y Trapani.","fuente":"https://www.balarm.it/news/ryanair-punta-sulla-sicilia-17-nuove-rotte-il-programma-record-per-l-inverno-170822"}]}'::jsonb,'{"resumen":"Entre Palermo, Catania, Siracusa y Cefalù tenéis tren y bus; para calas, reservas y pueblos del interior el coche es más cómodo. Dentro de cada ciudad, a pie.","tren":{"nota":"Trenitalia cubre Palermo-Cefalù, Catania-Taormina, Catania-Siracusa y Palermo-Agrigento; es lento pero barato. Comprad en la web o en máquina.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Une Palermo, Catania, Siracusa y otras ciudades; suele ser más rápido que el tren entre Palermo y Catania.","enlace":"https://www.flixbus.it/tratte-autobus/palermo-siracusa","fuente":"https://www.flixbus.it/tratte-autobus/palermo-siracusa"},"ferry":[{"operador":"Caronte & Tourist","ruta":"Villa San Giovanni (Calabria) - Mesina","nota":"Más de 120 travesías diarias, 24 horas, admite vehículos. Sirve para combinar Calabria y Sicilia.","enlace":"https://booking.carontetourist.it/en","fuente":"https://www.carontetourist.it/en/caronte-tourist"},{"operador":"Caronte & Tourist","ruta":"Milazzo - Islas Eolias","nota":"Salidas desde Milazzo (cerca de Mesina); la página explica cómo llegar a Milazzo.","enlace":"https://www.carontetourist.it/en/aeolian-islands/how-to-get-from-milazzo","fuente":"https://www.carontetourist.it/en/aeolian-islands/how-to-get-from-milazzo"},{"operador":"Liberty Lines","ruta":"Trapani - Islas Egadi (Favignana, Levanzo)","nota":"Aliscafos en temporada; consultad frecuencias en su web.","enlace":"https://www.libertylines.it/destinazioni/favignana/","fuente":"https://www.libertylines.it/destinazioni/favignana/"}],"camper":null}'::jsonb,'["Sicilia es grande: en un viaje corto elegid una zona (oeste o este), no las dos.","No he verificado horarios, precios ni frecuencias de bus/tren; comprobadlos antes de ir.","Para varios sitios de Palermo y Catania el enlace es el mapa porque no verifiqué una web oficial.","Rutas aéreas Ryanair VLC/ALC-CTA vienen de prensa del sector, no de Ryanair; hay que confirmarlas en la web.","Fontane Bianche y San Vito solo tienen enlace de mapa; Gole dell''Alcantara tiene fuente privada (enjoysicilia).","Falta ampliar alojamiento en Taormina/Catania y verificar Hostelworld."]'::jsonb,'{"zona":"sicilia","base":"palermo","ciudad_referencia":"Palermo","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":20,"max":28,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/palermo/","calidad":"orientativo"},"doble_noche":{"min":50,"max":90,"fuente":"https://www.booking.com/city/it/palermo.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/palermo","calidad":"orientativo"},"comida_barata":{"valor":13.5,"fuente":"https://www.numbeo.com/cost-of-living/in/Palermo","calidad":"orientativo"},"transporte_billete":{"valor":1.4,"fuente":"https://www.amat.pa.it/biglietti/","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 10 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=15.0, maximo=34.0); son precios ''desde'' sin fechas concretas. doble_noche: min=50 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=90 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Palermo (rango Numbeo 7-18). transporte_billete: AMAT Palermo, biglietto ordinario 90 min 1.40 EUR; a bordo 1.80."}'::jsonb);
