insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('sicilia','ballaro','palermo','Mercado de Ballarò','Palermo','gastronomia',array['compras']::text[],'2h','manana','gratis',false,false,'bajo','social',null,'Puestos de pescado, fruta y fritos en el mercado más vivo del centro histórico; se come de pie probando de todo.','Id por la mañana: por la tarde casi todo recoge.','https://www.italia.it/it/sicilia/palermo/ballaro','oficial','https://www.google.com/maps/search/?api=1&query=Mercato+di+Ballar%C3%B2%2C+Palermo%2C+Italia','https://www.italia.it/it/sicilia/palermo/ballaro',38.111,13.358);
