insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('sicilia','Festino de Santa Rosalía','Palermo','cada año, noche del 14 al 15 de julio',array[7]::int[],null,'https://www.voloscontato.it/sagre-ed-eventi/festa-di-santa-rosalia-2026-a-palermo-quando-dove-e-info.php','Procesión de la patrona con carro triunfal por el centro y fuegos artificiales junto al mar.');
