insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('sicilia','Cous Cous Fest','San Vito Lo Capo','cada año, septiembre (fechas en la web oficial)',array[9]::int[],null,'https://www.italia.it/it/sicilia/cosa-fare/evento-cous-cous-fest','Festival internacional de cuscús con degustaciones, concursos y conciertos en la playa.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('cerdena','IT','Cerdeña','Cerdeña','Calas de agua turquesa y nuraghes','{"mar":3,"montana":1,"ciudad":1,"campo":2,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":3,"playa":3,"aventura":2,"postal":3}'::jsonb,'alto','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8,12,1,2],"nota":"Junio y septiembre dan mar cálido sin la masificación de agosto, que es caro y está lleno. Barcos y baño son de mayo a octubre; en invierno muchas cosas de costa cierran."}'::jsonb,'alto',false,'{"necesidad":"imprescindible","nota":"Las calas, el interior y los nuraghes quedan lejos de cualquier tren o bus útil para un grupo. Sin coche, quedaos en Cagliari (Poetto, Castello, Molentargius) o Alghero (casco, barco a Nettuno) y pensad en repartir gasolina entre varios. Para Cagliari-Alghero-Cala Gonone contad con muchas horas de carretera.","aeropuerto_recogida":"CAG","operadores":[{"nombre":"Avis","enlace":"https://www.kayak.it/Avis-Auto-a-noleggio-Cagliari.CAG.AAVIS.cla.ksp","fuente":"https://www.kayak.it/Avis-Auto-a-noleggio-Cagliari.CAG.AAVIS.cla.ksp"},{"nombre":"Hertz","enlace":"https://www.kayak.it/Hertz-Auto-a-noleggio-Cagliari.CAG.AHERTZ.cla.ksp","fuente":"https://www.kayak.it/Hertz-Auto-a-noleggio-Cagliari.CAG.AHERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Cagliari.CAG.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Cagliari.CAG.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"CAG","nombre":"Cagliari – Elmas","ciudad":"Cagliari","a_la_base":"Cagliari está a pocos kilómetros del aeropuerto: hay tren y bus urbano al centro, y taxi; comprobad horarios en la web de Trenitalia."},{"iata":"AHO","nombre":"Alghero – Fertilia","ciudad":"Alghero","a_la_base":"Fertilia está al lado de Alghero; hay bus urbano y taxi al casco antiguo."},{"iata":"OLB","nombre":"Olbia – Costa Smeralda","ciudad":"Olbia","a_la_base":"Entrada al nordeste (Costa Smeralda, La Maddalena); Cala Gonone queda a unas horas en coche."}],"desde_espana":"Suelen volar low cost (Ryanair, Vueling, Volotea) desde Barcelona, Madrid y otras ciudades a Cagliari, Alghero y Olbia, con mucha más oferta de mayo a octubre. Mirad los tres aeropuertos y combinadlos (ida a uno, vuelta a otro) si vais a recorrer la isla.","rutas_directas":[{"origen":"Sevilla","origen_iata":"SVQ","destino_iata":"OLB","aerolinea":"Volotea","nota":"Ruta nueva desde 29 mayo 2026, dos vuelos semanales (martes y viernes); comprobad si sigue en 2027.","fuente":"https://www.lanuovasardegna.it/sassari/cronaca/2026/05/29/news/alghero-e-olbia-da-oggi-i-nuovi-collegamenti-aerei-verso-due-citta-europee-ecco-quali-sono-1.100876062"}],"desde_italia":"Desde Roma, Livorno, Génova o Civitavecchia hay ferris nocturnos baratos a Olbia, Golfo Aranci, Porto Torres o Cagliari; con vuelos desde Bolonia, Milán o Roma a los tres aeropuertos. No hay tren que llegue a la isla.","novedades":[{"nota":"Volotea abrió en mayo de 2026 Olbia–Sevilla dentro del concurso de rutas subvencionadas de la Región de Cerdeña.","fuente":"https://www.lanuovasardegna.it/sassari/cronaca/2026/05/29/news/alghero-e-olbia-da-oggi-i-nuovi-collegamenti-aerei-verso-due-citta-europee-ecco-quali-sono-1.100876062"}]}'::jsonb,'{"resumen":"Con coche podéis enlazar calas y pueblos a vuestro ritmo; sin coche, usad Cagliari o Alghero como base única y excursiones en barco. Las distancias entre zonas son largas.","tren":{"nota":"Trenitalia cubre Cagliari y algunos tramos del sur y del norte, pero no llega a calas ni al Golfo di Orosei. El Trenino Verde es una experiencia turística, no transporte.","enlace":"https://www.trenitalia.com/"},"bus":null,"ferry":[{"operador":"Grimaldi Lines","ruta":"Barcelona – Porto Torres","nota":"Ruta activa en la web de puertos de Grimaldi. No verificamos frecuencia, duración ni admisión de vehículos: comprobadlo con la naviera.","enlace":"https://www.grimaldi-lines.com/en/harbor/barcelona/","fuente":"https://www.grimaldi-lines.com/en/harbor/barcelona/"}],"camper":{"operador":"Roadsurfer","nota":"Alquiler de furgonetas camper en Italia; enlazamos la página general del país, sin verificar oficina concreta en Cerdeña.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Búsqueda web y fetch estuvieron agotados al escribir este archivo: casi todos los enlaces de actividades son el patrón seguro de mapa, no webs oficiales (Su Nuraxi, Trenino Verde, Molentargius, La Pelosa, Cala Goloritzé tienen web oficial pero no la pudimos abrir).","Normas de acceso a La Pelosa y a Cala Goloritzé (cupo, pago, reserva) descritas en general; no hemos verificado cifras ni fechas de este año.","Cavalcata Sarda enlaza a la portada de sardegnaturismo.it sin haber abierto esa página en esta sesión.","Sin ruta aérea directa verificada desde Barcelona/Madrid; solo Olbia–Sevilla (Volotea).","Faltan bus ARST y horarios de barcos con enlace oficial; no se incluyen locales concretos."]'::jsonb,'{"zona":"cerdena","base":"cagliari","ciudad_referencia":"Cagliari","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":{"min":63,"max":132,"fuente":"https://www.booking.com/city/it/cagliari.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/cagliari","calidad":"orientativo"},"comida_barata":{"valor":20,"fuente":"https://www.numbeo.com/cost-of-living/in/Cagliari","calidad":"orientativo"},"transporte_billete":{"valor":1.3,"fuente":"https://www.ctmcagliari.it/wp-content/uploads/CTM_carta_dei_servizi.pdf","calidad":"verificado"}},"notas":"hostel_noche null: Hostelworld Cagliari (pagina cargada) no muestra ninguna cama en dormitorio (\"No Dorms Available\" / \"Add dates to see prices\"); sin cifra de dorm. doble_noche: min=63 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=132 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Cagliari (rango Numbeo 15-25). transporte_billete: CTM Cagliari, corsa semplice 90 min 1.30 EUR (Carta dei Servizi 2025-2026, revision 4 del 31-jul-2025)."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('cerdena','cagliari','Cagliari','La única base de la isla con mucho que hacer sin coche: Castello, mercado, Poetto en bus urbano y flamencos.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('cerdena','alghero','Alghero','Casco amurallado catalán con bastiones al atardecer y barco a la Grotta di Nettuno; el resto del noroeste pide coche.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('cerdena','cala-gonone','Cala Gonone','Puerto desde donde salen los barcos a Cala Luna y al Golfo di Orosei; pueblo pequeño y tranquilo, mejor con coche.','calma',false);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','castello-cagliari','cagliari','Barrio de Castello y murallas','Cagliari','cultura',array['postal']::text[],'medio_dia','manana','gratis',false,false,'medio','mixto',null,'Callejones medievales sobre la colina, catedral, torres pisanas y vistas a toda la bahía.','Subid caminando desde la Marina: hay cuestas y escaleras.','https://www.google.com/maps/search/?api=1&query=Quartiere+Castello%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Quartiere+Castello%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Quartiere+Castello%2C+Cagliari%2C+Italia',39.217,9.113);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','bastione-saint-remy','cagliari','Atardecer en el Bastione di Saint Remy','Cagliari','postal',array['fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',null,'Terraza monumental sobre el casco con vista a la ciudad y al mar; plan de aperitivo y fotos al atardecer.',null,'https://www.google.com/maps/search/?api=1&query=Bastione+di+Saint+Remy%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Bastione+di+Saint+Remy%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Bastione+di+Saint+Remy%2C+Cagliari%2C+Italia',39.216,9.115);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','mercato-san-benedetto','cagliari','Mercato civico di San Benedetto','Cagliari','gastronomia',array['cultura']::text[],'2h','manana','bajo',false,false,'bajo','social',null,'Mercado municipal grande con pescado fresco, quesos y embutidos sardos; se pica comida barata de pie.','Mejor por la mañana: los puestos cierran a mediodía.','https://www.google.com/maps/search/?api=1&query=Mercato+di+San+Benedetto%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Mercato+di+San+Benedetto%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Mercato+di+San+Benedetto%2C+Cagliari%2C+Italia',39.22,9.121);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','poetto','cagliari','Playa del Poetto','Cagliari','playa',array['agua']::text[],'dia_completo','cualquiera','gratis',false,false,'bajo','social',array[5,6,7,8,9]::int[],'Larga playa urbana de arena clara a las afueras de Cagliari, con chiringuitos y bus urbano desde el centro.',null,'https://www.google.com/maps/search/?api=1&query=Spiaggia+del+Poetto%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+del+Poetto%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Spiaggia+del+Poetto%2C+Cagliari%2C+Italia',39.2,9.17);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','molentargius','cagliari','Parque de Molentargius: flamencos','Cagliari','naturaleza',array['postal']::text[],'medio_dia','manana','bajo',false,false,'bajo','tranquilo',null,'Humedal junto al Poetto con salinas históricas y colonias de flamencos rosas, visible a pie o en bici.','Llevad prismáticos si tenéis; hay más fauna en invierno y primavera.','https://www.google.com/maps/search/?api=1&query=Parco+Naturale+Molentargius+Saline%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Parco+Naturale+Molentargius+Saline%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Parco+Naturale+Molentargius+Saline%2C+Cagliari%2C+Italia',39.23,9.16);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','sella-del-diavolo','cagliari','Ruta a la Sella del Diavolo','Cagliari','aventura',array['naturaleza','postal']::text[],'2h','tarde','gratis',false,false,'medio','mixto',array[3,4,5,6,9,10,11]::int[],'Senderismo corto hasta el promontorio sobre el Poetto, con vistas a la bahía de Cagliari.','Evitad el mediodía de verano: casi sin sombra.','https://www.google.com/maps/search/?api=1&query=Sella+del+Diavolo%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Sella+del+Diavolo%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Sella+del+Diavolo%2C+Cagliari%2C+Italia',39.176,9.2);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','anfiteatro-romano','cagliari','Anfiteatro romano de Cagliari','Cagliari','cultura',null,'2h','cualquiera','bajo',false,false,'bajo','tranquilo',null,'Anfiteatro excavado en la roca de época romana, a un paso de Castello; visita corta y fácil de encajar.',null,'https://www.google.com/maps/search/?api=1&query=Anfiteatro+Romano%2C+Cagliari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Anfiteatro+Romano%2C+Cagliari%2C+Italia','https://www.google.com/maps/search/?api=1&query=Anfiteatro+Romano%2C+Cagliari%2C+Italia',39.222,9.12);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','villasimius-capo-carbonara','cagliari','Villasimius y Capo Carbonara','Villasimius','playa',array['agua','naturaleza']::text[],'dia_completo','cualquiera','bajo',true,false,'bajo','social',array[6,7,8,9]::int[],'Costa al este de Cagliari con calas de arena blanca y agua clara; ideal para snorkel en verano.','Madrugad en julio-agosto o no habrá sitio para aparcar.','https://www.google.com/maps/search/?api=1&query=Villasimius%2C+Italia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Villasimius%2C+Italia%2C+Italia','https://www.google.com/maps/search/?api=1&query=Villasimius%2C+Italia%2C+Italia',39.138,9.52);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','su-nuraxi','cagliari','Su Nuraxi di Barumini','Barumini','cultura',array['postal']::text[],'medio_dia','manana','medio',true,false,'bajo','tranquilo',null,'Poblado nurágico de la Edad del Bronce declarado Patrimonio UNESCO, el mejor nuraghe de la isla.','Visita con guía recomendada.','https://www.google.com/maps/search/?api=1&query=Su+Nuraxi%2C+Barumini%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Su+Nuraxi%2C+Barumini%2C+Italia','https://www.google.com/maps/search/?api=1&query=Su+Nuraxi%2C+Barumini%2C+Italia',39.706,8.992);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','trenino-verde','cagliari','Trenino Verde Mandas–Arbatax','Mandas','naturaleza',array['postal']::text[],'dia_completo','manana','medio',false,true,'bajo','social',array[6,7,8,9]::int[],'Tren histórico de vía estrecha que cruza el interior por pueblos y montañas; viaje lento más que transporte.','Funciona sobre todo en temporada turística: comprobad fechas con la operadora.','https://www.google.com/maps/search/?api=1&query=Stazione+di+Mandas%2C+Italia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Stazione+di+Mandas%2C+Italia%2C+Italia','https://www.google.com/maps/search/?api=1&query=Stazione+di+Mandas%2C+Italia%2C+Italia',39.65,9.13);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','bastioni-alghero','alghero','Bastioni y atardecer en Alghero','Alghero','postal',array['fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',null,'Paseo por las murallas sobre el mar con aperitivo al atardecer; la imagen clásica de Alghero.',null,'https://www.google.com/maps/search/?api=1&query=Bastioni+Marco+Polo%2C+Alghero%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Bastioni+Marco+Polo%2C+Alghero%2C+Italia','https://www.google.com/maps/search/?api=1&query=Bastioni+Marco+Polo%2C+Alghero%2C+Italia',40.558,8.317);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('cerdena','centro-alghero','alghero','Casco antiguo catalán de Alghero','Alghero','cultura',array['compras']::text[],'medio_dia','tarde','gratis',false,false,'bajo','mixto',null,'Calles empedradas con herencia catalana (aún se habla alguerés), iglesias, torres y tiendas de coral.',null,'https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Alghero%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Alghero%2C+Italia','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Alghero%2C+Italia',40.557,8.32);
