insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('dolomitas','IT','Dolomitas: Alto Adige y Cortina','Dolomitas','Picos de cuento, rutas y nieve','{"mar":0,"montana":3,"ciudad":1,"campo":2,"fiesta":1,"calma":2,"cultura":1,"gastronomia":2,"naturaleza":3,"playa":0,"aventura":3,"postal":3}'::jsonb,'alto','{"ideales":[6,7,8,9,12,1,2,3],"aceptables":[5,10],"evitar":[4,11],"nota":"Jun-sep para rutas y lagos; dic-mar para nieve y mercadillos. Abril y noviembre es entretiempo: muchos teleféricos y refugios cierran."}'::jsonb,'suave',true,'{"necesidad":"util","nota":"Sin coche se hace Bolzano, Ortisei, Seceda y Alpe di Siusi con bus y teleférico. Con coche se llega a Tre Cime, Misurina, Funes y los puertos de montaña, pero hay peaje, accesos limitados en verano (Braies, Alpe di Siusi) y cadenas o neumáticos de invierno en temporada de nieve.","aeropuerto_recogida":"VRN","operadores":[{"nombre":"Sixt","enlace":"https://www.rentalcars.com/en/airport/it/vrn/sixt","fuente":"https://www.rentalcars.com/en/airport/it/vrn/sixt"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Verona.VRN.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Verona.VRN.AVIS.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Verona.VRN.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Verona.VRN.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"VRN","nombre":"Verona – Valerio Catullo","ciudad":"Verona","a_la_base":"Tren desde Verona Porta Nuova hacia Bolzano por la línea del Brennero; Verona queda a unos 90 km de Trento según Visit Trentino."},{"iata":"VCE","nombre":"Venecia – Marco Polo","ciudad":"Venecia","a_la_base":"Bus directo del aeropuerto a Cortina (servicio Cortina Express); para Bolzano, tren desde Venecia con cambio."},{"iata":"BZO","nombre":"Bolzano – Dolomiti","ciudad":"Bolzano","a_la_base":"A 57 km de Trento según Visit Trentino; vuelos muy limitados (Air A!ps)."},{"iata":"INN","nombre":"Innsbruck","ciudad":"Innsbruck","a_la_base":"Alternativa por el norte: tren por el Brennero a Bolzano."}],"desde_espana":"El acceso realista es Verona (Volotea desde Barcelona y Madrid) o Venecia (low cost más variado); Bergamo y Treviso también sirven con bus o tren. Comparad en el buscador: las frecuencias cambian cada temporada.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"VRN","aerolinea":"Volotea","nota":"ruta existente según la prensa del sector; frecuencias y temporada sin verificar","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"},{"origen":"Madrid","origen_iata":"MAD","destino_iata":"VRN","aerolinea":"Volotea","nota":"ruta existente según la prensa del sector; frecuencias y temporada sin verificar","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"}],"desde_italia":"Tren a Verona y regional hasta Bolzano (línea Verona–Brennero); desde Milán Bergamo hay FlixBus Orio al Serio–Bolzano. A Cortina, bus desde Venecia o desde Dobbiaco.","novedades":[{"nota":"Volotea estrenó en 2026 Verona–Málaga (desde el 1 de agosto, martes y sábado) y Verona–Menorca (desde el 2 de agosto, jueves y domingo). Comprobad si siguen en 2027.","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"}]}'::jsonb,'{"resumen":"Sin coche: tren a Bolzano y buses regionales con la Mobilcard, más teleféricos para subir. Con coche se añaden Tre Cime, Misurina y Funes, con aparcamientos de pago y accesos con reserva en verano.","tren":{"nota":"Trenitalia y Italo llegan hasta Verona; de ahí el tren regional sigue por el valle del Adigio a Trento, Bolzano y el Brennero.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"Südtirol Mobil (transporte público de Alto Adige)","nota":"La Mobilcard (1, 3 o 7 días) cubre buses, trenes y el trenino del Renon; no se confirma que incluya teleféricos. Se valida en cada viaje.","enlace":"https://www.suedtirolerland.it/it/service/trasporto-pubblico/mobilcard-alto-adige/","fuente":"https://www.suedtirolerland.it/it/service/trasporto-pubblico/mobilcard-alto-adige/"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de camper en Italia; solo hay página general del país, no de la zona. Encaja si queréis dormir sobre ruedas, pero en montaña el aparcamiento y los accesos tienen restricciones.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["No he verificado horarios ni precios de buses de montaña (Tre Cime, Funes, Passo Gardena); por eso esas actividades van con requiere_coche true.","Fecha del Christkindlmarkt de Bolzano de 2026 no publicada en la web consultada.","Venecia–Cortina en bus existe (Cortina Express) pero no se verificó operador oficial ni horarios.","No hay rutas aéreas España–BZO ni Ryanair verificadas; solo Volotea a Verona.","Falta una opción de bienestar o termas en Alto Adige; quedó fuera por no verificar fuente."]'::jsonb,'{"zona":"dolomitas","base":"bolzano","ciudad_referencia":"Bolzano","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":null,"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Bolzano-Bozen","calidad":"orientativo"},"transporte_billete":{"valor":2,"fuente":"https://www.suedtirolmobil.info/en/tickets/ticket-finder/single-tickets","calidad":"verificado"}},"notas":"hostel_noche null: Hostelworld muestra 0 hostels en Bolzano (pagina cargada: \"no Hostels available in Bolzano right now\"); sin dato de hostel en las fuentes abiertas. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/bolzano.html?selected_currency=EUR: precio ''From'' del titulo = 104 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Bolzano (Bolzano-Bozen) (rango Numbeo 10-20). transporte_billete: Altoadigemobilita/SASA: tarifa minima por trayecto 2.00 EUR (20 cent/km redondeado a 50 cent). La pagina NO da un precio fijo especifico del billete urbano de Bolzano; 2.00 es el minimo oficial."}'::jsonb);
