insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','seceda','ortisei','Seceda: cresta de las Odle','Ortisei','naturaleza',array['postal']::text[],'medio_dia','manana','medio',false,false,'medio','mixto',array[5,6,7,8,9,10]::int[],'Cabinovia Ortisei–Furnes y funivia hasta la cresta a 2.519 m; vistas de 360° a las Odle y el Sella.','Abierta en verano de finales de mayo a principios de noviembre según valgardena.it.','https://www.valgardena.it/it/vacanze-estive-dolomiti/impianti/','oficial','https://www.google.com/maps/search/?api=1&query=Seceda%2C+Ortisei%2C+Italia','https://www.valgardena.it/it/vacanze-estive-dolomiti/impianti/',46.567,11.72);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','alpe-siusi','ortisei','Alpe di Siusi en verano','Alpe di Siusi','naturaleza',array['postal']::text[],'dia_completo','manana','medio',false,false,'bajo','tranquilo',array[5,6,7,8,9,10]::int[],'Los prados alpinos más grandes de Europa: paseos llanos entre malghe con el Sciliar y el Sassolungo de fondo.','La carretera está cerrada al tráfico privado de 9:00 a 17:00; subid en cabinovia o con la línea de bus. Cabinovia Siusi–Alpe di Siusi desde finales de mayo; consultad fechas exactas en la web.','https://www.seiseralm.it/it/info-e-service/mobilita/accesso-all-alpe-di-siusi.html','oficial','https://www.google.com/maps/search/?api=1&query=Alpe+di+Siusi+en+verano%2C+Alpe+di+Siusi%2C+Italia','https://www.seiseralm.it/it/info-e-service/mobilita/accesso-all-alpe-di-siusi.html',46.54,11.62);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','tre-cime','cortina','Giro de las Tre Cime di Lavaredo','Tre Cime di Lavaredo','aventura',array['naturaleza','postal']::text[],'dia_completo','manana','medio',true,false,'medio','mixto',array[6,7,8,9]::int[],'Circuito de unos 9,5 km y 3 h desde el Rifugio Auronzo pasando por el Rifugio Lavaredo y el Locatelli; dificultad turística, unos 400 m de desnivel.','La carretera de acceso desde Misurina es de peaje; los refugios abren de junio a septiembre.','https://www.dolomiti.it/it/itinerari/trekking/giro-delle-tre-cime-di-lavaredo','oficial','https://www.google.com/maps/search/?api=1&query=Giro+de+las+Tre+Cime+di+Lavaredo%2C+Tre+Cime+di+Lavaredo%2C+Italia','https://www.dolomiti.it/it/itinerari/trekking/giro-delle-tre-cime-di-lavaredo',46.619,12.303);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','braies','bolzano','Lago di Braies','Lago di Braies','naturaleza',array['postal','agua']::text[],'medio_dia','manana','bajo',false,true,'bajo','mixto',array[5,6,7,8,9,10]::int[],'Vuelta de 4 km al lago esmeralda, con barca de remos en verano; es el más fotografiado de Alto Adige.','De julio a septiembre el valle solo se alcanza en transporte público, a pie, en bici o con reserva online; la web de turismo anuncia la línea 442 desde Dobbiaco/Villabassa.','https://www.suedtirolerland.it/it/cultura-e-territorio/natura-e-paesaggio/laghi/lago-di-braies/','oficial','https://www.google.com/maps/search/?api=1&query=Lago+di+Braies%2C+Lago+di+Braies%2C+Italia','https://www.suedtirolerland.it/it/cultura-e-territorio/natura-e-paesaggio/laghi/lago-di-braies/',46.694,12.085);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','otzi','bolzano','Museo Arqueológico de Alto Adige (Ötzi)','Bolzano','cultura',null,'2h','tarde','medio',false,false,'bajo','tranquilo',null,'Aquí está Ötzi, la momia de 5.300 años hallada en el glaciar; buen plan de día de lluvia.',null,'https://iceman.it/en/the-iceman/','oficial','https://www.google.com/maps/search/?api=1&query=Museo+Arqueol%C3%B3gico+de+Alto+Adige+%28%C3%96tzi%29%2C+Bolzano%2C+Italia','https://iceman.it/en/the-iceman/',46.498,11.356);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','mercatino-bolzano','bolzano','Mercadillo de Navidad de Bolzano','Bolzano','compras',array['gastronomia','fiesta']::text[],'2h','noche','gratis',false,false,'bajo','social',array[11,12]::int[],'Casetas en Piazza Walther con el abeto iluminado, vin brulé y dulces; es el mercado navideño más conocido de Italia.','Abre a finales de noviembre y sigue en diciembre; fechas de 2026 sin confirmar en la web consultada.','https://www.bolzano-bozen.it/en/blog-en/events-in-the-city-the-bolzano-christmas-market','oficial','https://www.google.com/maps/search/?api=1&query=Mercadillo+de+Navidad+de+Bolzano%2C+Bolzano%2C+Italia','https://www.bolzano-bozen.it/en/blog-en/events-in-the-city-the-bolzano-christmas-market',46.498,11.356);
