insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','ferrata-tridentina','ortisei','Vía ferrata Brigata Tridentina (Pisciadù)','Passo Gardena','aventura',array['naturaleza']::text[],'dia_completo','manana','medio',true,true,'alto','mixto',array[6,7,8,9]::int[],'Clásica ferrata del Sella con cascada y puentes colgantes; dificultad media, exige arnés, casco y kit de ferrata.','Solo sin experiencia con guía de montaña; no entréis con mal tiempo ni en cuanto haya nieve.','https://www.val-gardena.com/it/escursioni/dettaglio/ferrata-tridentina-pisciadu-dolomiti/','oficial','https://www.google.com/maps/search/?api=1&query=V%C3%ADa+ferrata+Brigata+Tridentina+%28Pisciad%C3%B9%29%2C+Passo+Gardena%2C+Italia','https://www.val-gardena.com/it/escursioni/dettaglio/ferrata-tridentina-pisciadu-dolomiti/',46.54,11.8);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('dolomitas','esqui-val-gardena','ortisei','Esquí en Val Gardena y Dolomiti Superski','Val Gardena','aventura',array['naturaleza']::text[],'dia_completo','manana','alto',false,true,'alto','social',array[12,1,2,3]::int[],'Pistas de la Val Gardena conectadas con el área Dolomiti Superski; forfait y material son el gasto grande del viaje.','Alquilad el material en el valle y comparad forfaits de varios días.','https://www.dolomitisuperski.com/it/Scopri/Zone-sciistiche/Val-Gardena/Impianti','oficial','https://www.google.com/maps/search/?api=1&query=Esqu%C3%AD+en+Val+Gardena+y+Dolomiti+Superski%2C+Val+Gardena%2C+Italia','https://www.dolomitisuperski.com/it/Scopri/Zone-sciistiche/Val-Gardena/Impianti',46.56,11.67);
