insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('dolomitas','Apertura de teleféricos de verano en Val Gardena','Ortisei y Seceda','cada año, desde mayo hasta principios de noviembre',array[5]::int[],null,'https://www.valgardena.it/it/vacanze-estive-dolomiti/impianti/','Abren Ortisei–Alpe di Siusi, Seceda y los remontes de la Alpe; en 2026 fue desde el 1 y el 22 de mayo.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('puglia-salento','IT','Puglia y Salento','Puglia-Salento','Pueblos blancos, barroco y mar turquesa','{"mar":3,"montana":0,"ciudad":2,"campo":2,"fiesta":2,"calma":2,"cultura":2,"gastronomia":3,"naturaleza":2,"playa":3,"aventura":1,"postal":3}'::jsonb,'medio','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8,1,2],"nota":"Mayo-junio y septiembre dan mar cálido sin masas; agosto es caro y abarrotado, y de noviembre a marzo no hay baño y muchos locales de playa cierran."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Sin coche se hacen Bari, Polignano, Monopoli, Ostuni, Alberobello, Lecce, Gallipoli y Otranto con trenes regionales y buses. Para las calas del Salento (Porto Selvaggio, Grotta della Poesia, Punta Prosciutto, Pescoluse) el coche es casi imprescindible porque el bus es escaso. Cuidado con las ZTL en los cascos antiguos.","aeropuerto_recogida":"BRI","operadores":[{"nombre":"Hertz (Bari, BRI)","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Bari.BRI.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Bari.BRI.HERTZ.cla.ksp"},{"nombre":"Europcar (Bari, BRI)","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Bari.BRI.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Bari.BRI.EUROPCAR.cla.ksp"},{"nombre":"Hertz (Brindisi, BDS)","enlace":"https://www.discovercars.com/es/partners/hertz-1861","fuente":"https://www.discovercars.com/es/partners/hertz-1861"}]}'::jsonb,'{"aeropuertos":[{"iata":"BRI","nombre":"Bari – Karol Wojtyła","ciudad":"Bari","a_la_base":"Tren desde la estación del aeropuerto a Bari Centrale (Trenitalia/Ferrotramviaria); el trayecto es corto, comprobad horarios."},{"iata":"BDS","nombre":"Brindisi – Salento","ciudad":"Brindisi","a_la_base":"Para el Salento profundo; sin coche es más lento: tren o bus a Brindisi/Lecce según horarios."}],"desde_espana":"Vueling y Ryanair son las opciones directas hacia Bari; Brindisi suele exigir escala. En verano hay más oferta que en invierno, así que conviene comparar fechas.","rutas_directas":[{"origen":"Girona","origen_iata":"GRO","destino_iata":"BRI","aerolinea":"Ryanair","nota":"Ruta anunciada para verano 2026; flightconnections lista 1 vuelo por semana. Comprobad temporada 2027.","fuente":"https://dosunos.aviacionline.com/ryanair-lanza-cinco-nuevas-rutas-desde-cinco-aeropuertos-de-espana"},{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"BRI","aerolinea":"Vueling","nota":"Según flightconnections, unos 6 vuelos por semana; no se sabe si es estacional.","fuente":"https://www.flightconnections.com/flights-from-bri-to-bcn"}],"desde_italia":"Trenitalia/Italo hasta Bari y Lecce por la costa adriática (Bolonia–Bari–Lecce en tren de alta velocidad o regional). FlixBus tiene buses a Bari.","novedades":[{"nota":"Ryanair confirmó para el verano 2026 una ruta directa Girona – Bari (BRI).","fuente":"https://dosunos.aviacionline.com/ryanair-lanza-cinco-nuevas-rutas-desde-cinco-aeropuertos-de-espana"}]}'::jsonb,'{"resumen":"Tren regional Trenitalia Bari–Polignano–Monopoli–Ostuni–Lecce, FSE hacia Alberobello y Otranto, y bus o coche para las calas. En el Salento profundo el coche manda.","tren":{"nota":"Línea Bari–Lecce con paradas en Polignano, Monopoli y Ostuni. Ferrovie del Sud Est (FSE) cubre Alberobello, Martina Franca y el sur del Salento (Lecce–Otranto).","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus (larga distancia)","nota":"Para conectar Bari con otras ciudades italianas; no cubre la llegada desde España ni las calas.","enlace":"https://www.flixbus.it/autobus/bari","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["No verifiqué horarios ni líneas exactas de Ferrovie del Sud Est (su web solo cargó una pantalla de espera); no hay enlace oficial de FSE en moverse.","Rutas desde España: solo BRI verificadas (Girona/Ryanair 1 vuelo semanal; Barcelona/Vueling). Brindisi sin directo a Barcelona según flightconnections.","Grotta della Poesia: acceso regulado y saltos peligrosos; la fuente verificada es una nota antigua de 2019, comprobad restricciones actuales.","Enlaces de Polignano, Lecce, Gallipoli y Porto Selvaggio son de italia.it; Monopoli, Ostuni, Otranto, Punta Prosciutto y Pescoluse usan guías privadas, no webs municipales.","Cavalcata de Sant''Oronzo y Focara: fechas exactas solo de fuentes secundarias.","Pasticciotto, burrata y tiella no tienen una fuente específica verificada; se citan por ser típicos.","Notte della Taranta 2027 no tiene fechas publicadas."]'::jsonb,'{"zona":"puglia-salento","base":"bari","ciudad_referencia":"Bari","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":24,"max":27,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/bari/","calidad":"orientativo"},"doble_noche":{"min":76,"max":146,"fuente":"https://www.booking.com/city/it/bari.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/bari","calidad":"orientativo"},"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Bari","calidad":"orientativo"},"transporte_billete":{"valor":1,"fuente":"https://www.amtab.it/en/trasporto-pubblico-locale-sub-3/titoli-di-viaggio-e-tariffe-2","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 4 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=20.0, maximo=27.0); son precios ''desde'' sin fechas concretas. doble_noche: min=76 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=146 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Bari (rango Numbeo 10-20). transporte_billete: AMTAB Bari, billete sencillo urbano 1.00 EUR; a bordo 1.50. La pagina no indica fecha."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('puglia-salento','bari','Bari','Aeropuerto y tren a Polignano, Monopoli y Alberobello, con la mejor comida callejera y alojamiento barato.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('puglia-salento','lecce','Lecce','Barroco, ambiente universitario y salidas a Otranto y a la costa; mejor con coche para las calas.','mixto',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('puglia-salento','gallipoli','Gallipoli','Playa y fiesta en verano a pie; cerca de Porto Selvaggio y Punta Prosciutto, pero caro en agosto.','fiesta',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('puglia-salento','ostuni','Ostuni','Pueblo blanco con masserie alrededor; calma y buena comida, y la estación está lejos del casco antiguo.','calma',false);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-orecchiette','bari','Orecchiette a mano en Arco Basso (Bari Vecchia)','Bari','gastronomia',array['cultura']::text[],'2h','manana','gratis',false,false,'bajo','social',null,'Callejón de Bari Vecchia donde las abuelas amasan orecchiette a mano a la puerta de casa, justo frente al castillo normando-suabo.','Mejor por la mañana, cuando trabajan; se pueden comprar bolsas sueltas para cocinar en el apartamento.','https://www.google.com/maps/search/?api=1&query=Arco+Basso%2C+Bari+Vecchia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Arco+Basso%2C+Bari+Vecchia%2C+Italia','https://gazzettadelgusto.it/cibo/strada-delle-orecchiette-a-bari-ecco-dove-si-trova/?print=pdf',41.129,16.871);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-street-food','bari','Ruta de street food barés','Bari','gastronomia',array['fiesta']::text[],'2h','tarde','bajo',false,false,'bajo','social',null,'Focaccia barese en panadería, panzerotti fritos de tomate y mozzarella, y sgagliozze (polenta frita en cucurucho) sentados en un escalón de Bari Vecchia.','Las sgagliozze suelen venderse desde media tarde y a veces solo se paga en efectivo; los panaderos de focaccia cierran algún día a la semana.','https://www.google.com/maps/search/?api=1&query=Bari+Vecchia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Bari+Vecchia%2C+Italia','https://doeatbetterexperience.com/it/blog/cosa-mangiare-a-bari/',41.126,16.871);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-san-nicola','bari','Basílica de San Nicolás y callejones de Bari Vecchia','Bari','cultura',array['postal']::text[],'2h','manana','gratis',false,false,'bajo','tranquilo',null,'Basílica románica donde descansan las reliquias de San Nicolás, rodeada de un laberinto de calles con ropa tendida y plazas diminutas.',null,'https://www.google.com/maps/search/?api=1&query=Basilica+di+San+Nicola%2C+Bari%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Basilica+di+San+Nicola%2C+Bari%2C+Italia','https://www.visititaly.eu/it/storie-e-tradizioni/nicola-il-santo-dei-baresi-venerato-in-tutto-il-mondo',41.128,16.871);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','polignano-lama-monachile','bari','Lama Monachile y casco antiguo de Polignano a Mare','Polignano a Mare','playa',array['postal','agua']::text[],'medio_dia','cualquiera','gratis',false,false,'bajo','social',array[5,6,7,8,9]::int[],'Cala de guijarros encajada entre acantilados bajo un puente romano, con el casco antiguo blanco encima y la estatua de Domenico Modugno en el paseo.','En verano se llena a partir de media mañana: llegad temprano. Polignano tiene estación de tren en la línea Bari–Lecce.','https://www.italia.it/it/puglia/bari/polignano','oficial','https://www.google.com/maps/search/?api=1&query=Lama+Monachile%2C+Polignano+a+Mare%2C+Italia','https://www.italia.it/it/puglia/bari/polignano',40.996,17.219);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','polignano-grutas-barco','bari','Barco por las cuevas marinas de Polignano','Polignano a Mare','agua',array['aventura','postal']::text[],'2h','manana','medio',false,true,'bajo','social',array[5,6,7,8,9]::int[],'Salida corta en barca para ver desde el mar las cuevas del acantilado, como la Grotta Palazzese, la mayor de unas veinte.','Se reserva por internet o en el puerto; comparad duración y baño incluido.','https://www.getyourguide.es/s/?q=Polignano+a+Mare+barco+cuevas','reserva','https://www.google.com/maps/search/?api=1&query=Polignano+a+Mare+porto%2C+Italia','https://www.italia.it/it/puglia/bari/polignano',40.996,17.219);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','polignano-atardecer','bari','Atardecer en los miradores de Polignano','Polignano a Mare','postal',array['naturaleza']::text[],'2h','noche','gratis',false,false,'bajo','tranquilo',null,'Miradores sobre el acantilado y paseo por las murallas con el sol cayendo sobre el Adriático; la luz es el mejor plan gratis del pueblo.',null,'https://www.italia.it/it/puglia/bari/polignano','oficial','https://www.google.com/maps/search/?api=1&query=Terrazza+Santo+Stefano%2C+Polignano+a+Mare%2C+Italia','https://www.italia.it/it/puglia/bari/polignano',40.995,17.22);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','monopoli','bari','Monopoli: puerto viejo y murallas','Monopoli','cultura',array['postal','playa']::text[],'medio_dia','cualquiera','gratis',false,false,'bajo','mixto',null,'Pueblo costero con puerto de barcas de colores, casco antiguo blanco y pequeñas calas urbanas; más tranquilo que Polignano.',null,'https://www.google.com/maps/search/?api=1&query=Porto+Vecchio%2C+Monopoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Porto+Vecchio%2C+Monopoli%2C+Italia','https://www.itinerarinelgusto.it/en/apulia/monopoli-ba',40.952,17.299);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','alberobello-trulli','bari','Alberobello: Rione Monti y trulli','Alberobello','cultura',array['postal']::text[],'medio_dia','manana','bajo',false,false,'bajo','mixto',null,'Barrio Patrimonio UNESCO con más de mil casas de piedra seca de techo cónico, hoy tiendas y bares. Se ve en medio día.','Sin coche: tren de Ferrovie del Sud Est desde Bari (confirmad horarios en su web) o combinación con Trenitalia. Id temprano para evitar autocares.','https://whc.unesco.org/en/list/787','oficial','https://www.google.com/maps/search/?api=1&query=Rione+Monti%2C+Alberobello%2C+Italia','https://whc.unesco.org/en/list/787',40.783,17.237);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','ostuni-citta-bianca','ostuni','Ostuni, la Ciudad Blanca','Ostuni','cultura',array['postal']::text[],'medio_dia','tarde','gratis',false,false,'medio','tranquilo',null,'Casco antiguo encalado en lo alto de una colina, de calles empinadas y arcos; mejor a la hora del atardecer.','La estación de Ostuni está en la línea Bari–Lecce pero lejos del casco antiguo; se sube en bus o taxi.','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Ostuni%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Ostuni%2C+Italia','https://www.ilturista.info/guide/ostuni-puglia-spiagge-cosa-vedere-centro-storico-citta-bianca-salento/',40.73,17.577);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','lecce-barocco','lecce','Lecce barroca: Piazza Duomo y Santa Croce','Lecce','cultura',array['postal']::text[],'medio_dia','cualquiera','gratis',false,false,'bajo','mixto',null,'Fachadas de piedra dorada labradas con ángeles y frutas, plazas y palacios; la ciudad más bonita del sur y se recorre a pie.',null,'https://www.italia.it/en/puglia/lecce','oficial','https://www.google.com/maps/search/?api=1&query=Piazza+del+Duomo%2C+Lecce%2C+Italia','https://www.italia.it/it/puglia/lecce/guida-storia-curiosita',40.352,18.172);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','lecce-aperitivo','lecce','Aperitivo en el centro de Lecce','Lecce','fiesta',array['gastronomia']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Noche de plaza y callejones del casco antiguo: aperitivo, tapas pugliesi y copas con mucho ambiente universitario.',null,'https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Lecce%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Lecce%2C+Italia','https://www.italia.it/en/puglia/lecce',40.353,18.174);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','otranto','lecce','Otranto: catedral, murallas y calas','Otranto','cultura',array['playa','postal']::text[],'dia_completo','cualquiera','bajo',false,false,'bajo','mixto',null,'Pueblo amurallado sobre el mar más oriental de Italia, con catedral de suelo de mosaico y calas de agua turquesa al lado.','Hay trenes regionales de Ferrovie del Sud Est entre Lecce y Otranto; comprobad horarios, son pocos.','https://www.google.com/maps/search/?api=1&query=Cattedrale+di+Otranto%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Cattedrale+di+Otranto%2C+Italia','https://www.museionline.info/tipologie-museo/cattedrale-di-otranto',40.146,18.49);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','porto-selvaggio','gallipoli','Porto Selvaggio y Torre Uluzzo','Nardò','naturaleza',array['playa','aventura']::text[],'dia_completo','manana','gratis',true,false,'medio','tranquilo',array[5,6,7,8,9,10]::int[],'Parque natural: sendero entre pinos hasta una cala de guijarros con agua limpia y acantilados, con torre del siglo XVI sobre la roca.','Llevad agua, calzado cerrado y bolsa para la basura; no hay servicios en la cala y la bajada se hace a pie.','https://www.italia.it/it/puglia/lecce/parco-naturale-di-porto-selvaggio-e-palude-del-capitano','oficial','https://www.google.com/maps/search/?api=1&query=Parco+Naturale+Porto+Selvaggio%2C+Nard%C3%B2%2C+Italia','https://www.italia.it/it/puglia/lecce/parco-naturale-di-porto-selvaggio-e-palude-del-capitano',40.167,17.957);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','grotta-poesia','lecce','Grotta della Poesia (Roca Vecchia)','Melendugno','agua',array['naturaleza','aventura']::text[],'medio_dia','manana','gratis',true,false,'bajo','social',array[6,7,8,9]::int[],'Piscina natural en la roca junto al yacimiento de Roca Vecchia, con agua turquesa y saltos desde unos 5 metros.','El acceso está regulado y la zona ha tenido restricciones y accidentes por saltos con poca profundidad: mirad las normas locales antes de ir y no saltéis sin comprobar.','https://www.google.com/maps/search/?api=1&query=Grotta+della+Poesia%2C+Roca+Vecchia%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Grotta+della+Poesia%2C+Roca+Vecchia%2C+Italia','https://www.greenme.it/viaggi/italia/grotta-della-poesia-salento/',40.297,18.428);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','punta-prosciutto','gallipoli','Punta Prosciutto: dunas y mar caribeño','Porto Cesareo','playa',array['naturaleza']::text[],'dia_completo','cualquiera','gratis',true,false,'bajo','tranquilo',array[6,7,8,9]::int[],'Kilómetros de arena clara y dunas con agua poco profunda en el Jónico; la playa más parecida al Caribe del Salento.',null,'https://www.google.com/maps/search/?api=1&query=Punta+Prosciutto%2C+Porto+Cesareo%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Punta+Prosciutto%2C+Porto+Cesareo%2C+Italia','https://www.greenme.it/viaggi/punta-prosciutto-spiaggia-salento/',40.27,17.762);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','pescoluse','gallipoli','Pescoluse, las Maldivas del Salento','Salve','playa',array['agua']::text[],'dia_completo','cualquiera','gratis',true,false,'bajo','social',array[6,7,8,9]::int[],'Playa larga de arena fina blanca y agua baja y cristalina; hay zonas libres y chiringuitos.',null,'https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Pescoluse%2C+Salve%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Pescoluse%2C+Salve%2C+Italia','https://www.spiagge.it/magazine/le-maldive-del-salento-i-tropici-tutti-italiani/',39.833,18.283);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-centro','gallipoli','Centro histórico de Gallipoli','Gallipoli','cultura',array['postal']::text[],'medio_dia','tarde','gratis',false,false,'bajo','mixto',null,'Casco antiguo en una isla unida por un puente: murallas, puerto de pesca, iglesias barrocas y callejones blancos.',null,'https://www.italia.it/pt/apulia/lecce/galipoli','oficial','https://www.google.com/maps/search/?api=1&query=Centro+storico%2C+Gallipoli%2C+Italia','https://www.italia.it/pt/apulia/lecce/galipoli',40.056,17.979);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-purita','gallipoli','Spiaggia della Purità','Gallipoli','playa',array['postal']::text[],'medio_dia','cualquiera','gratis',false,false,'bajo','social',array[6,7,8,9]::int[],'Playa de arena a los pies de las murallas, con baño y vistas al casco antiguo; sin coche y a cinco minutos de todo.',null,'https://www.google.com/maps/search/?api=1&query=Spiaggia+della+Purit%C3%A0%2C+Gallipoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+della+Purit%C3%A0%2C+Gallipoli%2C+Italia','https://travel.thewom.it/italia/puglia/spiagge-gallipoli.html',40.057,17.976);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-fiesta-verano','gallipoli','Fiesta de verano en Gallipoli','Gallipoli','fiesta',array['musica']::text[],'2h','noche','medio',false,false,'bajo','social',array[6,7,8,9]::int[],'En julio y agosto el casco antiguo y los locales de playa se llenan de gente; es el sitio de más ambiente del Salento.','Mejor evitar agosto si queréis dormir barato: los precios se disparan.','https://www.google.com/maps/search/?api=1&query=Gallipoli+centro+storico%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Gallipoli+centro+storico%2C+Italia','https://travel.thewom.it/italia/puglia/spiagge-gallipoli.html',40.056,17.979);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','pizzica-salento','lecce','Noches de pizzica en pueblos del Salento','Melpignano y Grecía Salentina','musica',array['fiesta','cultura']::text[],'2h','noche','gratis',true,false,'bajo','social',array[7,8]::int[],'Música popular salentina con tambores y baile en plazas y fiestas de pueblo durante el verano; la Notte della Taranta es la cita grande.','Los pueblos de la Grecìa Salentina están a unos 25-35 km de Lecce; sin coche, mirad las salidas de bus nocturnas o id en grupo con taxi compartido.','https://www.lanottedellataranta.it/','oficial','https://www.google.com/maps/search/?api=1&query=Melpignano%2C+Italia','https://www.lanottedellataranta.it/',40.168,18.3);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-lungomare-murat','bari','Lungomare de Bari y barrio Murat','Bari','postal',array['compras']::text[],'2h','tarde','gratis',false,false,'bajo','tranquilo',null,'Paseo marítimo de farolas de hierro frente al Adriático y vuelta por la cuadrícula del barrio Murat, la zona de tiendas.','','https://www.google.com/maps/search/?api=1&query=Teatro%20Margherita%2C%20Bari%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Teatro%20Margherita%2C%20Bari%2C%20Italia',null,41.1225,16.875);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-castello-svevo','bari','Castello Svevo de Bari','Bari','cultura',null,'1h','cualquiera','bajo',false,false,'bajo','tranquilo',null,'Fortaleza normanda y suaba pegada a Bari Vecchia, con foso y patio interior.','La entrada es de pago: mirad precio y horario antes de ir. Por fuera se rodea gratis.','https://www.google.com/maps/search/?api=1&query=Castello%20Svevo%2C%20Bari','mapa','https://www.google.com/maps/search/?api=1&query=Castello%20Svevo%2C%20Bari',null,41.1283,16.8662);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','bari-pane-pomodoro','bari','Playa de Pane e Pomodoro','Bari','playa',null,'2h','cualquiera','gratis',false,false,'bajo','social',array[6,7,8,9]::int[],'La playa de ciudad de los bareses, de arena y a un paseo por el lungomare desde el centro.','','https://www.google.com/maps/search/?api=1&query=Spiaggia%20Pane%20e%20Pomodoro%2C%20Bari','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia%20Pane%20e%20Pomodoro%2C%20Bari',null,41.1175,16.8905);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','trani-catedral','bari','Trani: la catedral sobre el mar','Trani','cultura',null,'medio_dia','cualquiera','gratis',false,false,'bajo','tranquilo',null,'Pueblo de piedra clara con una catedral románica levantada al borde del agua y un puerto de pescadores lleno de terrazas.','Se llega en tren regional desde Bari.','https://www.google.com/maps/search/?api=1&query=Cattedrale%20di%20Trani%2C%20Trani%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Cattedrale%20di%20Trani%2C%20Trani%2C%20Italia',null,41.2822,16.4185);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','castel-del-monte','bari','Castel del Monte','Andria','cultura',null,'medio_dia','cualquiera','bajo',true,false,'bajo','tranquilo',null,'El castillo octogonal de Federico II, solo en lo alto de una colina de la Murgia. Patrimonio de la Humanidad.','Entrada de pago; en temporada alta el aparcamiento está abajo y se sube en lanzadera o andando.','https://www.google.com/maps/search/?api=1&query=Castel%20del%20Monte%2C%20Andria','mapa','https://www.google.com/maps/search/?api=1&query=Castel%20del%20Monte%2C%20Andria',null,41.0847,16.2709);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','locorotondo','bari','Locorotondo, el pueblo redondo','Locorotondo','postal',null,'2h','cualquiera','gratis',false,false,'bajo','tranquilo',null,'Casco antiguo circular y blanquísimo, de tejados a dos aguas, con balcón sobre los viñedos y trulli del Valle d''Itria.','Está a una parada de tren de Alberobello.','https://www.google.com/maps/search/?api=1&query=Porta%20Napoli%2C%20Locorotondo%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Porta%20Napoli%2C%20Locorotondo%2C%20Italia','https://www.conociendoitalia.com/apulia-en-10-dias-itinerario/',40.7555,17.3265);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','martina-franca','ostuni','Martina Franca barroca','Martina Franca','cultura',null,'2h','cualquiera','gratis',false,false,'bajo','tranquilo',null,'La ciudad barroca del Valle d''Itria: palacios con balcones de hierro, una basílica enorme y plazas porticadas.','','https://www.google.com/maps/search/?api=1&query=Arco%20di%20Sant''Antonio%2C%20Martina%20Franca%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Arco%20di%20Sant''Antonio%2C%20Martina%20Franca%2C%20Italia',null,40.705,17.339);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','lecce-pasticciotto','lecce','Desayuno de pasticciotto y caffè leccese','Lecce','gastronomia',null,'1h','manana','bajo',false,false,'bajo','tranquilo',null,'El desayuno de Lecce: pasticciotto recién hecho (masa quebrada rellena de crema) y café con hielo y leche de almendra.','','https://www.google.com/maps/search/?api=1&query=pasticceria%20Piazza%20Sant''Oronzo%2C%20Lecce','mapa','https://www.google.com/maps/search/?api=1&query=pasticceria%20Piazza%20Sant''Oronzo%2C%20Lecce',null,40.3529,18.1724);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','lecce-castello-villa','lecce','Castello Carlo V y Villa Comunale de Lecce','Lecce','cultura',null,'1h','cualquiera','gratis',false,false,'bajo','tranquilo',null,'La fortaleza del siglo XVI junto al centro y el jardín público donde pasean los leccesi.','El interior del castillo puede ser de pago según la exposición.','https://www.google.com/maps/search/?api=1&query=Castello%20Carlo%20V%2C%20Lecce%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Castello%20Carlo%20V%2C%20Lecce%2C%20Italia',null,40.353,18.1748);
