insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-murallas-atardecer','gallipoli','Vuelta a las murallas de Gallipoli al atardecer','Gallipoli','postal',null,'1h','noche','gratis',false,false,'bajo','tranquilo',null,'El paseo que rodea la isla del casco antiguo mira a poniente: el sol cae sobre el mar frente a la Purità.','','https://www.google.com/maps/search/?api=1&query=Riviera%20Nazario%20Sauro%2C%20Gallipoli%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Riviera%20Nazario%20Sauro%2C%20Gallipoli%2C%20Italia',null,40.0553,17.9752);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-mercado-pescado','gallipoli','Mercado del pescado de Gallipoli','Gallipoli','gastronomia',null,'1h','manana','bajo',false,false,'bajo','social',null,'Los puestos junto al puente y el castillo donde descargan las barcas: erizos, gambas rojas y pescado crudo para tomar allí mismo.','','https://www.google.com/maps/search/?api=1&query=Mercato%20del%20pesce%2C%20Gallipoli','mapa','https://www.google.com/maps/search/?api=1&query=Mercato%20del%20pesce%2C%20Gallipoli',null,40.0563,17.9822);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','gallipoli-baia-verde','gallipoli','Playas de Baia Verde','Gallipoli','playa',null,'medio_dia','cualquiera','bajo',false,false,'bajo','social',array[6,7,8,9]::int[],'Kilómetros de arena al sur de Gallipoli, con chiringuitos de música y tramos libres.','Los lidos cobran por hamaca; entre uno y otro hay playa libre.','https://www.google.com/maps/search/?api=1&query=Baia%20Verde%2C%20Gallipoli','mapa','https://www.google.com/maps/search/?api=1&query=Baia%20Verde%2C%20Gallipoli','https://www.conociendoitalia.com/apulia-en-10-dias-itinerario/',40.033,18.008);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','monopoli-cala','bari','Baño en Cala Porta Vecchia','Monopoli','playa',null,'2h','cualquiera','gratis',false,false,'bajo','tranquilo',array[6,7,8,9]::int[],'La cala de arena al pie de las murallas de Monopoli, a dos minutos del casco antiguo.','','https://www.google.com/maps/search/?api=1&query=Cala%20Porta%20Vecchia%2C%20Monopoli','mapa','https://www.google.com/maps/search/?api=1&query=Cala%20Porta%20Vecchia%2C%20Monopoli',null,40.9505,17.306);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','torre-sant-andrea','lecce','Farallones de Torre Sant''Andrea','Melendugno','postal',null,'2h','cualquiera','gratis',true,false,'bajo','tranquilo',array[4,5,6,7,8,9,10]::int[],'Arcos y agujas de roca blanca saliendo de un agua verde, en la costa adriática del Salento.','','https://www.google.com/maps/search/?api=1&query=Faraglioni%20di%20Sant''Andrea%2C%20Melendugno','mapa','https://www.google.com/maps/search/?api=1&query=Faraglioni%20di%20Sant''Andrea%2C%20Melendugno',null,40.2555,18.4445);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('puglia-salento','cisternino','ostuni','Cisternino al caer la tarde','Cisternino','postal',array['gastronomia']::text[],'2h','tarde','gratis',false,false,'bajo','tranquilo',null,'Pueblo blanco del Valle d''Itria con balcones sobre el valle; famoso por sus «fornelli», carnicerías que te asan la carne al momento.','Se combina bien con Ostuni el mismo día.','https://www.google.com/maps/search/?api=1&query=Piazza%20Vittorio%20Emanuele%2C%20Cisternino%2C%20Italia','mapa','https://www.google.com/maps/search/?api=1&query=Piazza%20Vittorio%20Emanuele%2C%20Cisternino%2C%20Italia',null,40.7425,17.425);
