insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('puglia-salento','La Notte della Taranta','Melpignano y pueblos de la Grecìa Salentina','cada año, conciertos de pizzica en pueblos desde finales de julio y concertone final en Melpignano a finales de agosto (en 2026 fue el 22 de agosto)',array[7,8]::int[],null,'https://www.lanottedellataranta.it/','El mayor festival de música popular de Italia: pizzica y tarantella por pueblos del Salento y un gran concierto gratuito final.');
