insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('puglia-salento','Focara de Novoli','Novoli (Lecce)','cada año, 16-17 de enero',array[1]::int[],null,'https://www.eventiesagre.it/Eventi_Feste/4528_La+Focara+di+Novoli.html','Una hoguera gigante de sarmientos en honor a San Antonio Abad, con música y fiesta en el pueblo.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('liguria-cinque-terre','IT','Liguria y Cinque Terre','Liguria','Pueblos colgados del mar y Génova','{"mar":3,"montana":1,"ciudad":2,"campo":1,"fiesta":1,"calma":2,"cultura":2,"gastronomia":3,"naturaleza":3,"playa":2,"aventura":2,"postal":3}'::jsonb,'medio','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11],"evitar":[1,2,8],"nota":"Mayo-junio y septiembre-octubre: buen tiempo para caminar y menos masificación. En agosto hay colas, calor y precios altos; en invierno hay barcos limitados y algunos senderos cerrados."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Los pueblos de Cinque Terre son prácticamente peatonales y el tren los une; en Génova hay ZTL y aparcamiento caro. Solo compensa para calas o pueblos fuera de la línea de tren, y aun así el aparcamiento es el problema.","aeropuerto_recogida":"GOA","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Genova.GOA.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Genova.GOA.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Genova.GOA.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Genova.GOA.EUROPCAR.cla.ksp"},{"nombre":"Sixt","enlace":"https://www.skyscanner.com.mx/mx/it-it/mxn/noleggio-auto/fornitore-aeroporto/673/goa","fuente":"https://www.skyscanner.com.mx/mx/it-it/mxn/noleggio-auto/fornitore-aeroporto/673/goa"}]}'::jsonb,'{"aeropuertos":[{"iata":"GOA","nombre":"Génova – Cristoforo Colombo","ciudad":"Génova","a_la_base":"Está en Sestri Ponente, dentro de la ciudad; se llega a Génova en bus urbano o taxi y de ahí tren a La Spezia o Cinque Terre."},{"iata":"PSA","nombre":"Pisa – Galileo Galilei","ciudad":"Pisa","a_la_base":"PisaMover o bus a Pisa Centrale y tren regional a La Spezia; comprobad el trasbordo en Trenitalia."},{"iata":"MXP","nombre":"Milán – Malpensa","ciudad":"Milán","a_la_base":"Tren o bus a Milán y de ahí tren a Génova o La Spezia; más largo pero con más vuelos low cost."}],"desde_espana":"El aeropuerto de referencia es Génova, con oferta limitada desde España. Pisa y Milán suelen tener más vuelos low cost, a cambio de un trayecto en tren más largo.","rutas_directas":[{"origen":"Madrid","origen_iata":"MAD","destino_iata":"GOA","aerolinea":"Volotea","nota":"Dos frecuencias semanales (lunes y viernes) desde la inauguración en diciembre de 2025; comprobad que siga operativa","fuente":"https://genovaquotidiana.com/2025/12/05/volotea-inaugura-il-volo-genova-madrid-e-punta-a-44-di-posti-nel-2026/"}],"desde_italia":"Desde Milán hay trenes a Génova y a La Spezia, normalmente con trasbordo según la hora. Desde Florencia o Bolonia, tren a Pisa y de ahí a La Spezia."}'::jsonb,'{"resumen":"Sin coche: tren regional entre La Spezia y los cinco pueblos y senderos a pie; en Génova, metro y bus urbano. El coche estorba más que ayuda.","tren":{"nota":"Trenitalia regional entre La Spezia y Levanto (cada pueblo tiene estación) y Génova–La Spezia por la costa. La Cinque Terre Card del Parque incluye servicios como los trenes entre pueblos; mirad qué incluye hoy en la web del Parque.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Conecta Génova con otras ciudades italianas; no sirve para moverse entre los pueblos de Cinque Terre.","enlace":"https://www.flixbus.it/autobus/genova","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia (enlace a la página general). Dentro de los pueblos de Cinque Terre no se puede circular.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["No se verificó el estado actual de cada tramo del Sentiero Azzurro ni qué incluye hoy la Cinque Terre Card (precios y condiciones en la web del Parque): comprobadlo antes de ir.","No se verificó web oficial de los barcos ni del tren 5 Terre Express: se usa Trenitalia y GetYourGuide como patrón seguro.","No se encontró fuente fiable para la Sagra del Pesce de Camogli ni el Salone Nautico de Génova; se dejan fuera.","Los eventos de Rolli Days, Walking Park y Montale se describen como recurrentes con fechas variables; faltan fechas de 2027.","No hay rutas aéreas directas verificadas salvo Madrid–Génova (Volotea); nada desde Barcelona."]'::jsonb,'{"zona":"liguria-cinque-terre","base":"la-spezia","ciudad_referencia":"La Spezia","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":26,"max":36.1,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/la-spezia/","calidad":"orientativo"},"doble_noche":{"min":55,"max":226,"fuente":"https://www.booking.com/city/it/la-spezia.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/la-spezia","calidad":"orientativo"},"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/La-Spezia?displayCurrency=EUR","calidad":"orientativo"},"transporte_billete":{"valor":1.5,"fuente":"https://www.atcesercizio.it/en/biglietti/","calidad":"verificado"}},"notas":"hostel_noche: rango min-max de 3 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=26.0, maximo=36.1); son precios ''desde'' sin fechas concretas. doble_noche: min=55 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=226 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en La Spezia (rango Numbeo 10-20). transporte_billete: ATC Esercizio La Spezia, billete urbano ordinario 60 min 1.50 EUR comprado por SMS (solo SIM italiana); en el bus (codigo 00-01, solo antes de 7:30 y desde 19:00) cuesta 2.50 EUR."}'::jsonb);
