insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('umbria','IT','Umbria','Umbría','Pueblos de piedra sin la multitud','{"mar":0,"montana":2,"ciudad":2,"campo":3,"fiesta":1,"calma":3,"cultura":3,"gastronomia":3,"naturaleza":3,"playa":0,"aventura":1,"postal":2}'::jsonb,'medio','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11],"evitar":[8],"nota":"Primavera y otoño: temperatura agradable; agosto agobia en los valles."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Perugia, Asís, Spello y Orvieto funcionan en tren, con minimetro en Perugia; Gubbio, Marmore y el lago tienen bus. Montefalco y Norcia solo van bien con coche. Los centros tienen ZTL.","aeropuerto_recogida":"PEG","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Perugia.PEG.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Perugia.PEG.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Perugia.PEG.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Perugia.PEG.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.it/noleggio-auto/Avis-Perugia.PEG.AVIS.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Avis-Perugia.PEG.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"PEG","nombre":"Perugia – San Francesco d''Assisi","ciudad":"Perugia","a_la_base":"Está a pocos km de Perugia; comprobad en la web del aeropuerto el medio de conexión."},{"iata":"FCO","nombre":"Roma – Fiumicino","ciudad":"Roma","a_la_base":"Tren a Roma Termini y, desde allí, tren a Orvieto o Perugia, con trasbordo."}],"desde_espana":"Ryanair ha volado Barcelona–Perugia en verano de 2026; desde otras ciudades lo normal es volar a Roma y seguir en tren.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"PEG","aerolinea":"Ryanair","nota":"estacional, verano 2026; comprobad otras temporadas","fuente":"https://corporate.ryanair.com/novita/ryanair-lancia-loperativo-per-lestate-2026-a-perugia/"}],"desde_italia":"Orvieto está en la línea Roma–Florencia; Perugia y Asís tienen trenes regionales desde Roma y Florencia; FlixBus también cubre Perugia.","novedades":[{"nota":"Ryanair confirmó para verano 2026 Barcelona–Perugia entre las 10 rutas de su temporada.","fuente":"https://corporate.ryanair.com/novita/ryanair-lancia-loperativo-per-lestate-2026-a-perugia/"}]}'::jsonb,'{"resumen":"Tren regional entre Perugia, Asís, Spello y Orvieto. Para Norcia, Montefalco y el Trasimeno, el coche manda.","tren":{"nota":"Trenitalia cubre Perugia–Asís–Spello y Orvieto.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Cubre Perugia y otras ciudades dentro de Italia; para pueblos pequeños hay bus regional con pocas frecuencias.","enlace":"https://www.flixbus.it/autobus/perugia","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia; enlace a la página general.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Termas libres de Toscana no tienen equivalente verificado en Umbría.","Enlaces de Perugia, Montefalco y Norcia son mapa o fuente general porque no se verificó web oficial propia.","No se verificó el horario real de buses a Gubbio, Marmore ni el barco del lago.","Spoleto y Castelluccio quedan fuera por falta de fuente verificada.","Fechas 2027 de eventos sin confirmar."]'::jsonb,'{"zona":"umbria","base":"perugia","ciudad_referencia":"Perugia","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":22.77,"max":38.5,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/perugia/","calidad":"orientativo"},"doble_noche":null,"comida_barata":{"valor":14,"fuente":"https://www.numbeo.com/cost-of-living/in/Perugia","calidad":"orientativo"},"transporte_billete":{"valor":1.5,"fuente":"https://www.fsbusitalia.it/it/umbria/titoli-di-viaggio-tariffe-umbria/biglietti-tariffe-servizi-urbani-umbria/tariffe-perugia.html","calidad":"verificado"}},"notas":"hostel_noche: rango min-max de 2 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=22.77, maximo=38.5); son precios ''desde'' sin fechas concretas. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/perugia.html?selected_currency=EUR: precio ''From'' del titulo = 62 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Perugia (rango Numbeo 12-20). transporte_billete: Busitalia Umbria, corsa semplice ordinaria urbana Perugia 70 min 1.50 EUR; a bordo 2.00."}'::jsonb);
