insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('umbria','orvieto','Orvieto','Pueblo sobre una roca con tren directo desde Roma y Florencia; plan de una noche o de excursión.','calma',true);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','perugia-centro','perugia','Perugia: Corso Vannucci, Fontana Maggiore y Rocca Paolina','Perugia','cultura',array['postal']::text[],'medio_dia','cualquiera','bajo',false,false,'medio','mixto',null,'Centro medieval en lo alto de la colina: Fontana Maggiore, escalinata del Duomo y la fortaleza subterránea de la Rocca Paolina.','Desde la estación hay minimetro hasta el centro, que evita la cuesta.','https://www.visititaly.eu/it/luoghi-e-itinerari/visita-perugia-sul-minimetro','mapa','https://www.google.com/maps/search/?api=1&query=Fontana+Maggiore%2C+Perugia%2C+Italia','https://www.visititaly.eu/it/luoghi-e-itinerari/visita-perugia-sul-minimetro',43.112,12.389);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','perugia-noche','perugia','Perugia de noche: escalinata del Duomo y Corso Vannucci','Perugia','fiesta',array['musica']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Perugia es ciudad de estudiantes, con la Università degli Studi y la Università per Stranieri; el ambiente se concentra en la escalinata del Duomo y las calles vecinas.',null,'https://www.universita.it/universita-di-perugia-tra-cultura-e-gastronomia/','oficial','https://www.google.com/maps/search/?api=1&query=Corso+Vannucci%2C+Perugia%2C+Italia','https://www.universita.it/universita-di-perugia-tra-cultura-e-gastronomia/',43.113,12.389);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','asis-basilica','asis','Asís: Basílica de San Francisco','Asís','cultura',array['postal']::text[],'medio_dia','manana','gratis',false,false,'medio','tranquilo',null,'Los frescos de Giotto y la tumba de San Francisco, en un pueblo de piedra rosa que se hace en tren desde Perugia.','Vestid con hombros y rodillas cubiertos; es lugar de culto.','https://www.umbriatourism.it/-/basilica-of-saint-francis-of-assisi','oficial','https://www.google.com/maps/search/?api=1&query=Basilica+di+San+Francesco%2C+As%C3%ADs%2C+Italia','https://www.umbriatourism.it/-/basilica-of-saint-francis-of-assisi',43.074,12.606);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','asis-rocca-maggiore','asis','Asís al atardecer: Rocca Maggiore','Asís','postal',array['naturaleza']::text[],'2h','noche','bajo',false,false,'medio','social',null,'Subid a la fortaleza para ver el valle de Umbría al atardecer, con la basílica abajo; la vuelta se hace por callejuelas.',null,'https://www.italia.it/en/umbria/assisi.html','oficial','https://www.google.com/maps/search/?api=1&query=Rocca+Maggiore%2C+As%C3%ADs%2C+Italia','https://www.travelsignposts.com/Italy/destinations/assisi-live-from-the-rocca-maggiore',43.073,12.62);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','spello','asis','Spello: callejas de flores','Spello','postal',array['cultura']::text[],'medio_dia','tarde','gratis',false,false,'medio','tranquilo',null,'Pueblo de piedra en cuesta con macetas en cada esquina, junto a Asís y con estación de tren.','En primavera, la Infiorata de Corpus Domini llena las calles de alfombras de flores.','https://www.umbriatourism.it/en/-/inflorate-corpus-domini-of-spello','oficial','https://www.google.com/maps/search/?api=1&query=Spello%2C+Italia','https://www.umbriatourism.it/en/-/inflorate-corpus-domini-of-spello',42.989,12.671);
