insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','gubbio','perugia','Gubbio y su teleférico','Gubbio','cultura',array['naturaleza']::text[],'medio_dia','manana','medio',false,false,'medio','mixto',null,'Pueblo medieval de piedra gris y teleférico de cestas abiertas hasta el monte Ingino.','Hay bus desde Perugia; comprobad horarios del día.','https://www.italia.it/it/umbria/perugia/gubbio/funivia-colle-eletto','oficial','https://www.google.com/maps/search/?api=1&query=Funivia+Colle+Eletto%2C+Gubbio%2C+Italia','https://www.italia.it/it/umbria/perugia/gubbio/funivia-colle-eletto',43.351,12.577);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','marmore','perugia','Cascata delle Marmore','Terni','naturaleza',array['agua','aventura']::text[],'medio_dia','manana','bajo',false,false,'medio','mixto',null,'Cascada artificial de 165 m, de las más altas de Europa, con senderos hasta los miradores.','El caudal se abre y cierra por horarios, mirad el calendario oficial; hay tren a Terni y bus local.','https://www.umbriatourism.it/en/w/marmore-falls','oficial','https://www.google.com/maps/search/?api=1&query=Cascata+delle+Marmore%2C+Terni%2C+Italia','https://www.umbriatourism.it/en/w/marmore-falls',42.551,12.714);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('umbria','trasimeno','perugia','Lago Trasimeno e Isola Maggiore','Lago Trasimeno','naturaleza',array['agua','postal']::text[],'dia_completo','cualquiera','bajo',false,false,'bajo','mixto',null,'Barco desde Passignano o Castiglione del Lago hasta la isla, pueblo de pescadores, y tarde de lago.','Mejor de primavera a otoño; en invierno hay menos barcos.','https://www.umbriatourism.it/en/w/a-day-among-the-islands-of-lake-trasimeno','oficial','https://www.google.com/maps/search/?api=1&query=Isola+Maggiore%2C+Lago+Trasimeno%2C+Italia','https://www.umbriatourism.it/en/w/a-day-among-the-islands-of-lake-trasimeno',43.131,12.095);
