insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('emilia-romana-gastronomica','IT','Emilia-Romaña gastronómica','Emilia-Romaña','Pasta, torres y Riviera en tren','{"mar":2,"montana":0,"ciudad":3,"campo":1,"fiesta":2,"calma":1,"cultura":2,"gastronomia":3,"naturaleza":0,"playa":2,"aventura":1,"postal":1}'::jsonb,'medio','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11],"evitar":[8],"nota":"Primavera y otoño para ciudades; la playa y la fiesta de Rímini solo de junio a septiembre. En la llanura hace bochorno en pleno verano y niebla en invierno."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Bolonia, Módena, Parma, Ferrara, Rávena y Rímini se enlazan en tren y las ciudades tienen ZTL y aparcamiento caro. El coche solo compensa para acetaie, caseríos de parmesano y el museo Lamborghini.","aeropuerto_recogida":"BLQ","operadores":[{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Bolonia.BLQ.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Bolonia.BLQ.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Bolonia.BLQ.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Bolonia.BLQ.AVIS.cla.ksp"},{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Bolonia.BLQ.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Bolonia.BLQ.HERTZ.cla.ksp"},{"nombre":"Enterprise","enlace":"https://www.momondo.it/noleggio-auto/Enterprise-Bologna.BLQ.ENTERPRISE.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Enterprise-Bologna.BLQ.ENTERPRISE.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"BLQ","nombre":"Bolonia – Guglielmo Marconi","ciudad":"Bolonia","a_la_base":"Hay lanzadera ferroviaria y bus hasta la estación Bologna Centrale en pocos minutos; comprobad opciones y precio en la web del aeropuerto."},{"iata":"RMI","nombre":"Rímini – Federico Fellini","ciudad":"Rímini","a_la_base":"Aeropuerto pequeño de temporada junto a Rímini; desde él se llega al centro y a la estación en bus o taxi corto."}],"desde_espana":"Bolonia (BLQ) recibe vuelos low cost desde ciudades españolas, sobre todo Barcelona, y alternativa barata es volar a Milán Bérgamo (BGY) y subir en tren (1 h 30 aprox.). Comparad siempre fechas en el buscador: la oferta cambia por temporada.","rutas_directas":[],"desde_italia":"Bolonia Centrale es el gran nudo: alta velocidad con Milán, Florencia, Venecia y Roma (Trenitalia/Italo) y regionales a Módena, Parma, Ferrara, Rávena y Rímini.","novedades":[]}'::jsonb,'{"resumen":"Un grupo se mueve en tren regional desde Bolonia: Módena, Parma, Ferrara, Rávena y Rímini están a distancias de día. Dentro de las ciudades todo es a pie o en bici.","tren":{"nota":"Trenes regionales baratos entre Bolonia, Módena, Parma, Ferrara, Rávena y Rímini; alta velocidad hacia Milán y Florencia. Comprad en Trenitalia o Italo y validad el billete regional antes de subir.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Rutas dentro de Italia desde Bolonia; sirve para ir a otras ciudades de Italia, no para llegar desde España.","enlace":"https://www.flixbus.it/autobus/bologna","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["No pude abrir webs oficiales en esta sesión (límite de herramientas): casi todos los enlaces son mapa, Booking, Airbnb o GetYourGuide en patrón seguro.","Sin rutas aéreas directas verificadas para BLQ: la biblioteca previa solo citaba un comparador genérico, así que no las incluyo.","Fechas de Motor Valley Fest, Notte Rosa y Ravenna Festival sin verificar: son recurrentes, pero comprobad el año.","Rímini y su playa/fiesta solo funcionan de junio a septiembre; en invierno la zona es solo ciudad y comida.","El museo Lamborghini y las acetaie/caseifici se hacen mal sin coche; el resto sí es a pie o en tren."]'::jsonb,'{"zona":"emilia-romana-gastronomica","base":"bologna","ciudad_referencia":"Bolonia","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":25,"max":34,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/bologna/","calidad":"orientativo"},"doble_noche":{"min":59,"max":151,"fuente":"https://www.booking.com/city/it/bologna.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/bologna","calidad":"orientativo"},"comida_barata":{"valor":20,"fuente":"https://www.numbeo.com/cost-of-living/in/Bologna","calidad":"orientativo"},"transporte_billete":{"valor":2.3,"fuente":"https://www.tper.it/sites/default/files/Tariffe%20Area%20Urbana%20Bologna.pdf","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 10 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=22.0, maximo=35.0); son precios ''desde'' sin fechas concretas. doble_noche: min=59 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=151 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Bolonia (rango Numbeo 15-25). transporte_billete: TPER, billete ordinario area urbana de Bolonia 2.30 EUR (tambien con tarjeta contactless). El PDF no lleva fecha."}'::jsonb);
