insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('emilia-romana-gastronomica','torre-asinelli','bologna','Las Dos Torres desde Piazza di Porta Ravegnana','Bolonia','cultura',array['postal']::text[],'1h','manana','gratis',false,false,'bajo','social',null,'Ved desde la plaza la Asinelli y la Garisenda, las dos torres medievales más conocidas de Bolonia. La subida a la Asinelli está cerrada por obras.','La subida está cerrada hasta nuevo aviso. Para una vista desde lo alto, buscad la Torre del Reloj en Piazza Maggiore.','https://www.bolognawelcome.com/es/lugares/torres-edificios-historicos/las-dos-torres-garisenda-y-asinelli','oficial','https://www.google.com/maps/search/?api=1&query=Torre+degli+Asinelli+y+Due+Torri%2C+Bolonia%2C+Italia','https://www.google.com/maps/search/?api=1&query=Torre+degli+Asinelli+y+Due+Torri%2C+Bolonia%2C+Italia',44.494,11.347);
