insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('piamonte','IT','Piamonte (Turín y Langhe)','Piamonte','Turín señorial y colinas de vino','{"mar":0,"montana":2,"ciudad":3,"campo":2,"fiesta":2,"calma":1,"cultura":3,"gastronomia":3,"naturaleza":1,"playa":0,"aventura":1,"postal":2}'::jsonb,'medio','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11,12],"evitar":[1,2,8],"nota":"Primavera y otoño son lo mejor (en otoño, vendimia y trufa). En invierno hay niebla y frío en el valle del Po; en agosto muchos locales cierran."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Turín funciona sin coche (metro, tranvía, bus) y tiene ZTL en el centro. Para catas en las Langhe el coche o un tour organizado es casi obligatorio, y el conductor no puede beber.","aeropuerto_recogida":"TRN","operadores":[{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Turin.TRN.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Turin.TRN.AVIS.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Turin.TRN.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Turin.TRN.EUROPCAR.cla.ksp"},{"nombre":"Hertz","enlace":"https://www.kayak.es/Hertz-Coches-de-alquiler-Turin.TRN.AHERTZ.cla.ksp","fuente":"https://www.kayak.es/Hertz-Coches-de-alquiler-Turin.TRN.AHERTZ.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"TRN","nombre":"Turín – Caselle","ciudad":"Turín","a_la_base":"Está a las afueras de Turín; hay bus y tren hasta la ciudad, comprobad el medio en la web del aeropuerto."},{"iata":"MXP","nombre":"Milán – Malpensa","ciudad":"Milán","a_la_base":"Bus o tren a Milán y tren de alta velocidad Milán–Turín, de aproximadamente una hora."}],"desde_espana":"Barcelona–Turín es de las rutas low cost más usadas, con vuelo directo de poco más de una hora; la frecuencia varía por temporada. Desde otras ciudades suele salir mejor volar a Milán y seguir en tren.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"TRN","aerolinea":"Ryanair / Vueling","nota":"La oferta cambia por temporada; comparad fechas","fuente":"https://www.momondo.es/vuelos/barcelona/turin"}],"desde_italia":"Tren de alta velocidad Milán–Turín en torno a una hora; Génova–Turín también por tren regional. Desde Bolonia o Roma, normalmente con cambio en Milán."}'::jsonb,'{"resumen":"Turín se recorre a pie, en metro y en tranvía. Alba, Venaria y la Sacra se alcanzan en tren o bus; para viñedos de las Langhe, coche o tour.","tren":{"nota":"Tren regional a Alba (desde Turín) y a Sant''Ambrogio, al pie de la Sacra; Italo y Trenitalia a Milán.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Cubre Turín y otras ciudades dentro de Italia; para pueblos de las Langhe hay bus local con pocas frecuencias.","enlace":"https://www.flixbus.it/autobus/torino","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia (página general); útil para moverse entre colinas.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["No se verificaron webs oficiales de Superga, Valentino, Mauto, Balôn, Murazzi ni Lago d''Orta: se enlazan por mapa o portada de turismo.","La subida a la Sacra desde la estación de Sant''Ambrogio y el tren a Orta se describen de forma general; comprobad en Trenitalia.","Los eventos son recurrentes sin fecha de 2027 publicada; Terra Madre es bienal.","Bicerin y los cafés históricos se citan sin nombrar locales (sin web oficial verificada).","Se descartó nombrar bodegas o tours concretos de las Langhe."]'::jsonb,'{"zona":"piamonte","base":"torino","ciudad_referencia":"Turín","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":23,"max":30,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/turin/","calidad":"orientativo"},"doble_noche":{"min":59,"max":158,"fuente":"https://www.booking.com/city/it/torino.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/turin","calidad":"orientativo"},"comida_barata":{"valor":18,"fuente":"https://www.numbeo.com/cost-of-living/in/Turin","calidad":"orientativo"},"transporte_billete":{"valor":1.7,"fuente":"https://gtt.to.it/cms/en/howtouse","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 5 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=20.0, maximo=33.66); son precios ''desde'' sin fechas concretas. doble_noche: min=59 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=158 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Turin (rango Numbeo 15-25). transporte_billete: GTT Turin, billete ordinario \"City 100\" 100 min 1.70 EUR segun la pagina oficial en ingles; la pagina no muestra fecha y podria estar desactualizada (otras fuentes mencionan aumentos)."}'::jsonb);
