insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','porta-palazzo','torino','Mercado de Porta Palazzo','Turín','compras',array['gastronomia']::text[],'2h','manana','gratis',false,false,'bajo','social',null,'Uno de los mayores mercados al aire libre de Europa: fruta, queso, embutidos y ropa a buen precio.','Se llena por la mañana y está cerrado los domingos; comprobad días en la web del Ayuntamiento.','https://www.google.com/maps/search/?api=1&query=Mercato+di+Porta+Palazzo%2C+Torino%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Porta+Palazzo%2C+Torino%2C+Italia','https://www.turismotorino.org/',45.078,7.682);
