insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','sacra-san-michele','torino','Sacra di San Michele','Sant''Ambrogio di Torino','cultura',array['aventura','postal']::text[],'dia_completo','manana','bajo',false,false,'alto','mixto',null,'Abadía medieval sobre el monte Pirchiriano, símbolo del Piamonte; con subida a pie desde el valle.','En tren hasta Sant''Ambrogio y subida larga a pie, o coche hasta arriba; llevad calzado de monte.','https://www.sacradisanmichele.com/','oficial','https://www.google.com/maps/search/?api=1&query=Sacra+di+San+Michele%2C+Italia','https://www.sacradisanmichele.com/',45.098,7.343);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','langhe-cata','alba','Cata de vino en las Langhe','Barolo','gastronomia',array['naturaleza']::text[],'dia_completo','tarde','alto',true,true,'bajo','social',null,'Bodegas y colinas de viñedo Patrimonio UNESCO con Barolo y Barbaresco.','Sin coche, buscad un tour desde Turín o Alba; si vais en coche, el conductor no bebe.','https://www.getyourguide.es/s/?q=Langhe+Barolo+cata','reserva','https://www.google.com/maps/search/?api=1&query=Barolo%2C+Langhe%2C+Italia','https://www.getyourguide.es/s/?q=Langhe+Barolo+cata',44.611,7.941);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','alba-centro','alba','Alba: centro histórico','Alba','cultura',array['gastronomia']::text[],'medio_dia','cualquiera','gratis',false,false,'bajo','tranquilo',null,'Torres medievales, calles de ladrillo y tiendas de vino y chocolate; a un tren regional de Turín.',null,'https://www.google.com/maps/search/?api=1&query=Alba%2C+Cuneo%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Alba%2C+Cuneo%2C+Italia','https://www.visitpiemonte-dmo.org/',44.7,8.035);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','fiera-tartufo','alba','Feria de la trufa blanca de Alba','Alba','gastronomia',array['compras']::text[],'medio_dia','cualquiera','bajo',false,false,'bajo','social',array[10,11,12]::int[],'Mercado y catas de trufa blanca en otoño; entrar suele costar poco y probar, bastante más.','En 2026 la feria fue de octubre a principios de diciembre; comprobad fechas anuales.','https://www.fieradeltartufo.org/','oficial','https://www.google.com/maps/search/?api=1&query=Fiera+del+Tartufo%2C+Alba%2C+Italia','https://www.fieradeltartufo.org/',44.7,8.035);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','superga','torino','Basílica de Superga','Turín','postal',array['aventura']::text[],'medio_dia','tarde','bajo',false,false,'bajo','tranquilo',null,'Mirador sobre Turín y los Alpes, con subida en tranvía de cremallera histórico.',null,'https://www.google.com/maps/search/?api=1&query=Basilica+di+Superga%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Basilica+di+Superga%2C+Italia','https://www.turismotorino.org/',45.08,7.766);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','valentino','torino','Parco del Valentino y paseo junto al Po','Turín','naturaleza',array['cultura']::text[],'2h','tarde','gratis',false,false,'bajo','tranquilo',null,'Recorred la ribera del Po dentro del parque. Podéis acercaros al Borgo Medievale por fuera mientras duren las obras.','Pasead por el parque junto al Po. El Borgo Medievale y la fortaleza están cerrados por restauración. Consultad la ficha de Turismo de Turín antes de contar con la visita interior.','https://www.google.com/maps/search/?api=1&query=Parco+del+Valentino%2C+Torino%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Parco+del+Valentino%2C+Torino%2C+Italia','https://www.turismotorino.org/',45.054,7.688);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','cappuccini','torino','Monte dei Cappuccini al atardecer','Turín','postal',null,'2h','noche','gratis',false,false,'bajo','tranquilo',null,'Mirador sobre Turín y los Alpes, ideal para la puesta de sol.',null,'https://www.google.com/maps/search/?api=1&query=Monte+dei+Cappuccini%2C+Torino%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Monte+dei+Cappuccini%2C+Torino%2C+Italia','https://www.turismotorino.org/',45.062,7.699);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('piamonte','mauto','torino','Museo Nazionale dell''Automobile','Turín','cultura',null,'medio_dia','cualquiera','medio',false,false,'bajo','mixto',null,'Historia del coche y del diseño italiano en la capital del motor.',null,'https://www.google.com/maps/search/?api=1&query=Museo+Nazionale+dell%27Automobile%2C+Torino%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Museo+Nazionale+dell%27Automobile%2C+Italia','https://www.turismotorino.org/',45.032,7.675);
