insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('basilicata-matera','IT','Basilicata y Matera','Matera','Ciudad-cueva y pueblos de piedra','{"mar":1,"montana":2,"ciudad":2,"campo":2,"fiesta":0,"calma":3,"cultura":3,"gastronomia":2,"naturaleza":2,"playa":1,"aventura":2,"postal":3}'::jsonb,'bajo','{"ideales":[4,5,6,9,10],"aceptables":[3,11],"evitar":[7,8],"nota":"En verano la piedra de los Sassi acumula mucho calor; primavera y otoño son mucho mejores para caminar. En invierno hace fresco y hay menos ambiente."}'::jsonb,'extremo',false,'{"necesidad":"util","nota":"Matera se hace a pie, pero Craco, Castelmezzano, Pietrapertosa y Maratea exigen coche. Para ahorrar, alquilad un coche solo los días de excursión (desde Bari).","aeropuerto_recogida":"BRI","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.it/noleggio-auto/Hertz-Bari.BRI.HERTZ.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Hertz-Bari.BRI.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.it/noleggio-auto/Europcar-Bari.BRI.EUROPCAR.cla.ksp","fuente":"https://www.momondo.it/noleggio-auto/Europcar-Bari.BRI.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"BRI","nombre":"Bari – Karol Wojtyła","ciudad":"Bari","a_la_base":"Matera no tiene aeropuerto: son unos 65 km desde Bari; hay tren regional (Ferrovie Appulo Lucane) o coche, alrededor de una hora."}],"desde_espana":"Ryanair conecta Madrid con Bari; desde otras ciudades españolas hay pocas rutas directas, así que contad con escala o con llegar vía Roma o Nápoles. Mirad también vuelos a Brindisi y Nápoles como alternativas.","rutas_directas":[{"origen":"Madrid","origen_iata":"MAD","destino_iata":"BRI","aerolinea":"Ryanair","nota":"Listada en ryanair.com; comprobad si es estacional.","fuente":"https://www.ryanair.com/"}],"desde_italia":"FlixBus llega a Bari y desde allí tren regional o bus a Matera; también hay buses desde Roma o Nápoles. Cuenta con transbordos y mucho tiempo.","novedades":[]}'::jsonb,'{"resumen":"Matera se recorre a pie (con cuestas y escaleras); para Craco, Dolomitas Lucanas o Maratea hace falta coche. Entre Bari y Matera, tren o bus regional.","tren":{"nota":"Conexión regional Bari–Matera con Ferrovie Appulo Lucane; no hay red útil para el resto de Basilicata.","enlace":"https://www.rome2rio.com/es/map/Bari/Matera"},"bus":{"operador":"FlixBus","nota":"Larga distancia dentro de Italia; el slug de Bari está verificado en flixbus.it. No cubre la llegada desde España.","enlace":"https://www.flixbus.it/autobus/bari","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de camper en Italia; enlazamos la página general del país, sin oficina verificada en esta zona.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Búsqueda web y fetch agotados: casi todos los enlaces de actividades son el patrón seguro de mapa; no hay web oficial verificada de Casa Grotta, MUSMA, Craco ni Volo dell''Angelo.","Los tres eventos enlazan a la portada de basilicataturistica.it sin abrir esa página en esta sesión; fechas no confirmadas con fuente oficial.","Ruta Madrid–Bari de Ryanair: fuente es la portada de ryanair.com, no una página de ruta.","Craco y Volo dell''Angelo: condiciones de acceso y reserva no verificadas."]'::jsonb,'{"zona":"basilicata-matera","base":"matera","ciudad_referencia":"Matera","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":20,"max":25,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/matera/","calidad":"orientativo"},"doble_noche":null,"comida_barata":{"valor":13.5,"fuente":"https://www.numbeo.com/cost-of-living/in/Matera-Italy","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche: rango min-max de 3 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=20.0, maximo=25.0); son precios ''desde'' sin fechas concretas. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/matera.html?selected_currency=EUR: precio ''From'' del titulo = 76 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Matera (rango Numbeo 10-30). transporte_billete null: No se encontro tarifa urbana oficial de Matera. La Carta della Mobilita 2023 de Miccolis menciona una corsa semplice de 0.80 EUR, pero no se puede confirmar que sea el servicio urbano de Matera ni que siga vigente, asi que no se usa."}'::jsonb);
