insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('calabria','IT','Calabria','Calabria','Calas de postal y sur sin masificar','{"mar":3,"montana":2,"ciudad":1,"campo":1,"fiesta":1,"calma":3,"cultura":1,"gastronomia":2,"naturaleza":2,"playa":3,"aventura":1,"postal":3}'::jsonb,'bajo','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8],"nota":"Junio y septiembre dan mar cálido sin la masificación de agosto; en julio-agosto hace mucho calor, aunque la Sila es un respiro."}'::jsonb,'alto',false,'{"necesidad":"imprescindible","nota":"Fuera de la línea de tren de la costa (Pizzo, Tropea, Scilla, Reggio) los pueblos, calas y parques de montaña tienen poco transporte público. Para Capo Vaticano, Sila y Le Castella el coche es casi obligatorio.","aeropuerto_recogida":"SUF","operadores":[{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Lamezia-Terme.SUF.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Lamezia-Terme.SUF.EUROPCAR.cla.ksp"},{"nombre":"Enterprise","enlace":"https://www.momondo.es/alquiler-de-coches/Enterprise-Lamezia-Terme.SUF.ENTERPRISE.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Enterprise-Lamezia-Terme.SUF.ENTERPRISE.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"SUF","nombre":"Lamezia Terme","ciudad":"Lamezia Terme","a_la_base":"Lamezia Airlink de Trenitalia conecta el aeropuerto con la estación y de ahí tren regional a Pizzo y Tropea."},{"iata":"REG","nombre":"Reggio Calabria – Tito Minniti","ciudad":"Reggio Calabria","a_la_base":"Cerca de la ciudad; sirve para Reggio y Scilla; comprobad transporte público."},{"iata":"CRV","nombre":"Crotone – Sant''Anna","ciudad":"Crotone","a_la_base":"Útil para Le Castella y el Área Marina Protegida; mejor con coche."}],"desde_espana":"Ryanair ha unido Madrid con Lamezia en verano (ruta de 2025). Desde el resto de España suele hacer falta escala o volar a Sicilia/Nápoles y seguir en tren o ferry.","rutas_directas":[{"origen":"Madrid","origen_iata":"MAD","destino_iata":"SUF","aerolinea":"Ryanair","nota":"estacional (verano 2025); comprobad si sigue","fuente":"https://italiabsolutely.com/news/transportation/calabria-takes-centre-stage-in-ryanair-s-international-network-202504081736"}],"desde_italia":"Desde Roma o Nápoles hay trenes (Intercity) hasta Lamezia Terme y Reggio Calabria por la costa tirrena; son varias horas. Desde Sicilia, el ferry de Mesina a Villa San Giovanni.","novedades":[{"nota":"Ryanair añadió cinco rutas internacionales a Calabria en verano 2025, entre ellas Madrid-Lamezia.","fuente":"https://italiabsolutely.com/news/transportation/calabria-takes-centre-stage-in-ryanair-s-international-network-202504081736"}]}'::jsonb,'{"resumen":"La línea de tren de la costa une Pizzo, Tropea, Scilla y Reggio, pero para calas y la Sila hace falta coche o excursión organizada.","tren":{"nota":"Tren regional de Trenitalia por la costa tirrena; Lamezia Airlink conecta el aeropuerto con la estación.","enlace":"https://www.trenitalia.com/it/regionale/collegamenti-regionale/lamezia-airlink.html"},"bus":null,"ferry":[{"operador":"Caronte & Tourist","ruta":"Villa San Giovanni - Mesina","nota":"Más de 120 travesías diarias, 24 horas; para combinar Calabria y Sicilia.","enlace":"https://booking.carontetourist.it/en","fuente":"https://www.carontetourist.it/en/caronte-tourist"}],"camper":null}'::jsonb,'["Calabria es difícil sin coche fuera de la línea de tren de la costa.","No verifiqué horarios, precios ni si el Treno della Sila opera en cada fecha.","Ryanair Madrid-Lamezia es de verano 2025; hay que confirmar si sigue.","Reggio (noche) y Cirò solo tienen fuente genérica; sin locales concretos.","Faltan transporte público de la Sila y Pollino, y no incluyo Pollino ni Aspromonte."]'::jsonb,'{"zona":"calabria","base":"tropea","ciudad_referencia":"Tropea","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":16,"max":16,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/tropea/","calidad":"orientativo"},"doble_noche":null,"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Reggio-Di-Calabria?displayCurrency=EUR","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche: rango min-max de 1 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=16.0, maximo=16.0); son precios ''desde'' sin fechas concretas. Solo 1 hostel con precio de dorm; min=max. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/tropea.html?selected_currency=EUR: precio ''From'' del titulo = 73 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Reggio Calabria (ciudad con datos mas cercana; Tropea no existe en Numbeo, ~100 km) (rango Numbeo 10-15). transporte_billete null: Tropea es un pueblo sin red de transporte urbano relevante; no se abrio fuente con tarifa."}'::jsonb);
