insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('lombardia-milan','IT','Milán y Lombardía','Milán','Ciudad grande, Navigli y lagos','{"mar":0,"montana":0,"ciudad":3,"campo":0,"fiesta":2,"calma":0,"cultura":2,"gastronomia":2,"naturaleza":1,"playa":0,"aventura":0,"postal":2}'::jsonb,'alto','{"ideales":[4,5,6,9,10],"aceptables":[3,7,11,12],"evitar":[8],"nota":"En agosto media ciudad cierra por vacaciones y hay bochorno; en invierno hay niebla pero Navidad es animada."}'::jsonb,'alto',false,'{"necesidad":"innecesario","nota":"Metro, tranvía y tren cubren Milán y las excursiones; el centro tiene ZTL y aparcar es caro. Solo tiene sentido si queréis explorar los lagos por vuestra cuenta.","aeropuerto_recogida":"MXP","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Milan.MXP.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Milan.MXP.HERTZ.cla.ksp"},{"nombre":"Alamo","enlace":"https://www.momondo.es/alquiler-de-coches/Alamo-Milan.MXP.ALAMO.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Alamo-Milan.MXP.ALAMO.cla.ksp"},{"nombre":"Enterprise","enlace":"https://www.momondo.es/alquiler-de-coches/Enterprise-Milan.MXP.ENTERPRISE.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Enterprise-Milan.MXP.ENTERPRISE.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"BGY","nombre":"Milán Bérgamo – Orio al Serio","ciudad":"Bérgamo","a_la_base":"Hay bus directo a la estación de Milano Centrale y a Bérgamo; unos 50-60 minutos a Milán según tráfico. Comprobad operador y precio en la web del aeropuerto."},{"iata":"MXP","nombre":"Milán Malpensa","ciudad":"Milán","a_la_base":"Tren Malpensa Express a Milán (Centrale y Cadorna), de unos 50 minutos; también hay buses."},{"iata":"LIN","nombre":"Milán Linate","ciudad":"Milán","a_la_base":"Aeropuerto urbano, conectado con el centro en metro (unos 15-20 minutos); menos low cost."}],"desde_espana":"Barcelona-Milán Bérgamo es la ruta low cost más consolidada, con Ryanair. Comparad también Malpensa (MXP) y Linate (LIN), que reciben más aerolíneas.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"BGY","aerolinea":"Ryanair","nota":"ruta consolidada; comprobad días y temporada al reservar","fuente":"https://www.momondo.es/vuelos/barcelona/aeropuerto-de-bergamo-orio-al-serio-bgy"}],"desde_italia":"Milano Centrale tiene alta velocidad directa con Turín, Venecia, Bolonia, Florencia y Roma (Trenitalia e Italo).","novedades":[]}'::jsonb,'{"resumen":"En Milán se va en metro, tranvía y a pie; para Bérgamo, Como, Pavía o Monza basta tren regional desde Centrale, Garibaldi o Cadorna.","tren":{"nota":"Trenes regionales baratos a Bérgamo, Como, Pavía y Monza; alta velocidad a otras ciudades. Comprad en Trenitalia o Italo y validad el billete regional.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Rutas dentro de Italia desde Milán; no sirve para llegar desde España.","enlace":"https://www.flixbus.it/autobus/milano","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["No pude abrir webs oficiales en esta sesión (límite de herramientas): casi todos los enlaces son mapa, Booking, Airbnb o GetYourGuide en patrón seguro.","Solo una ruta aérea verificada (BCN-BGY, Ryanair); faltan MXP/LIN con fuente.","Fechas de Sant''Ambrogio, Fashion Week y Carnevale Ambrosiano sin fuente oficial verificada, y fecha del mercadillo de Navigli aproximada.","Tiempos de aeropuerto a Milán aproximados: comprobad en la web del aeropuerto.","Cenacolo y San Siro: entradas con enlace de GetYourGuide, no web oficial."]'::jsonb,'{"zona":"lombardia-milan","base":"milan-centro","ciudad_referencia":"Milán","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":18,"max":23,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/milan/","calidad":"orientativo"},"doble_noche":{"min":52,"max":130,"fuente":"https://www.booking.com/city/it/milan.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/milan","calidad":"orientativo"},"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Milan","calidad":"orientativo"},"transporte_billete":{"valor":2.2,"fuente":"https://atm.it/it/ViaggiaConNoi/Documents/TARIFFE%20ATM_ottobre2024.pdf","calidad":"verificado"}},"notas":"hostel_noche: rango P25-P75 de 29 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=10.49, maximo=74.97); son precios ''desde'' sin fechas concretas. doble_noche: min=52 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=130 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Milan (rango Numbeo 10-18). transporte_billete: ATM, billete ordinario urbano Mi1-Mi3, 90 min, 2.20 EUR. OJO: documento oficial de tarifas fechado octubre 2024; no se ha podido confirmar si hay cambio posterior."}'::jsonb);
