insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('friuli-venezia-giulia','IT','Friuli-Venecia Julia (Trieste)','Trieste','Cafés, Carso y mar sin turistas','{"mar":2,"montana":1,"ciudad":2,"campo":2,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":2,"playa":1,"aventura":1,"postal":2}'::jsonb,'medio','{"ideales":[5,6,9,10],"aceptables":[4,7,8,11],"evitar":[1,2],"nota":"La bora, viento frío del noreste, puede ser fortísima en invierno; en octubre, Barcolana llena la ciudad."}'::jsonb,'suave',false,'{"necesidad":"util","nota":"Trieste, Udine y Cividale se visitan en tren y a pie. Para Aquileia, el Collio, la Grotta Gigante y las osmize del Carso el coche es mucho más cómodo.","aeropuerto_recogida":"TRS","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Trieste.TRS.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Trieste.TRS.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Trieste.TRS.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Trieste.TRS.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"TRS","nombre":"Trieste – Friuli Venezia Giulia (Ronchi dei Legionari)","ciudad":"Trieste","a_la_base":"Hay conexión en bus y tren con Trieste; comprobad horarios y precios en la web del aeropuerto antes de volar."},{"iata":"VCE","nombre":"Venecia – Marco Polo","ciudad":"Venecia","a_la_base":"Alternativa con más vuelos: tren de Venecia a Trieste (comprobad en Trenitalia)."}],"desde_espana":"Ryanair conecta Barcelona y Valencia con Trieste (TRS) según temporada. Si no hay vuelo directo, Venecia (VCE) o Treviso (TSF) son alternativas con más rutas, y desde allí se llega en tren o bus.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"TRS","aerolinea":"Ryanair","nota":"confirmada para verano 2026 por el aeropuerto; comprobad otras temporadas","fuente":"https://triesteairport.it/media/documents/CS__RYANAIR_LANCIA_LOPERATIVO_PER_LESTATE_2026_A_TRIESTE_20260318.pdf"},{"origen":"Valencia","origen_iata":"VLC","destino_iata":"TRS","aerolinea":"Ryanair","nota":"confirmada para verano 2026 por el aeropuerto; comprobad otras temporadas","fuente":"https://triesteairport.it/media/documents/CS__RYANAIR_LANCIA_LOPERATIVO_PER_LESTATE_2026_A_TRIESTE_20260318.pdf"}],"desde_italia":"Hay trenes de Trenitalia entre Venecia, Udine y Trieste (alrededor de dos horas desde Venecia); FlixBus cubre rutas por carretera. Para quien está en Bolonia o Milán, el tren con transbordo en Venecia o Mestre es lo habitual.","novedades":[{"nota":"Ryanair confirmó en su comunicado oficial (18 de marzo de 2026) que mantiene y refuerza Trieste–Barcelona y Trieste–Valencia en verano 2026, entre 21 rutas desde TRS; el comunicado no precisa si es BCN o Girona.","fuente":"https://triesteairport.it/media/documents/CS__RYANAIR_LANCIA_LOPERATIVO_PER_LESTATE_2026_A_TRIESTE_20260318.pdf"}]}'::jsonb,'{"resumen":"Trieste se recorre a pie y con bus urbano; Udine, Cividale y Gorizia se alcanzan en tren regional. Aquileia, el Collio y el Carso piden coche o bus lento.","tren":{"nota":"Trenitalia cubre Trieste–Udine y Trieste–Gorizia; Cividale se hace desde Udine en tren regional.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Solo rutas dentro de Italia (por ejemplo Trieste–Venecia–Milán); no hay ruta directa verificada desde España.","enlace":"https://www.flixbus.it/tratte-autobus","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["Barcolana: la web oficial dice segundo domingo de octubre pero no publica aún fecha de 2027 verificada.","Friuli DOC: la fuente es un listado derivado del calendario de turismo regional, no la web propia del festival.","Los mercadillos de Navidad se basan en una fuente periodística, sin fechas oficiales verificadas.","Aperitivos y bares en Trieste/Udine van con enlace de mapa; sin locales concretos verificados.","Grotta Gigante, osmize, Aquileia y Collio se han marcado como actividades con coche por prudencia; algunas pueden hacerse con bus lento, sin horarios verificados.","No hay ferry verificado en la zona; no se incluye."]'::jsonb,'{"zona":"friuli-venezia-giulia","base":"trieste","ciudad_referencia":"Trieste","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":17,"max":21.85,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/trieste/","calidad":"orientativo"},"doble_noche":{"min":66,"max":88,"fuente":"https://www.booking.com/city/it/trieste.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/trieste","calidad":"orientativo"},"comida_barata":{"valor":20,"fuente":"https://www.numbeo.com/cost-of-living/in/Trieste?displayCurrency=EUR","calidad":"orientativo"},"transporte_billete":{"valor":1.5,"fuente":"https://www.triestetrasporti.it/sites/default/files/attachments/tpl_tariffe_urbane_Trieste_2026.pdf","calidad":"verificado"}},"notas":"hostel_noche: rango min-max de 3 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=17.0, maximo=21.85); son precios ''desde'' sin fechas concretas. doble_noche: min=66 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=88 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Trieste (rango Numbeo 15-30). transporte_billete: Trieste Trasporti, biglietto orario 60 min (cod. U01) 1.50 EUR. El PDF no muestra el ano de forma explicita (el fichero se llama 2026; otro PDF 2025 tambien indica 1.50)."}'::jsonb);
