insert into public.lib_eventos(destino_id,nombre,donde,cuando,meses,proxima_fecha,enlace,descripcion) values ('friuli-venezia-giulia','Mercadillos de Navidad en Friuli-Venecia Julia','Trieste y otras localidades','cada año, desde finales de noviembre hasta principios de enero',array[11,12,1]::int[],null,'https://siviaggia.it/idee-di-viaggio/natale-in-friuli-venezia-giulia/497432/','Mercados navideños en Trieste y otras localidades de la región.');
insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('abruzos','IT','Abruzos','Abruzos','Montaña, trabocchi y mar sin multitudes','{"mar":2,"montana":3,"ciudad":1,"campo":2,"fiesta":1,"calma":3,"cultura":2,"gastronomia":3,"naturaleza":3,"playa":2,"aventura":2,"postal":2}'::jsonb,'bajo','{"ideales":[5,6,9],"aceptables":[1,2,3,4,7,10],"evitar":[8],"nota":"Mayo, junio y septiembre combinan playa y montaña; en agosto la costa se llena. De enero a marzo hay esquí en Roccaraso y Campo Imperatore."}'::jsonb,'alto',true,'{"necesidad":"imprescindible","nota":"Pescara, la costa y Sulmona van en tren, pero Gran Sasso, Rocca Calascio, Scanno y las estaciones de esquí funcionan mucho mejor con coche. En L''Aquila y Sulmona hay centros con tráfico limitado: aparcad fuera.","aeropuerto_recogida":"PSR","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Pescara.PSR.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Pescara.PSR.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Pescara.PSR.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Pescara.PSR.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Pescara.PSR.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Pescara.PSR.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"PSR","nombre":"Pescara – Abruzzo","ciudad":"Pescara","a_la_base":"Pescara Air Link de Trenitalia: tren y bus entre la estación y el aeropuerto, unos 25 min según Trenitalia."},{"iata":"FCO","nombre":"Roma – Fiumicino","ciudad":"Roma","a_la_base":"Se sigue en FlixBus o tren hasta Pescara; hay trasbordo y el trayecto es largo. Comprobad opciones el día de la reserva."}],"desde_espana":"Ryanair ha volado Valencia–Pescara desde el invierno de 2025. Desde otras ciudades, lo normal es volar a Roma y seguir en bus o tren, o alquilar coche en Pescara.","rutas_directas":[{"origen":"Valencia","origen_iata":"VLC","destino_iata":"PSR","aerolinea":"Ryanair","nota":"ruta anunciada como nueva en invierno 2025; comprobad días y vigencia al reservar","fuente":"https://corporate.ryanair.com/novita/ryanair-annuncia-una-crescita-record-per-labruzzo/"}],"desde_italia":"Pescara está en la línea adriática de Trenitalia y FlixBus la une con Roma, Bolonia, Milán, Florencia, Nápoles y Bari. Sulmona y L''Aquila se llegan en tren regional desde Pescara.","novedades":[{"nota":"Un registro de vuelos independiente mostraba el Pescara–Valencia de Ryanair operando en noviembre de 2026, unas 3 veces por semana. Es una referencia, no un horario fijo.","fuente":"https://aviability.com/en/flight/fr6415-ryanair/psr-vlc"}]}'::jsonb,'{"resumen":"Sin coche: tren por la costa (Pescara, Ortona, San Vito) y Pescara–Sulmona, más bus a Roccaraso. Con coche: Gran Sasso, Scanno y Calascio en un día cada uno.","tren":{"nota":"Trenitalia cubre la costa adriática y la línea Pescara–Sulmona. RFI ha publicado avisos de obras en Pescara–Sulmona en 2026: comprobadlo antes de ir.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Une Pescara con Roma, Bolonia, Milán, Nápoles y más ciudades italianas. Para pueblos de montaña hay bus regional con pocas salidas.","enlace":"https://www.flixbus.it/autobus/pescara","fuente":"https://www.flixbus.it/autobus/pescara"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia; enlace a la página general.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Sin coche se pierden Gran Sasso, Rocca Calascio, Scanno y Punta Aderci: son lo mejor de la región.","No pude verificar si la funivia de Campo Imperatore funciona esta temporada; estuvo cerrada por obras en 2025.","No pude verificar horarios de buses regionales a Scanno, Roccaraso ni el servicio a Campo Imperatore.","No pude confirmar días de circulación de la Transiberiana para 2027: solo vi fechas de 2026.","Las fechas de eventos de 2027 no estaban publicadas en las fuentes oficiales; proxima_fecha queda en null.","Solo una ruta directa desde España (Valencia–Pescara) y con pocas frecuencias: comprobadla antes de reservar.","Enlaces de L''Aquila nocturno, playa de Pescara y mercados son mapa o fuente general: no hay web oficial verificada.","Coordenadas de geo aproximadas a 3 decimales; sin web oficial de horarios para la Ermita de Sant''Onofrio."]'::jsonb,'{"zona":"abruzos","base":"pescara","ciudad_referencia":"Pescara","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":null,"comida_barata":{"valor":20,"fuente":"https://www.numbeo.com/cost-of-living/in/Pescara","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche null: Hostelworld muestra 0 hostels en Pescara (\"no Hostels available in Pescara right now\"). doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/pescara.html?selected_currency=EUR: precio ''From'' del titulo = 70 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Pescara (rango Numbeo 15-25). transporte_billete null: No se encontro tarifa urbana de TUA Pescara en ninguna pagina abierta (las paginas de TUA abiertas no la mostraban)."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('abruzos','pescara','Pescara','Ciudad grande con playa, ambiente de estudiantes, aeropuerto y trenes a la costa, Sulmona y Roma.','fiesta',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('abruzos','san-vito-chietino','San Vito Chietino','En plena Costa dei Trabocchi, con estación de tren, la ciclovía del mar y calas tranquilas.','calma',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('abruzos','sulmona','Sulmona','Pueblo de piedra a los pies de la Majella: confetti, ermitas y salida hacia Scanno y Roccaraso.','calma',true);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('abruzos','laquila','L''Aquila','Base para el Gran Sasso, Campo Imperatore y Rocca Calascio, con ambiente universitario.','mixto',false);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','pescara-lungomare','pescara','Lungomare de Pescara y Ponte Flaiano','Pescara','postal',array['cultura']::text[],'2h','tarde','gratis',false,false,'bajo','mixto',null,'Paseo por el frente marítimo con la fuente La Nave de Cascella y el puente Flaiano sobre el río, en una ciudad llana que se hace a pie o en bici.',null,'https://www.italia.it/it/abruzzo/pescara','oficial','https://www.google.com/maps/search/?api=1&query=Lungomare+Matteotti%2C+Pescara%2C+Italia','https://www.italia.it/it/abruzzo/pescara',42.468,14.226);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','pescara-playa','pescara','Playa de Pescara','Pescara','playa',null,'medio_dia','cualquiera','bajo',false,false,'bajo','social',array[6,7,8,9]::int[],'Arenal largo y dorado a un paseo del centro, con establecimientos de pago y tramos libres; mucho ambiente en verano.','Fuera de verano sirve como paseo largo junto al mar.','https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Pescara%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Pescara%2C+Italia','https://www.spiagge.it/magazine/spiagge-a-pescara/',42.463,14.233);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','pescara-dannunzio','pescara','Casa natal de Gabriele d''Annunzio','Pescara','cultura',null,'2h','manana','bajo',false,false,'bajo','tranquilo',null,'Museo en la casa donde nació el poeta, en el corso Manthonè, en el casco antiguo de Pescara.','Comprobad horarios en la web antes de ir.','https://www.italia.it/it/abruzzo/pescara/musei/museo-casa-natale-di-gabriele-dannunzio','oficial','https://www.google.com/maps/search/?api=1&query=Museo+Casa+Natale+Gabriele+d%27Annunzio%2C+Pescara%2C+Italia','https://www.italia.it/it/abruzzo/pescara/musei/museo-casa-natale-di-gabriele-dannunzio',42.465,14.215);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','pescara-noche','pescara','Corso Umberto I y centro de Pescara','Pescara','fiesta',array['gastronomia']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Calle peatonal con cafés y restaurantes y ambiente joven por las noches; Pescara es la ciudad más animada de la región.',null,'https://www.italia.it/it/abruzzo/pescara','oficial','https://www.google.com/maps/search/?api=1&query=Corso+Umberto+I%2C+Pescara%2C+Italia','https://www.italia.it/it/abruzzo/pescara',42.462,14.211);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','arrosticini-noche','pescara','Cena de arrosticini','Pescara','gastronomia',array['fiesta']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Pinchos de oveja a la brasa que se comen con la mano y por docenas; el plan de grupo clásico de Abruzos.','Pedid por tandas y con pan y vino de la casa: lo normal es ir sumando.','https://www.uniquevisitor.it/abruzzo/prodotti-tipici/arrosticini-abruzzesi.php','oficial','https://www.google.com/maps/search/?api=1&query=arrosticini%2C+Pescara%2C+Italia','https://www.uniquevisitor.it/abruzzo/prodotti-tipici/arrosticini-abruzzesi.php',42.464,14.213);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','trabocchi-costa','san-vito-chietino','Costa dei Trabocchi en tren y a pie','Costa dei Trabocchi','cultura',array['postal','gastronomia']::text[],'dia_completo','cualquiera','medio',false,false,'medio','mixto',null,'Plataformas de pesca de madera sobre el mar entre Ortona, San Vito y Fossacesia; algunas funcionan hoy como restaurantes.','Si queréis comer en un trabocco, reservad con antelación en temporada.','https://www.italia.it/it/abruzzo/cosa-fare/costa-dei-trabocchi','oficial','https://www.google.com/maps/search/?api=1&query=Costa+dei+Trabocchi%2C+San+Vito+Chietino%2C+Italia','https://www.italia.it/it/abruzzo/cosa-fare/costa-dei-trabocchi',42.29,14.46);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','via-verde-bici','san-vito-chietino','Ciclovía de la costa (Bike to Coast)','Costa dei Trabocchi','aventura',array['naturaleza','agua']::text[],'medio_dia','manana','bajo',false,false,'medio','mixto',array[4,5,6,7,8,9,10]::int[],'Tramos de la ciclovía de 131 km que recorre la costa abruzesa, en parte sobre la vieja vía del tren, con calas y trabocchi al lado.','Algunos tramos tienen problemas de seguridad o cortes: mirad el estado antes de alquilar bici.','https://www.italia.it/it/abruzzo/cosa-fare/ciclovia-bike-to-coast-in-abruzzo','oficial','https://www.google.com/maps/search/?api=1&query=Via+Verde+Costa+dei+Trabocchi%2C+Fossacesia%2C+Italia','https://www.italia.it/it/abruzzo/cosa-fare/ciclovia-bike-to-coast-in-abruzzo',42.244,14.481);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','trabocco-turchino','san-vito-chietino','Atardecer en el Trabocco del Turchino','San Vito Chietino','postal',array['naturaleza']::text[],'2h','noche','gratis',false,false,'bajo','tranquilo',null,'El trabocco más fotografiado de la costa, junto a San Vito Chietino, con el Eremo Dannunziano cerca; se ve a pie y mejor al caer el sol.',null,'https://www.italia.it/it/abruzzo/cosa-fare/costa-dei-trabocchi','oficial','https://www.google.com/maps/search/?api=1&query=Trabocco+Turchino%2C+San+Vito+Chietino%2C+Italia','https://www.italia.it/it/abruzzo/cosa-fare/costa-dei-trabocchi',42.307,14.453);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','punta-aderci','san-vito-chietino','Punta Aderci y Punta Penna','Vasto','naturaleza',array['playa','postal']::text[],'dia_completo','cualquiera','gratis',true,false,'medio','tranquilo',array[5,6,7,8,9]::int[],'Reserva natural con acantilados bajos, playas casi salvajes y trabocchi; está al sur de la costa, más cerca de Vasto que de San Vito.',null,'https://www.italia.it/it/abruzzo/chieti/punta-aderci','oficial','https://www.google.com/maps/search/?api=1&query=Riserva+Naturale+Punta+Aderci%2C+Vasto%2C+Italia','https://www.italia.it/it/abruzzo/chieti/punta-aderci',42.172,14.708);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','ortona-castillo','san-vito-chietino','Castillo aragonés de Ortona','Ortona','cultura',array['postal']::text[],'2h','tarde','bajo',false,false,'bajo','tranquilo',null,'Fortaleza del siglo XV sobre el mar, en una ciudad portuaria con estación de tren.',null,'https://www.italia.it/it/abruzzo/chieti/castello-aragonese-ortona','oficial','https://www.google.com/maps/search/?api=1&query=Castello+Aragonese%2C+Ortona%2C+Italia','https://www.italia.it/it/abruzzo/chieti/castello-aragonese-ortona',42.355,14.405);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','laquila-centro','laquila','L''Aquila: Collemaggio y las 99 Cannelle','L''Aquila','cultura',array['postal']::text[],'medio_dia','manana','bajo',false,false,'bajo','tranquilo',null,'Basílica de Santa Maria di Collemaggio, con la Puerta Santa de la Perdonanza, y la fuente medieval de las 99 Cannelle.','Parte del centro sigue en reconstrucción tras el terremoto de 2009.','https://www.italia.it/it/abruzzo/l-aquila/musei/basilica-di-santa-maria-di-collemaggio','oficial','https://www.google.com/maps/search/?api=1&query=Basilica+di+Santa+Maria+di+Collemaggio%2C+L%27Aquila%2C+Italia','https://www.italia.it/it/abruzzo/l-aquila/musei/basilica-di-santa-maria-di-collemaggio',42.343,13.411);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','laquila-noche','laquila','Aperitivo en el centro de L''Aquila','L''Aquila','fiesta',null,'2h','noche','bajo',false,false,'bajo','social',null,'Ambiente universitario de plazas y calles del centro histórico, con aperitivo y copas.',null,'https://www.google.com/maps/search/?api=1&query=Piazza+Duomo%2C+L%27Aquila%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Piazza+Duomo%2C+L%27Aquila%2C+Italia','https://www.google.com/maps/search/?api=1&query=Piazza+Duomo%2C+L%27Aquila%2C+Italia',42.351,13.398);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','campo-imperatore','laquila','Campo Imperatore: el pequeño Tíbet','Campo Imperatore','naturaleza',array['postal','aventura']::text[],'dia_completo','cualquiera','bajo',true,false,'medio','tranquilo',array[6,7,8,9,10]::int[],'Meseta de altura del Gran Sasso con praderas, rebaños y rutas a pie o en bici; se llega por carretera desde Fonte Cerreto o Castel del Monte.','La funivia de Fonte Cerreto estuvo cerrada por obras en 2025: comprobad si funciona.','https://www.italia.it/it/abruzzo/cosa-fare/castel-del-monte-campo-imperatore-in-bici','oficial','https://www.google.com/maps/search/?api=1&query=Campo+Imperatore%2C+L%27Aquila%2C+Italia','https://www.italia.it/it/abruzzo/cosa-fare/castel-del-monte-campo-imperatore-in-bici',42.44,13.56);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','campo-imperatore-esqui','laquila','Esquí en Campo Imperatore','Campo Imperatore','aventura',array['naturaleza']::text[],'dia_completo','manana','alto',true,false,'alto','social',array[12,1,2,3]::int[],'Unos 15 km de pistas en el Gran Sasso, con nieve fiable de noviembre a abril según el turismo regional; ambiente más tranquilo que Roccaraso.','Comprobad antes qué accesos y remontes están abiertos esa temporada.','https://turismo.abruzzo.it/en/skiing-in-abruzzo-best-resorts/','oficial','https://www.google.com/maps/search/?api=1&query=Campo+Imperatore%2C+L%27Aquila%2C+Italia','https://turismo.abruzzo.it/en/skiing-in-abruzzo-best-resorts/',42.44,13.56);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','roccaraso-esqui','sulmona','Esquí en Roccaraso y Aremogna','Roccaraso','aventura',array['naturaleza','fiesta']::text[],'dia_completo','manana','alto',false,true,'alto','social',array[12,1,2,3]::int[],'La mayor estación del centro de Italia, con 147 km de pistas y 38 remontes según el turismo regional. Un día en bus o tren desde Sulmona.','En fines de semana de nieve hay mucha gente: madrugad y reservad el forfait y el material.','https://turismo.abruzzo.it/en/skiing-in-abruzzo-best-resorts/','oficial','https://www.google.com/maps/search/?api=1&query=Aremogna%2C+Roccaraso%2C+Italia','https://turismo.abruzzo.it/en/skiing-in-abruzzo-best-resorts/',41.857,14.08);
