insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','sulmona-confetti','sulmona','Sulmona: centro y museo de los confetti','Sulmona','cultura',array['gastronomia']::text[],'medio_dia','cualquiera','bajo',false,false,'bajo','tranquilo',null,'Paseo por el centro medieval y visita al museo del arte confitero; Sulmona es la ciudad de los confetti, almendras bañadas en azúcar.',null,'https://cultura.gov.it/luogo/museo-dell-arte-e-della-tecnologia-confettiera','oficial','https://www.google.com/maps/search/?api=1&query=Museo+dell%27Arte+Confettiera%2C+Sulmona%2C+Italia','https://cultura.gov.it/luogo/museo-dell-arte-e-della-tecnologia-confettiera',42.047,13.926);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('abruzos','eremo-sant-onofrio','sulmona','Ermita de Sant''Onofrio al Morrone','Sulmona','cultura',array['naturaleza']::text[],'medio_dia','manana','bajo',false,false,'medio','tranquilo',null,'Ermita de Celestino V en la ladera del Morrone, con oratorio frescado y mirador sobre el valle Peligno.','La web oficial no da horarios: preguntad antes en la oficina de turismo de Sulmona.','https://www.italia.it/it/abruzzo/eremo-sant-onofrio-morrone-sulmona','oficial','https://www.google.com/maps/search/?api=1&query=Eremo+di+Sant%27Onofrio+al+Morrone%2C+Sulmona%2C+Italia','https://www.italia.it/it/abruzzo/eremo-sant-onofrio-morrone-sulmona',42.054,13.96);
