insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('molise','IT','Molise','Molise','La región que casi nadie visita','{"mar":1,"montana":1,"ciudad":0,"campo":3,"fiesta":1,"calma":3,"cultura":2,"gastronomia":2,"naturaleza":2,"playa":1,"aventura":0,"postal":2}'::jsonb,'bajo','{"ideales":[5,6,9],"aceptables":[4,7,10,12,1,2,3],"evitar":[8],"nota":"Mayo, junio y septiembre para la playa de Termoli y el interior suave. En agosto Termoli se llena; el interior es duro en invierno, con nieve en Capracotta."}'::jsonb,'alto',true,'{"necesidad":"imprescindible","nota":"Sin coche solo funcionan bien Termoli y Campobasso, unidas por tren. Agnone, Sepino, Pietrabbondante y los lagos del interior tienen transporte público escaso. No hay aeropuerto propio: lo normal es recoger el coche en Pescara.","aeropuerto_recogida":"PSR","operadores":[{"nombre":"Hertz","enlace":"https://www.momondo.es/alquiler-de-coches/Hertz-Pescara.PSR.HERTZ.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Hertz-Pescara.PSR.HERTZ.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Pescara.PSR.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Pescara.PSR.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Pescara.PSR.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Pescara.PSR.AVIS.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"PSR","nombre":"Pescara – Abruzzo","ciudad":"Pescara","a_la_base":"Molise no tiene aeropuerto propio. Desde Pescara se llega a Termoli por la línea adriática o en FlixBus (Pescara aparece en la web de FlixBus de Termoli), o en coche de alquiler."},{"iata":"BRI","nombre":"Bari – Karol Wojtyła","ciudad":"Bari","a_la_base":"Opción alternativa y más lejana: Bari tiene FlixBus a Termoli según su web. No verifiqué tiempos."}],"desde_espana":"No hay vuelos directos a Molise. Lo habitual es volar a Pescara (Ryanair ha volado Valencia–Pescara) o a Roma o Bari, y seguir en coche, bus o tren hasta Termoli.","rutas_directas":[{"origen":"Valencia","origen_iata":"VLC","destino_iata":"PSR","aerolinea":"Ryanair","nota":"llega a Pescara, no a Molise; ruta anunciada como nueva en invierno 2025, comprobad vigencia","fuente":"https://corporate.ryanair.com/novita/ryanair-annuncia-una-crescita-record-per-labruzzo/"}],"desde_italia":"A Termoli llegan FlixBus desde Roma, Bolonia, Milán, Florencia, Nápoles, Bari y Pescara (según su web) y trenes de la línea adriática. Desde Termoli, tren regional a Campobasso.","novedades":[]}'::jsonb,'{"resumen":"Termoli y Campobasso se unen en tren y se hacen a pie. Para Agnone, Sepino, Pietrabbondante o los lagos, coche: los buses del interior pasan poco.","tren":{"nota":"Trenitalia: línea adriática hasta Termoli y regional Termoli–Campobasso, de aproximadamente 1 h 50 min según datos previos. El interior tiene muy pocos servicios.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Termoli tiene una parada (Termoli Terminal Bus) con conexiones a Roma, Bari, Nápoles, Pescara, Bolonia y Milán. Para el interior hay bus regional con pocas salidas.","enlace":"https://www.flixbus.it/autobus/termoli","fuente":"https://www.flixbus.it/autobus/termoli"},"ferry":[{"operador":"NLG – Navigazione Libera del Golfo","ruta":"Termoli – Islas Tremiti","nota":"Barco rápido a San Domino y San Nicola; las salidas dependen de la temporada, comprobad al reservar.","enlace":"https://www.traghetti.com/navigazione-libera-del-golfo/termoli-tremiti","fuente":"https://www.traghetti.com/navigazione-libera-del-golfo/termoli-tremiti"}],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia; enlace a la página general.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Molise es pequeña y sin aeropuerto: hay que combinar vuelo a Pescara con coche, bus o tren, y se nota en tiempo.","Sin coche solo se aprovechan bien Termoli y Campobasso; Agnone, Sepino y los lagos piden coche.","No hay vuelos directos desde España a la región; la única referencia verificada llega a Pescara.","No verifiqué horarios de los barcos a las Tremiti ni la temporada exacta; tampoco los buses del interior.","No pude confirmar si se puede nadar en el lago de Castel San Vincenzo ni los horarios de la fundición Marinelli.","Capracotta es sobre todo esquí de fondo y depende de la nieve; no hay estación grande.","Fechas de 2027 no publicadas en fuentes oficiales: proxima_fecha en null.","Aperitivo en Campobasso y playa de Termoli apoyados en mapa o fuentes generales; no hay web oficial verificada.","Coordenadas de geo aproximadas a 3 decimales."]'::jsonb,'{"zona":"molise","base":"termoli","ciudad_referencia":"Termoli","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":null,"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Termoli-Molise-Italy","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche null: Hostelworld muestra 0 hostels en Termoli. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/termoli.html?selected_currency=EUR: precio ''From'' del titulo = 53 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Termoli (sin rango en Numbeo). transporte_billete null: Termoli no tiene red urbana relevante documentada en una fuente abierta; no se encontro tarifa."}'::jsonb);
insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('molise','termoli','Termoli','Casco antiguo sobre el mar, playa de arena, estación de tren y FlixBus; la única base cómoda sin coche.','mixto',true);
