insert into public.lib_bases(destino_id,id,nombre,por_que,ambiente,sin_coche) values ('molise','agnone','Agnone','Pueblo de campanas y salchichas en el Alto Molise, a pocos km de Pietrabbondante y Capracotta; hace falta coche.','calma',false);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','termoli-borgo','termoli','Borgo antico de Termoli: catedral y castillo suevo','Termoli','cultura',array['postal']::text[],'2h','tarde','gratis',false,false,'bajo','mixto',null,'Ciudadela sobre el Adriático con la catedral del siglo XII, el castillo suevo y Vico Il Castello, una de las calles más estrechas de Europa.',null,'https://fondoambiente.it/luoghi/borgo-antico-termoli','oficial','https://www.google.com/maps/search/?api=1&query=Borgo+antico%2C+Termoli%2C+Italia','https://fondoambiente.it/luoghi/borgo-antico-termoli',42.001,14.997);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','termoli-playa','termoli','Playa de Termoli','Termoli','playa',null,'medio_dia','cualquiera','bajo',false,false,'bajo','social',array[6,7,8,9]::int[],'Playa larga de arena junto a la ciudad, con establecimientos de pago y tramos libres; el plan de verano de la región.',null,'https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Sant%27Antonio%2C+Termoli%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Spiaggia+di+Sant%27Antonio%2C+Termoli%2C+Italia','https://www.spiagge.it/stabilimenti-balneari/termoli/',42.008,14.986);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','termoli-trabucco','termoli','Atardecer junto al trabucco de Termoli','Termoli','postal',array['naturaleza']::text[],'2h','noche','gratis',false,false,'bajo','tranquilo',null,'Paseo por las murallas del borgo y el puerto, con los trabucchi, las plataformas de pesca de madera, y la luz del atardecer.',null,'https://travel.thewom.it/italia/molise/termoli-cosa-vedere.html','oficial','https://www.google.com/maps/search/?api=1&query=Trabucco%2C+Termoli%2C+Italia','https://travel.thewom.it/italia/molise/termoli-cosa-vedere.html',42.002,14.999);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','termoli-noche','termoli','Aperitivo en el borgo y el lungomare de Termoli','Termoli','fiesta',array['gastronomia']::text[],'2h','noche','bajo',false,false,'bajo','social',null,'Aperitivo en las callejas del borgo y paseo por el paseo marítimo; en verano hay más ambiente, fuera de temporada es tranquilo.',null,'https://www.spiagge.it/magazine/scoprire-termoli-posti-imperdibili-estate-1/','oficial','https://www.google.com/maps/search/?api=1&query=Lungomare+Cristoforo+Colombo%2C+Termoli%2C+Italia','https://www.spiagge.it/magazine/scoprire-termoli-posti-imperdibili-estate-1/',42.003,14.995);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','tremiti','termoli','Islas Tremiti desde Termoli','Islas Tremiti','agua',array['naturaleza','postal']::text[],'dia_completo','manana','medio',false,true,'medio','social',array[6,7,8,9]::int[],'Barco rápido desde Termoli a San Domino y San Nicola: calas de agua clara, cuevas y el monasterio fortificado.','Las salidas cambian por temporada y el barco puede cancelarse por mal tiempo: comprobad horario de vuelta.','https://www.traghetti.com/navigazione-libera-del-golfo/termoli-tremiti','reserva','https://www.google.com/maps/search/?api=1&query=Isole+Tremiti%2C+Italia','https://www.traghetti.com/navigazione-libera-del-golfo/termoli-tremiti',42.123,15.49);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','larino-anfiteatro','termoli','Larino: anfiteatro romano y casco medieval','Larino','cultura',array['postal']::text[],'dia_completo','manana','gratis',true,false,'bajo','tranquilo',null,'Anfiteatro romano de casi 100 m de eje mayor, foro, termas con mosaicos y la basílica de San Pardo en el pueblo alto.','Larino queda a unos 30 km de Termoli; id con coche y reservad una mañana.','https://www.italia.it/en/molise/campobasso/larino','oficial','https://www.google.com/maps/search/?api=1&query=Anfiteatro+romano%2C+Larino%2C+Italia','https://www.italia.it/en/molise/campobasso/larino',41.805,14.919);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','campobasso-monforte','campobasso','Castillo Monforte de Campobasso','Campobasso','cultura',array['postal']::text[],'2h','tarde','bajo',false,false,'medio','tranquilo',null,'Fortaleza cuadrada con torres cilíndricas en lo alto de la ciudad, con vistas a las colinas y, en días claros, al Matese.','Según italia.it, cierra los lunes.','https://www.italia.it/it/molise/campobasso/luoghi-della-cultura/castello-monforte','oficial','https://www.google.com/maps/search/?api=1&query=Castello+Monforte%2C+Campobasso%2C+Italia','https://www.italia.it/it/molise/campobasso/luoghi-della-cultura/castello-monforte',41.562,14.656);
insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','campobasso-misteri','campobasso','Museo de los Misteri de Campobasso','Campobasso','cultura',null,'2h','tarde','gratis',false,false,'bajo','tranquilo',null,'Trece máquinas procesionales del siglo XVIII con niños como figuras, que salen en Corpus Domini; la entrada es con ofrenda voluntaria.','Para grupos, horario de lunes a sábado de 16:00 a 18:00; otros horarios, con reserva.','https://fondoambiente.it/luoghi/museo-dei-misteri-campobasso-molise','oficial','https://www.google.com/maps/search/?api=1&query=Museo+dei+Misteri%2C+Via+Trento+3%2C+Campobasso%2C+Italia','https://fondoambiente.it/luoghi/museo-dei-misteri-campobasso-molise',41.56,14.66);
