insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('molise','saepinum','campobasso','Saepinum: la ciudad romana de Altilia','Sepino','cultura',array['postal']::text[],'medio_dia','manana','bajo',true,false,'bajo','tranquilo',null,'Ciudad romana casi entera con murallas de más de 1 km, puertas monumentales, basílica y teatro; la llaman la pequeña Pompeya de Molise.','Según italia.it abre de martes a sábado, de 9:00 a 18:00.','https://www.italia.it/en/molise/sepino/cultural-places/atilia-saepinum-archaeological-area','oficial','https://www.google.com/maps/search/?api=1&query=Saepinum%2C+Altilia%2C+Sepino%2C+Italia','https://www.italia.it/en/molise/sepino/cultural-places/atilia-saepinum-archaeological-area',41.404,14.617);
