insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('valle-de-aosta','IT','Valle de Aosta (Courmayeur y Mont Blanc)','Valle de Aosta','Nieve, castillos y el Mont Blanc','{"mar":0,"montana":3,"ciudad":1,"campo":1,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":3,"playa":0,"aventura":3,"postal":3}'::jsonb,'alto','{"ideales":[1,2,3,7,8,9],"aceptables":[6,10,12],"evitar":[4,5,11],"nota":"Esquí de diciembre a marzo y senderos de julio a septiembre. Abril-mayo y noviembre son entretiempo: remontes y refugios cerrados en parte."}'::jsonb,'suave',true,'{"necesidad":"util","nota":"Aosta, Courmayeur y Pila se hacen en bus o remonte. Cogne, Cervinia y los castillos del valle son más cómodos con coche; en invierno, cadenas o neumáticos de invierno obligatorios.","aeropuerto_recogida":"TRN","operadores":[{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Turin.TRN.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Turin.TRN.EUROPCAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Turin.TRN.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Turin.TRN.AVIS.cla.ksp"},{"nombre":"Enterprise","enlace":"https://www.momondo.es/alquiler-de-coches/Enterprise-Turin.TRN.ENTERPRISE.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Enterprise-Turin.TRN.ENTERPRISE.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"TRN","nombre":"Turín – Caselle","ciudad":"Turín","a_la_base":"Bus o tren a Turín y de ahí tren a Aosta o FlixBus directo desde el aeropuerto; comprobad en la web."},{"iata":"MXP","nombre":"Milán Malpensa","ciudad":"Milán","a_la_base":"FlixBus tiene conexión Malpensa-Aosta según su página de Aosta; comprobad fechas."}],"desde_espana":"Vueling vuela Barcelona-Turín, la entrada más cómoda a Aosta. Si los vuelos no cuadran, mirad Milán Malpensa y Ginebra con bus.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"TRN","aerolinea":"Vueling","nota":"Ruta confirmada en la web de Vueling; las tarifas varían.","fuente":"https://www.vueling.com/es/vuelos-baratos-desde-turin"}],"desde_italia":"Desde Turín hay tren a Aosta (algo lento, con cambio). FlixBus conecta Aosta con Turín, Milán, Génova y Bolonia, entre otras."}'::jsonb,'{"resumen":"Sin coche: tren o FlixBus hasta Aosta y bus a Courmayeur. Con coche, Cogne, Cervinia y los castillos; en invierno, equipamiento de nieve.","tren":{"nota":"Línea Turín-Aosta con trenes regionales; los valles laterales no tienen tren.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Aosta tiene conexión directa con Turín, Milán, Malpensa, Génova y destinos europeos; los valles se hacen con bus local.","enlace":"https://www.flixbus.it/autobus/aosta","fuente":"https://www.flixbus.it/autobus/aosta"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de campers en Italia; en invierno mejor alojamiento fijo.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Webs bloqueadas a bots (Parque Gran Paradiso, Forte di Bard, Pila, termas Pré-Saint-Didier): enlazamos a lovevda.it y courmayeurmontblanc.it y a mapas.","Pila y Cogne: acceso sin coche (remonte desde Aosta, bus) no verificado en fuente oficial.","Eventos flojos: ninguno con fecha 2027 publicada; el calendario de ferias (Saint-Ours, mercadillo navideño) no se pudo verificar.","Sin precios ni horarios de remontes; confirmad en las webs oficiales."]'::jsonb,'{"zona":"valle-de-aosta","base":"aosta","ciudad_referencia":"Aosta","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":null,"comida_barata":{"valor":18,"fuente":"https://www.numbeo.com/cost-of-living/in/Aosta?displayCurrency=EUR","calidad":"orientativo"},"transporte_billete":null},"notas":"hostel_noche null: Hostelworld muestra 0 hostels en Aosta. doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/aosta.html?selected_currency=EUR: precio ''From'' del titulo = 65 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Aosta (rango Numbeo 14-30). transporte_billete null: No se encontro tarifa urbana oficial de Aosta en las paginas abiertas."}'::jsonb);
