insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('marcas','IT','Las Marcas (Ancona, Conero, Urbino)','Las Marcas','Calas blancas y ciudades sin masas','{"mar":3,"montana":1,"ciudad":2,"campo":2,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":2,"playa":2,"aventura":1,"postal":2}'::jsonb,'bajo','{"ideales":[5,6,9],"aceptables":[4,7,10],"evitar":[8],"nota":"Mayo-junio y septiembre dan playa sin agobio; en agosto la costa se llena y sube el precio."}'::jsonb,'alto',false,'{"necesidad":"util","nota":"Ancona, Loreto y las playas del Conero en verano se hacen sin coche. Urbino, Ascoli, Frasassi y los Sibilinos van mucho mejor con coche; cuidado con las ZTL de los cascos históricos.","aeropuerto_recogida":"AOI","operadores":[{"nombre":"Budget","enlace":"https://www.momondo.es/alquiler-de-coches/Budget-Ancona.AOI.BUDGET.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Budget-Ancona.AOI.BUDGET.cla.ksp"},{"nombre":"Dollar","enlace":"https://www.momondo.es/alquiler-de-coches/Dollar-Ancona.AOI.DOLLAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Dollar-Ancona.AOI.DOLLAR.cla.ksp"},{"nombre":"Avis","enlace":"https://www.rentcars.com/es/rentadora/avis/italy/aeropuertos/aoi-ancona-provincia-di-ancona","fuente":"https://www.rentcars.com/es/rentadora/avis/italy/aeropuertos/aoi-ancona-provincia-di-ancona"}]}'::jsonb,'{"aeropuertos":[{"iata":"AOI","nombre":"Ancona – Falconara (Raffaello Sanzio)","ciudad":"Ancona","a_la_base":"Falconara está a unos 15 km de Ancona; hay tren, bus o taxi. Comprobad horarios en la web del aeropuerto."}],"desde_espana":"Volotea conecta Ancona con Barcelona y ha operado una ruta estacional con Madrid. Como alternativa, Bolonia o Roma con Ryanair y tren o FlixBus.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"AOI","aerolinea":"Volotea","nota":"Dos frecuencias semanales según el aeropuerto; comprobad vigencia en la web de Volotea.","fuente":"https://www.ancona-airport.com/en/informazioni/7101/"}],"desde_italia":"Ancona está en la línea ferroviaria adriática: se llega en tren regional o Frecciarossa desde Bolonia y con cambios desde Roma. FlixBus también para en Ancona.","novedades":[{"nota":"Ruta estacional Ancona-Madrid con Volotea según el comunicado del aeropuerto; comprobad si sigue en la web de Volotea.","fuente":"https://www.ancona-airport.com/en/informazioni/7101/"}]}'::jsonb,'{"resumen":"Sin coche, la costa adriática y Loreto se hacen en tren y el Conero con buses locales en verano. Urbino, Frasassi y los Sibilinos piden coche o buses lentos.","tren":{"nota":"Línea adriática con trenes frecuentes entre Ancona, Pesaro, Loreto y San Benedetto del Tronto.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Conexiones de larga distancia con Ancona.","enlace":"https://www.flixbus.it/autobus/ancona","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":null}'::jsonb,'["No se pudieron abrir webs oficiales (frasassi.com, parques, museos) en esta sesión: casi todos los enlaces son de mapa o búsqueda segura.","Horarios de buses locales del Conero y Ascoli sin verificar.","Fechas de Quintana, Festa dell''Aquilone y Castelluccio sin fuente oficial; son orientativas.","Tras el terremoto de 2016, los accesos a Castelluccio pueden cambiar.","Sin locales concretos por falta de fuentes."]'::jsonb,'{"zona":"marcas","base":"ancona","ciudad_referencia":"Ancona","fecha_consulta":"2026-11-11","datos":{"hostel_noche":null,"doble_noche":null,"comida_barata":{"valor":15,"fuente":"https://www.numbeo.com/cost-of-living/in/Ancona","calidad":"orientativo"},"transporte_billete":{"valor":1.6,"fuente":"https://www.conerobus.it/tariffe/tariffe-urbane-ed-extraurbane/tariffe-urbano-ancona/","calidad":"verificado"}},"notas":"hostel_noche null: Hostelworld Ancona solo lista un hotel sin dormitorios (\"No Dorms Available\"). doble_noche null: solo hay un dato suelto (Booking.com https://www.booking.com/city/it/ancona.html?selected_currency=EUR: precio ''From'' del titulo = 62 EUR) y BudgetYourTrip no tiene media para esta ciudad, asi que no se puede dar rango. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Ancona (rango Numbeo 8-25). transporte_billete: Conerobus Ancona, billete 60 min 1.60 EUR (100 min = 1.80; a bordo 3.60; maquina 2.00)."}'::jsonb);
