insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('marcas','portonovo','ancona','Bahía de Portonovo','Portonovo','playa',array['naturaleza','postal']::text[],'dia_completo','manana','bajo',false,false,'bajo','social',array[5,6,7,8,9]::int[],'Bahía de guijarros blancos con agua clara bajo el monte Conero, la iglesia románica de Santa Maria y el Fortino Napoleonico.','En temporada hay bus desde Ancona y el aparcamiento se llena pronto; comprobad horarios del bus local antes de ir.','https://www.google.com/maps/search/?api=1&query=Portonovo%2C+Ancona%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Portonovo%2C+Ancona%2C+Italia','https://www.google.com/maps/search/?api=1&query=Portonovo%2C+Ancona%2C+Italia',43.55,13.62);
