insert into public.lib_actividades(destino_id,id,base_id,nombre,donde,tipo,tipos_extra,duracion,momento,coste,requiere_coche,requiere_reserva,esfuerzo,ambiente,meses,descripcion,consejo,enlace,enlace_tipo,maps,fuente,lat,lon) values ('marcas','sendero-monte-conero','sirolo','Senderos del Monte Conero','Parque del Conero','naturaleza',array['aventura']::text[],'medio_dia','manana','gratis',false,false,'medio','mixto',null,'Rutas entre bosque y acantilados del Parco del Conero, con miradores sobre el mar desde Sirolo, Numana o Portonovo.','Mejor primavera y otoño; en pleno verano salid temprano por el calor.','https://www.google.com/maps/search/?api=1&query=Parco+del+Conero%2C+Sirolo%2C+Italia','mapa','https://www.google.com/maps/search/?api=1&query=Parco+del+Conero%2C+Sirolo%2C+Italia','https://www.google.com/maps/search/?api=1&query=Parco+del+Conero%2C+Sirolo%2C+Italia',43.526,13.617);
