insert into public.lib_destinos(id,pais,nombre,nombre_corto,lema,perfil,nivel_precio,meses,calor_verano,nieve_invierno,coche,llegar,moverse,notas_honestas,costes) values ('trento','IT','Trento y valles del Trentino','Trento','Ciudad alpina, lago y Brenta','{"mar":0,"montana":2,"ciudad":2,"campo":2,"fiesta":1,"calma":2,"cultura":2,"gastronomia":2,"naturaleza":2,"playa":1,"aventura":2,"postal":2}'::jsonb,'medio','{"ideales":[5,6,9,12],"aceptables":[4,7,8,10,1,2,3],"evitar":[11],"nota":"Mayo-junio y septiembre para ciudad, Garda y rutas; diciembre para mercadillos y esquí. A finales de noviembre los mercados abren, pero las montañas están en entretiempo."}'::jsonb,'alto',true,'{"necesidad":"util","nota":"Trento, Levico y Riva se hacen en tren y bus. Para Val di Non, Lago di Tovel, Monte Bondone y Brenta el coche ahorra muchos transbordos; en la ciudad hay ZTL y aparcamientos de pago.","aeropuerto_recogida":"VRN","operadores":[{"nombre":"Sixt","enlace":"https://www.rentalcars.com/en/airport/it/vrn/sixt","fuente":"https://www.rentalcars.com/en/airport/it/vrn/sixt"},{"nombre":"Avis","enlace":"https://www.momondo.es/alquiler-de-coches/Avis-Verona.VRN.AVIS.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Avis-Verona.VRN.AVIS.cla.ksp"},{"nombre":"Europcar","enlace":"https://www.momondo.es/alquiler-de-coches/Europcar-Verona.VRN.EUROPCAR.cla.ksp","fuente":"https://www.momondo.es/alquiler-de-coches/Europcar-Verona.VRN.EUROPCAR.cla.ksp"}]}'::jsonb,'{"aeropuertos":[{"iata":"VRN","nombre":"Verona – Valerio Catullo","ciudad":"Verona","a_la_base":"Unos 90 km de Trento, aprox. 1 h por la A22 según Visit Trentino; en tren desde Verona Porta Nuova (hay servicio Verona Airlink aeropuerto–estación)."},{"iata":"BZO","nombre":"Bolzano – Dolomiti","ciudad":"Bolzano","a_la_base":"A 57 km de Trento; vuelos muy limitados (Air A!ps)."},{"iata":"BGY","nombre":"Bergamo – Orio al Serio","ciudad":"Bergamo","a_la_base":"A unos 180 km, 1 h 50 min por carretera según Visit Trentino; bus a la ciudad y a Milán."}],"desde_espana":"Lo más práctico es Verona con Volotea desde Barcelona y Madrid, y luego tren a Trento. Bergamo y Venecia dan más oferta low cost pero con trayecto más largo.","rutas_directas":[{"origen":"Barcelona","origen_iata":"BCN","destino_iata":"VRN","aerolinea":"Volotea","nota":"ruta existente según la prensa del sector; frecuencias y temporada sin verificar","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"},{"origen":"Madrid","origen_iata":"MAD","destino_iata":"VRN","aerolinea":"Volotea","nota":"ruta existente según la prensa del sector; frecuencias y temporada sin verificar","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"}],"desde_italia":"El tren regional Verona–Trento–Bolzano es la columna vertebral; FlixBus también para en Trento con conexiones por Italia.","novedades":[{"nota":"Volotea estrenó en 2026 Verona–Málaga (desde el 1 de agosto, martes y sábado) y Verona–Menorca (desde el 2 de agosto, jueves y domingo). Comprobad si siguen en 2027.","fuente":"https://www.quotidianomotori.com/volo/volotea-verona-nuove-rotte-2026/"}]}'::jsonb,'{"resumen":"Trento y Levico se hacen en tren; Riva del Garda y Campiglio, en bus regional. Para Val di Non, Tovel y Bondone, el coche manda.","tren":{"nota":"Trenitalia y Italo llegan hasta Verona; de ahí el tren regional sigue por el valle del Adigio a Trento, Bolzano y el Brennero.","enlace":"https://www.trenitalia.com/"},"bus":{"operador":"FlixBus","nota":"Trento tiene parada con conexiones a Turín, Florencia, Roma, Trieste y Treviso; no llega directo desde España.","enlace":"https://www.flixbus.it/autobus/trento","fuente":"https://www.flixbus.it/azienda/stampa/flixbus-offerta-estiva-2026"},"ferry":[],"camper":{"operador":"Roadsurfer","nota":"Alquiler de camper en Italia; solo hay página general del país, no de la zona. Encaja si queréis dormir sobre ruedas, pero en montaña el aparcamiento y los accesos tienen restricciones.","enlace":"https://roadsurfer.com/es/alquilar-camper/italia/","fuente":"https://roadsurfer.com/es/alquilar-camper/italia/"}}'::jsonb,'["Horarios y precios de buses regionales (Trento–Riva, Trento–Campiglio, Val di Non) sin verificar.","Lago di Tovel, Monte Bondone, San Romedio, Ponale y lago de Levico llevan mapa, no web oficial verificada.","Sentiero delle Bocchette y las ferratas: no he verificado accesos ni estado, solo nombre y dificultad general.","No hay rutas aéreas verificadas salvo Volotea a VRN; BZO y BGY sin ruta con fuente.","No he verificado enlaces de Civitatis ni Hostelworld para Trento."]'::jsonb,'{"zona":"trento","base":"trento","ciudad_referencia":"Trento","fecha_consulta":"2026-11-11","datos":{"hostel_noche":{"min":25,"max":25,"fuente":"https://www.hostelworld.com/st/hostels/europe/italy/trento/","calidad":"orientativo"},"doble_noche":{"min":75,"max":138,"fuente":"https://www.booking.com/city/it/trento.html?selected_currency=EUR | https://www.budgetyourtrip.com/italy/trento","calidad":"orientativo"},"comida_barata":{"valor":17,"fuente":"https://www.numbeo.com/cost-of-living/in/Trento","calidad":"orientativo"},"transporte_billete":{"valor":1.2,"fuente":"https://www.provincia.tn.it/content/download/20917/287832/file/Tariffario_servizi_trasporto_pubblico.pdf","calidad":"verificado"}},"notas":"hostel_noche: rango min-max de 1 precios ''Dorms From'' (EUR/cama) listados hoy en la pagina de ciudad de Hostelworld (minimo=25.0, maximo=25.0); son precios ''desde'' sin fechas concretas. Solo 1 hostel con precio de dorm; min=max. doble_noche: min=75 es el precio ''From'' mas bajo del titulo de la pagina de Booking.com para la ciudad (alojamiento mas barato listado, 2 adultos, 1 noche, sin fecha fija); max=138 es el precio medio de hotel para una pareja segun BudgetYourTrip (gasto declarado por viajeros). La horquilla mezcla ambas fuentes: es solo una guia aproximada, no un rango de apartamentos/dobles economicos garantizado. comida_barata: Numbeo ''Meal at an Inexpensive Restaurant'' en Trento (rango Numbeo 12-25). transporte_billete: Tarifario del transporte publico de la Provincia de Trento (actualizado oct-2025): billete urbano 70 min 1.20 EUR; a bordo 2.00. El documento no usa la etiqueta \"corsa semplice\"."}'::jsonb);
